          <p style={{ fontFamily: "monospace", fontSize: "10px", color: "#0088FF", margin: "0.5rem 0 0" }}>
            PRÓXIMO: {nextAgent.name}
          </p>
        </div>

        {/* JOURNEY HUB — jornada cognitiva completa */}
        <JourneyHub />

        {/* NARRATIVE SUGGESTIONS */}
        {narrativeSuggestions.length > 0 && (
          <section style={{ marginBottom: "2rem" }}>
            {narrativeSuggestions.map((suggestion, index) => (
              <NarrativeSuggestionCard
                key={`${suggestion.targetAgent}-${index}`}
                suggestion={suggestion}
                index={index}
                onSelect={(targetAgent) => router.push(`/universo/${targetAgent}`)}
              />
            ))}
          </section>
        )}

        {/* AGENT CARDS GRID */}
        <div style={{
          display: "grid",
          gridTemplateColumns: "repeat(3, 1fr)",
          gap: "1rem",
          marginBottom: "2.5rem",
        }}>
          {AGENTS.map((agent, i) => {
            const unlocked = i < completedCount;
            const count = presenceCounts[agent.id] || 0;
            const intensity = count >= 10 ? "urgent" : count >= 3 ? "moderate" : "subtle";
            return (
              <Link key={agent.id} href={`/universo/${agent.id}`} style={{ textDecoration: "none" }}>
                <div style={{
                  height: "220px",
                  backgroundImage: `url(${agent.image})`,
                  backgroundSize: 'cover',
                  backgroundPosition: 'center top',
                  border: `1px solid ${unlocked ? agent.color : "rgba(255,255,255,0.1)"}`,
                  borderRadius: "8px",
                  cursor: "pointer",
                  position: "relative",
                  overflow: "hidden",
                  transition: "all 0.3s ease",
                }}
                  onMouseEnter={e => {
                    (e.currentTarget as HTMLDivElement).style.boxShadow = `0 0 16px ${agent.color}40`;
                    (e.currentTarget as HTMLDivElement).style.transform = "scale(1.03)";
                  }}
                  onMouseLeave={e => {
                    (e.currentTarget as HTMLDivElement).style.boxShadow = "none";
                    (e.currentTarget as HTMLDivElement).style.transform = "scale(1)";
                  }}
                >
                  {/* Overlay escuro */}
                  <div style={{
                    position: "absolute", inset: 0,
                    background: "linear-gradient(to top, rgba(0,0,0,0.8) 0%, rgba(0,0,0,0.2) 50%, rgba(0,0,0,0.1) 100%)",
                  }} />
                  {/* Info no canto inferior */}
                  <div style={{ position: "absolute", bottom: "12px", left: "12px", right: "12px" }}>
                    <p style={{ fontFamily: "monospace", fontSize: "13px", color: agent.color, letterSpacing: "0.1em", margin: "0 0 2px", textTransform: "uppercase", textShadow: `0 0 8px ${agent.color}80` }}>
                      {agent.name}
                    </p>
                    <p style={{ fontFamily: "monospace", fontSize: "10px", color: "#9ca3af", margin: 0 }}>
                      {agent.faction}
                    </p>
                    <PresenceIndicator agentId={agent.id} count={count} color={agent.color} pulseIntensity={intensity} />
                  </div>
                </div>
              </Link>
            );
          })}
        </div>

        {/* QUICK ACTIONS */}
        <div style={{ display: "flex", gap: "1rem", flexWrap: "wrap", marginBottom: "2rem" }}>
          {[
            { label: "MAPA GALÁCTICO", href: "/universo" },
            { label: "EXPLORAR", href: "/explorar" },
            { label: "LABORATÓRIO", href: "/lab" },
            { label: "AGENTES", href: "/agentes" },
          ].map(btn => (
            <Link key={btn.href} href={btn.href} style={{ textDecoration: "none" }}>
              <button style={{
                background: "transparent",
                border: "1px solid rgba(0,255,255,0.3)",
                color: "#00FFFF", fontFamily: "monospace",
                fontSize: "11px", padding: "10px 20px",
                cursor: "pointer", letterSpacing: "0.1em",
                transition: "all 0.2s ease",
              }}
                onMouseEnter={e => {
                  (e.currentTarget as HTMLButtonElement).style.background = "rgba(0,255,255,0.1)";
                  (e.currentTarget as HTMLButtonElement).style.borderColor = "#00FFFF";
                }}
                onMouseLeave={e => {
                  (e.currentTarget as HTMLButtonElement).style.background = "transparent";
                  (e.currentTarget as HTMLButtonElement).style.borderColor = "rgba(0,255,255,0.3)";
                }}
              >
                {btn.label}
              </button>
            </Link>
          ))}
        </div>

        {/* UPGRADE PROMPT */}
        {showUpgrade && (
          <div style={{ textAlign: "center", padding: "2rem", border: "1px solid rgba(0,255,255,0.2)", borderRadius: "4px" }}>
            <p style={{ fontFamily: "monospace", color: "#00FF88", fontSize: "14px", margin: "0 0 1rem" }}>
              DESBLOQUEIE TODOS OS MUNDOS
            </p>
            <Link href="/planos">
              <button style={{
                background: "transparent",
                border: "1px solid #00FF88",
                color: "#00FF88", fontFamily: "monospace",
                fontSize: "11px", padding: "10px 24px",
                cursor: "pointer", letterSpacing: "0.1em",
              }}>
                UPGRADE
              </button>
            </Link>
          </div>
        )}

        {/* NEXUS PORTAL — Storyboard Cena 3 */}
        <section style={{
          backgroundImage: 'url(/images/storyboard/universe-entry.jpg)',
          backgroundSize: 'cover', backgroundPosition: 'center',
          minHeight: '200px', display: 'flex', alignItems: 'center',
          justifyContent: 'center', position: 'relative',
          borderRadius: '12px', overflow: 'hidden', marginTop: '2rem',
        }}>
          <div style={{ position: 'absolute', inset: 0, background: 'rgba(0,0,0,0.6)' }} />
          <Link href="/universo/nexus" style={{
            position: 'relative', display: "inline-flex", alignItems: "center", gap: "0.75rem",
            padding: "1rem 2.5rem",
            border: "1px solid rgba(0,255,255,0.3)", borderRadius: "8px",
            background: "rgba(0,255,255,0.05)", color: "#00FFFF",
            fontFamily: "monospace", fontSize: "14px",
            letterSpacing: "0.15em", textTransform: "uppercase", textDecoration: "none",
            transition: "all 0.3s ease",
          }}>
            ✦ ENTRAR NO UNIVERSO NEXUS
          </Link>
        </section>

      </main>
    </div>
    </HomeErrorBoundary>
  );
}

// ─── src/app/(main)/lab/LabPageClient.tsx ──────────────────────────────────
//
// Refactored UX: single-column flow
//   Hero → AgentSelector → TopicCarousel → ConversationArea
// No more 3-column grid. Attention flows top-to-bottom.

"use client";

import React, { useState, useEffect } from "react";
import type { Agent } from "@/types/agent";
import type { Topic } from "@/types/topic";
import { useAgent } from "@/hooks/useAgent";
import { useLabMode } from "@/hooks/useLabMode";
import { useChat } from "@/hooks/useChat";
import { LabHero } from "@/components/lab/LabHero";
import { LabModeToggle } from "@/components/lab/LabModeToggle";
import { AgentSelector } from "@/components/lab/AgentSelector";
import { TopicCarousel } from "@/components/lab/TopicCarousel";
import { ConversationArea } from "@/components/lab/ConversationArea";

/* ─── Props ──────────────────────────────────────────────────────────────── */

interface LabPageClientProps {
  agents: Agent[];
  topics: Topic[];
}

/* ─── Component ──────────────────────────────────────────────────────────── */

export function LabPageClient({ agents, topics }: LabPageClientProps) {
  const { activeAgent, activeAgentId, selectAgent } = useAgent();
  const { mode, toggleMode } = useLabMode();
  const { messages, isLoading, error, send, clearMessages } = useChat(activeAgentId);

  const [hasStarted, setHasStarted] = useState(false);

  const handleSend = (question: string) => {
    setHasStarted(true);
    send(question);
  };

  const handleClear = () => {
    clearMessages();
    setHasStarted(false);
  };

  // Generate particles only on client to avoid hydration mismatch
  const [particles, setParticles] = useState<{ left: string; bottom: string; duration: string; delay: string; width: string; height: string }[]>([]);
  useEffect(() => {
    setParticles(Array.from({ length: 30 }).map(() => ({
      left: `${Math.random() * 100}%`,
      bottom: `-${Math.random() * 20}px`,
      duration: `${15 + Math.random() * 25}s`,
      delay: `${Math.random() * 15}s`,
      width: `${1 + Math.random() * 2}px`,
      height: `${1 + Math.random() * 2}px`,
    })));
  }, []);

  const agentColor = activeAgent?.color ?? "#7C3AED";

  return (
    <div
      className="min-h-screen"
      style={{ background: "linear-gradient(180deg, #1E293B 0%, #0F172A 100%)" }}
    >
      {/* Particle background */}
      <div className="fixed inset-0 pointer-events-none overflow-hidden" aria-hidden="true">
        <style>{`
          @keyframes particle-drift {
            0% { transform: translateY(0) translateX(0); opacity: 0; }
            10% { opacity: 0.6; }
            90% { opacity: 0.6; }
            100% { transform: translateY(-100vh) translateX(20px); opacity: 0; }
          }
          .lab-particle {
            position: absolute;
            border-radius: 50%;
            background: rgba(148,163,184,0.4);
            animation: particle-drift linear infinite;
          }
        `}</style>
        {particles.map((p, i) => (
          <div
            key={i}
            className="lab-particle"
            style={{
              left: p.left,
              bottom: p.bottom,
              animationDuration: p.duration,
              animationDelay: p.delay,
              width: p.width,
              height: p.height,
            }}
          />
        ))}
      </div>

      {/* Main content — single column */}
      <div className="relative z-10 max-w-4xl mx-auto px-4 py-8 md:py-12">
        {/* 1. Hero */}
        <LabHero
          activeAgent={activeAgent}
          agentCount={agents.length}
          mode={mode}
          onSend={handleSend}
          isLoading={isLoading}
        />

        {/* 2. Mode Toggle */}
        <div className="flex justify-center mb-6">
          <LabModeToggle mode={mode} onToggle={toggleMode} />
        </div>

        {/* 3. Agent Pills */}
        <div className="mb-6">
          <AgentSelector
            agents={agents}
            activeAgentId={activeAgentId}
            onSelect={selectAgent}
          />
        </div>

        {/* 4. Topic Carousel — collapses to compact row when conversation active */}
        {!hasStarted ? (
          <TopicCarousel
            topics={topics}
            onSelect={handleSend}
            agentColor={agentColor}
          />
        ) : (
          <div className="mb-4">
            <TopicCarousel
              topics={topics}
              onSelect={handleSend}
              agentColor={agentColor}
              compact
            />
          </div>
        )}

        {/* 5. Conversation Area */}
        <div className="mt-6">
          <ConversationArea
            messages={messages}
            activeAgent={activeAgent}
            isLoading={isLoading}
            error={error}
            onSend={handleSend}
            onClear={handleClear}
            mode={mode}
          />
        </div>
      </div>
    </div>
  );
}

"use client";

import { use, useEffect, useCallback, useMemo } from "react";
import { useRouter, useSearchParams } from "next/navigation";
import { motion } from "framer-motion";
import { ArrowLeft, Trophy } from "lucide-react";
import { AgentPipeline } from "@/components/lab/AgentPipeline";
import { KnowledgeBoard } from "@/components/lab/KnowledgeBoard";
import { EventStream } from "@/components/lab/EventStream";
import { HumanIntervention } from "@/components/lab/HumanIntervention";
import { ExperimentResult } from "@/components/lab/ExperimentResult";
import { useExperimentEngine } from "@/hooks/useExperimentEngine";
import type { AgentNodeStatus } from "@/components/lab/AgentNode";
import { saveToLocalCache } from "@/lib/client-cache";
import { useCognitiveStore } from "@/store/useCognitiveStore";
import { toastError } from "@/lib/toast";
import dynamic from "next/dynamic";

const LabCanvas = dynamic(() => import("@/components/lab/LabCanvas"), { ssr: false });
const AgentChatOverlay = dynamic(() => import("@/components/lab/AgentChatOverlay"), { ssr: false });

const AGENT_ORDER = ["nexus", "cipher", "kaos", "aurora"];

function getAgentStatus(
  agentId: string,
  currentAgent: string,
  completedAgents: string[],
  phase: string
): AgentNodeStatus {
  if (completedAgents.includes(agentId)) return "completed";
  if (agentId === currentAgent && phase === "running") return "active";
  return "waiting";
}

export default function ExperimentPage({
  params,
}: {
  params: Promise<{ experimentId: string }>;
}) {
  const { experimentId } = use(params);
  const router = useRouter();
  const searchParams = useSearchParams();

  const {
    phase,
    currentAgent,
    agentOutputs,
    boardFacts,
    events,
    error,
    history,
    rollbackUsed,
    runAll,
    executeAgent,
    pause,
    resume,
    injectIdea,
    rollback,
    stop,
    loadCachedResult,
    setMode,
  } = useExperimentEngine(experimentId === "cached" ? null : experimentId);

  // ── Cognitive decay tick ─────────────────────────────────────────────────────
  useEffect(() => {
    const id = setInterval(() => {
      useCognitiveStore.getState().decayTick()
    }, 2000)
    return () => clearInterval(id)
  }, []);

  // ── Handle cached mode ─────────────────────────────────────────────
  const cacheData = useMemo(() => {
    if (experimentId !== "cached") return null;
    try {
      const raw = searchParams.get("data");
      return raw ? JSON.parse(decodeURIComponent(raw)) : null;
    } catch {
      return null;
    }
  }, [experimentId, searchParams]);

  // ── Read mode from URL ─────────────────────────────────────────────
  const modeParam = searchParams.get("mode") as "fast" | "full" | null;

  // AUTO-START: cached → load instantly; normal → run pipeline
  useEffect(() => {
    if (cacheData) {
      // Load cached result (zero API calls)
      loadCachedResult(cacheData);
      if (modeParam) setMode(modeParam);
      return;
    }

    if (experimentId && experimentId !== "cached" && phase === "idle") {
      if (modeParam) setMode(modeParam);
      runAll();
    }
  }, [experimentId, phase, runAll, cacheData, loadCachedResult, modeParam, setMode]);

  // Award XP on completion
  const awardXp = useCallback(async () => {
    try {
      await fetch("/api/xp/award", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          reason: "lab_experiment_complete",
          rollbackUsed,
        }),
      });
      // Fire conquest event
      window.dispatchEvent(
        new CustomEvent("mente_ai_conquest", {
          detail: {
            title: "🧪 Experimento concluído!",
            description: `+${15 + (rollbackUsed ? 5 : 0)} XP`,
          },
        })
      );
    } catch (error) { console.error('[MENTE.AI] Error in lab/experiment:', error); toastError('Erro ao conceder XP. O experimento foi salvo.'); }
  }, [rollbackUsed]);

  useEffect(() => {
    if (phase === "complete") {
      awardXp();
      // Save to localStorage for offline use
      if (experimentId !== "cached") {
        const topic = boardFacts[0] || "experimento";
        saveToLocalCache(topic, {
          nexus: agentOutputs["nexus"]?.narrative,
          cipher: agentOutputs["cipher"]?.narrative,
          kaos: agentOutputs["kaos"]?.narrative,
          aurora: agentOutputs["aurora"]?.narrative,
          board: boardFacts,
        });
      }
      // Update past experiments in localStorage
      try {
        const stored = localStorage.getItem("lab_experiments");
        if (stored) {
          const exps = JSON.parse(stored);
          const idx = exps.findIndex((e: any) => e.id === experimentId);
          if (idx >= 0) {
            exps[idx].completedAgents = 4;
            localStorage.setItem("lab_experiments", JSON.stringify(exps));
          }
        }
      } catch (error) { console.error('[MENTE.AI] Error in lab/experiment:', error); toastError('Erro ao conceder XP. O experimento foi salvo.'); }
    }
  }, [phase, experimentId, awardXp]);

  // Export report
  const handleExport = useCallback(() => {
    const topic = boardFacts.length > 0 ? "Experiment" : "Relatório";
    const tags = boardFacts.map((f) => `  • ${f}`).join("\n");
    const synthesis = agentOutputs["aurora"]?.narrative || "Síntese não disponível.";

    const report = [
      `╔══════════════════════════════════════════════╗`,
      `║   MENTE.AI LAB — RELATÓRIO DE EXPERIMENTO   ║`,
      `╚══════════════════════════════════════════════╝`,
      ``,
      `TEMA: ${topic}`,
      `DATA: ${new Date().toLocaleString("pt-BR")}`,
      ``,
      `──────────────────────────────────────────────`,
      `📋 QUADRO DE CONHECIMENTO`,
      `──────────────────────────────────────────────`,
      tags || "  (vazio)",
      ``,
      `──────────────────────────────────────────────`,
      `✨ SÍNTESE DE AURORA`,
      `──────────────────────────────────────────────`,
      synthesis,
      ``,
      `──────────────────────────────────────────────`,
      `AGENTES: NEXUS · CIPHER · KAOS · AURORA`,
      `XP: +${15 + (rollbackUsed ? 5 : 0)}`,
    ].join("\n");

    const blob = new Blob([report], { type: "text/plain;charset=utf-8" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `relatorio-lab-${experimentId.slice(0, 8)}.txt`;
    a.click();
    URL.revokeObjectURL(url);
  }, [boardFacts, agentOutputs, experimentId, rollbackUsed]);

  // Retry failed agent
  const handleRetryAgent = useCallback(
    async (agentId: string) => {
      await executeAgent(agentId);
    },
    [executeAgent]
  );

  const agents = AGENT_ORDER.map((id) => ({
    id,
    status: getAgentStatus(id, currentAgent, Object.keys(agentOutputs), phase),
  }));

  const isComplete = phase === "complete";
  const isRunning = phase === "running" || phase === "paused";

  return (
    <main
      className="min-h-screen flex flex-col"
      style={{ background: "#0e1420" }}
    >
      {/* Background */}
      <div className="fixed inset-0 pointer-events-none overflow-hidden z-0">
        <div
          className="absolute top-0 right-0 w-[600px] h-[600px] rounded-full blur-[120px] opacity-[0.03]"
          style={{ background: isComplete ? "#a78bfa" : "var(--accent-cyan)" }}
        />
      </div>

      {/* Top bar */}
      <header
        className="relative z-20 flex items-center justify-between px-6 py-4 border-b"
        style={{ borderColor: "rgba(255,255,255,0.04)" }}
      >
        <button
          onClick={() => {
            stop();
            router.push("/lab");
          }}
          className="flex items-center gap-2 text-white/25 hover:text-white/50 transition-colors text-xs"
        >
          <ArrowLeft size={14} />
          <span className="font-mono uppercase tracking-wider">← LAB</span>
        </button>

        <div className="flex items-center gap-3">
          <span
            className="text-[10px] font-mono uppercase tracking-[0.2em]"
            style={{ color: "var(--accent-cyan)" }}
          >
            EXPERIMENTO {experimentId.slice(0, 8)}
          </span>
          <span
            className={`w-2 h-2 rounded-full ${
              isComplete
                ? "bg-[#a78bfa]"
                : isRunning
                ? "animate-pulse bg-[var(--accent-cyan)]"
                : "bg-white/10"
            }`}
            style={{
              boxShadow: isComplete
                ? "0 0 8px #a78bfa80"
                : isRunning
                ? "0 0 8px rgba(0,245,255,0.5)"
                : "none",
            }}
          />
        </div>
      </header>

      {/* Main grid */}
      <div className="relative z-10 flex-1 grid grid-cols-1 lg:grid-cols-[220px_1fr_280px] gap-4 p-4">
        {/* LEFT — Agent Pipeline */}
        <aside className="order-2 lg:order-1">
          <div
            className="rounded-xl p-3 h-full"
            style={{
              background: "rgba(22, 29, 46, 0.5)",
              border: "1px solid rgba(255,255,255,0.03)",
            }}
          >
            <AgentPipeline agents={agents} onRetryAgent={handleRetryAgent} />
          </div>
        </aside>

        {/* CENTER — Active output */}
        <section className="order-1 lg:order-2 flex flex-col gap-4 min-h-0">
          {/* Active agent typewriter */}
          {currentAgent && agentOutputs[currentAgent] && !isComplete && (
            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              className="rounded-xl p-5 flex-1 overflow-y-auto"
              style={{
                background: "rgba(22, 29, 46, 0.5)",
                border: "1px solid rgba(255,255,255,0.03)",
              }}
            >
              <p
                className="text-[9px] font-mono uppercase tracking-[0.25em] mb-3"
                style={{ color: "var(--accent-cyan)" }}
              >
                🎙️ {agentOutputs[currentAgent].agentName} · {agentOutputs[currentAgent].agentRole}
              </p>
              <div
                className="text-sm leading-relaxed whitespace-pre-wrap font-mono"
                style={{ color: "rgba(255,255,255,0.7)" }}
              >
                {agentOutputs[currentAgent].narrative}
                <motion.span
                  animate={{ opacity: [1, 0] }}
                  transition={{ repeat: Infinity, duration: 0.8 }}
                  className="inline-block ml-0.5"
                  style={{ color: "var(--accent-cyan)" }}
                >
                  ▌
                </motion.span>
              </div>
            </motion.div>
          )}

          {/* Waiting for agent */}
          {currentAgent && !agentOutputs[currentAgent] && isRunning && (
            <div className="flex-1 flex items-center justify-center">
              <motion.div
                animate={{ opacity: [0.3, 0.7] }}
                transition={{ repeat: Infinity, duration: 1.5 }}
                className="text-center"
              >
                <span className="text-3xl block mb-3">
                  {currentAgent === "nexus"
                    ? "🧬"
                    : currentAgent === "cipher"
                    ? "🔍"
                    : currentAgent === "kaos"
                    ? "⚡"
                    : "✨"}
                </span>
                <p className="text-white/20 text-sm font-mono">
                  {currentAgent.toUpperCase()} está processando...
                </p>
              </motion.div>
            </div>
          )}

          {/* Complete: show result */}
          {isComplete && (
            <ExperimentResult
              topic={boardFacts[0] || "Experimento"}
              agentOutputs={agentOutputs}
              boardFacts={boardFacts}
              rollbackUsed={rollbackUsed}
              onExport={handleExport}
            />
          )}

          {/* Error state */}
          {error && (
            <div
              className="rounded-xl p-5 text-center"
              style={{
                background: "rgba(239,68,68,0.05)",
                border: "1px solid rgba(239,68,68,0.15)",
              }}
            >
              <p className="text-red-400 text-sm font-bold mb-2">Erro no agente</p>
              <p className="text-red-300/60 text-xs font-mono">{error}</p>
            </div>
          )}

          {/* Knowledge board (bottom of center) */}
          {boardFacts.length > 0 && (
            <KnowledgeBoard facts={boardFacts} />
          )}
        </section>

        {/* RIGHT — Event Stream + Human Intervention */}
        <aside className="order-3 flex flex-col gap-4">
          <EventStream events={events} />

          {/* Intervention — only while running */}
          {!isComplete && (
            <HumanIntervention
              phase={phase}
              history={history}
              onPause={pause}
              onResume={resume}
              onInjectIdea={injectIdea}
              onRollback={rollback}
            />
          )}

          {/* XP info on complete */}
          {isComplete && (
            <div
              className="rounded-xl p-4 text-center"
              style={{
                background: "rgba(22, 29, 46, 0.5)",
                border: "1px solid rgba(255,255,255,0.03)",
              }}
            >
              <Trophy size={20} className="mx-auto mb-2" style={{ color: "var(--accent-cyan)" }} />
              <p className="text-xs font-bold" style={{ color: "var(--accent-cyan)" }}>
                +{15 + (rollbackUsed ? 5 : 0)} XP
              </p>
              <p className="text-[9px] text-white/20 mt-1">Experimento concluído</p>
            </div>
          )}
        </aside>
      </div>

      <LabCanvas />
      <AgentChatOverlay />
    </main>
  );
}

"use client";
import { useState, useMemo, useEffect } from "react";
import { Eye, EyeOff } from "lucide-react";

/**
 * Stars — Background de estrelas animadas.
 * Posições geradas apenas no CLIENTE (useEffect) para evitar
 * hydration mismatch entre SSR e browser.
 */
function Stars() {
  const [mounted, setMounted] = useState(false);

  const stars = useMemo(() => {
    if (!mounted) return [];
    return Array.from({ length: 80 }, (_, i) => ({
      id: i,
      left: `${Math.random() * 100}%`,
      top: `${Math.random() * 100}%`,
      size: Math.random() * 1.5 + 0.5,
      duration: `${Math.random() * 3 + 2}s`,
      delay: `${Math.random() * 3}s`,
    }));
  }, [mounted]);

  useEffect(() => {
    setMounted(true);
  }, []);

  return (
    <div style={{ position: 'fixed', inset: 0, zIndex: 0, pointerEvents: 'none', overflow: 'hidden' }}>
      {stars.map((s) => (
        <div
          key={s.id}
          style={{
            position: 'absolute',
            left: s.left,
            top: s.top,
            width: `${s.size}px`,
            height: `${s.size}px`,
            borderRadius: '50%',
            background: '#ffffff',
            opacity: 0.2,
            animation: `starPulse ${s.duration} ease-in-out ${s.delay} infinite`,
          }}
        />
      ))}
      <style jsx>{`
        @keyframes starPulse {
          0%, 100% { opacity: 0.2; transform: scale(1); }
          50% { opacity: 0.8; transform: scale(1.3); }
        }
      `}</style>
    </div>
  );
}

export default function Login() {
  const [tab, setTab] = useState("entrar");
  const [nome, setNome] = useState("");
  const [email, setEmail] = useState("");
  const [senha, setSenha] = useState("");
  const [confirmar, setConfirmar] = useState("");
  const [loading, setLoading] = useState(false);
  const [erro, setErro] = useState("");
  const [sucesso, setSucesso] = useState("");
  const [verSenha, setVerSenha] = useState(false);
  const [verConfirmar, setVerConfirmar] = useState(false);

  async function handleSubmit(e?: React.FormEvent) {
    e?.preventDefault();
    setErro(""); setSucesso("");
    if (tab === "cadastrar" && senha !== confirmar) { setErro("As senhas nao coincidem."); return; }
    setLoading(true);
    try {
      const url = tab === "entrar" ? "/api/auth/login" : "/api/auth/register";
      const body = tab === "entrar" ? { email, senha } : { nome, email, senha };
      const res = await fetch(url, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body) });
      const data = await res.json();
      if (!res.ok) { setErro(data.error || "Erro ao processar."); }
      else { setSucesso(tab === "entrar" ? "Login realizado!" : "Cadastro realizado!"); setTimeout(() => { window.location.href = "/home"; }, 1000); }
    } catch { setErro("Erro de conexao."); } finally { setLoading(false); }
  }

  return (
    <main style={{
      minHeight: '100vh',
      display: 'flex',
      flexDirection: 'column',
      alignItems: 'center',
      justifyContent: 'center',
      padding: '2rem',
      background: '#000000',
      position: 'relative',
    }}>
      <Stars />

      <div style={{
        width: '100%',
        maxWidth: '420px',
        position: 'relative',
        zIndex: 1,
        animation: 'terminalAppear 800ms cubic-bezier(0.16,1,0.3,1) forwards',
        transform: 'scale(0.8)',
        opacity: 0,
      }}>
        <style jsx>{`
          @keyframes terminalAppear {
            to {
              transform: scale(1);
              opacity: 1;
            }
          }
          @keyframes blink {
            0%, 100% { opacity: 1; }
            50% { opacity: 0; }
          }
        `}</style>

        <p style={{
          textAlign: 'center',
          fontFamily: 'monospace',
          fontSize: '11px',
          color: '#00f5ff',
          opacity: 0.6,
          letterSpacing: '0.1em',
          marginBottom: '0.5rem',
        }}>
          NEXUS PRIME // CONSCIOUSNESS TERMINAL v2.1
        </p>

        <h1 style={{
          textAlign: 'center',
          fontSize: '20px',
          fontWeight: 900,
          color: '#ffffff',
          letterSpacing: '0.15em',
          marginBottom: '2rem',
        }}>
          MATERIALIZAR CONSCIÊNCIA
        </h1>

        <form onSubmit={handleSubmit} style={{
          background: 'rgba(0,0,0,0.8)',
          border: '1px solid rgba(0,245,255,0.3)',
          borderRadius: '4px',
          boxShadow: '0 0 40px rgba(0,245,255,0.1)',
          padding: '2rem',
        }}>
          {tab === "cadastrar" && (
            <input style={{
              width: '100%',
              padding: '0.75rem 1rem',
              marginBottom: '1rem',
              borderRadius: '4px',
              border: '1px solid rgba(0,245,255,0.2)',
              background: 'rgba(0,245,255,0.05)',
              color: '#ffffff',
              fontSize: '14px',
              fontFamily: 'monospace',
              outline: 'none',
              boxSizing: 'border-box',
              transition: 'border-color 200ms ease, box-shadow 200ms ease',
            } as React.CSSProperties}
              placeholder="Nome de identidade"
              value={nome}
              onChange={(e) => setNome(e.target.value)}
              autoComplete="name"
              onFocus={(e) => { e.currentTarget.style.borderColor = '#00f5ff'; e.currentTarget.style.boxShadow = '0 0 8px rgba(0,245,255,0.3)'; }}
              onBlur={(e) => { e.currentTarget.style.borderColor = 'rgba(0,245,255,0.2)'; e.currentTarget.style.boxShadow = 'none'; }}
            />
          )}

          <input style={{
            width: '100%',
            padding: '0.75rem 1rem',
            marginBottom: '1rem',
            borderRadius: '4px',
            border: '1px solid rgba(0,245,255,0.2)',
            background: 'rgba(0,245,255,0.05)',
            color: '#ffffff',
            fontSize: '14px',
            fontFamily: 'monospace',
            outline: 'none',
            boxSizing: 'border-box',
            transition: 'border-color 200ms ease, box-shadow 200ms ease',
          } as React.CSSProperties}
            type="email"
            placeholder="Identificação de consciência (email)"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            autoComplete="email"
            onFocus={(e) => { e.currentTarget.style.borderColor = '#00f5ff'; e.currentTarget.style.boxShadow = '0 0 8px rgba(0,245,255,0.3)'; }}
            onBlur={(e) => { e.currentTarget.style.borderColor = 'rgba(0,245,255,0.2)'; e.currentTarget.style.boxShadow = 'none'; }}
          />

          <div style={{ position: 'relative', marginBottom: tab === "cadastrar" ? '1rem' : '0' }}>
            <input style={{
              width: '100%',
              padding: '0.75rem 1rem',
              paddingRight: '3rem',
              borderRadius: '4px',
              border: '1px solid rgba(0,245,255,0.2)',
              background: 'rgba(0,245,255,0.05)',
              color: '#ffffff',
