        </motion.div>
      </motion.div>
    </AnimatePresence>

    {/* Modal de Mais Informações (estilo Netflix) */}
    <AgentInfoModal
      agent={agent}
      isOpen={infoOpen}
      onClose={() => setInfoOpen(false)}
    />
    </>
  );
}

