"use client";

import { motion, AnimatePresence } from "framer-motion";
import { useState, useEffect, useRef, useCallback } from "react";
import { type FlipBookLesson, ExplanationBlock } from "./mockData";
import { AnimatedVisualizer, getVisualizerForConcept, VisualizerBlock } from "./AnimatedVisualizer";
import {
  Brain,
  Network,
  Sparkles,
  Bot,
  Lightbulb,
  ChevronLeft,
  ChevronRight,
  Play,
  Pause,
  Volume2,
  Image as ImageIcon,
  Loader2,
  Sparkle,
  Wand2,
  Eye,
  EyeOff
} from "lucide-react";

// Icon mapping
const iconMap = {
  brain: Brain,
  network: Network,
  sparkle: Sparkles,
  robot: Bot,
  lightbulb: Lightbulb,
};

// Animated background particles
function BackgroundParticles() {
  return (
    <div className="fixed inset-0 overflow-hidden pointer-events-none z-0">
      {[...Array(25)].map((_, i) => (
        <motion.div
          key={i}
          className="absolute w-1 h-1 rounded-full"
          initial={{
            x: `${5 + (i * 4) % 90}%`,
            y: `${Math.random() * 100}%`,
            scale: 0
          }}
          animate={{
            y: [`${Math.random() * 100}%`, "-10vh"],
            opacity: [0, 0.8, 0],
            scale: [0, 1.5, 0],
            x: [`${(i * 4) % 90}%`, `${((i * 4) + 20) % 90}%`]
          }}
          transition={{
            duration: 8 + Math.random() * 12,
            repeat: Infinity,
            delay: Math.random() * 8,
            ease: "linear"
          }}
          style={{
            background: i % 3 === 0 ? "#00f0ff" : i % 3 === 1 ? "#a855f7" : "#ec4899"
          }}
        />
      ))}
    </div>
  );
}

// Animated Title Component with enhanced effects
function AnimatedTitle({ title, subtitle }: { title: string; subtitle: string }) {
  return (
    <div className="text-center mb-12 relative">
      <motion.div
        initial={{ opacity: 0, scale: 0.8 }}
        animate={{ opacity: 1, scale: 1 }}
        className="relative inline-block"
      >
        {/* Multiple glow layers */}
        <motion.div
          className="absolute -inset-8 bg-gradient-to-r from-cyan-500/20 via-purple-500/20 to-pink-500/20 blur-3xl"
          animate={{ scale: [1, 1.1, 1], opacity: [0.5, 0.8, 0.5] }}
          transition={{ duration: 4, repeat: Infinity }}
        />
        
        <motion.h1
          initial={{ y: -80, opacity: 0 }}
          animate={{ y: 0, opacity: 1 }}
          transition={{ type: "spring", stiffness: 60, damping: 12 }}
          className="relative text-6xl md:text-8xl font-black tracking-tight"
        >
          {/* Gradient text with animation */}
          <motion.span
            className="bg-gradient-to-r from-white via-cyan-200 to-purple-300 bg-clip-text text-transparent"
            animate={{
              backgroundPosition: ["0% 50%", "100% 50%", "0% 50%"]
            }}
            transition={{ duration: 5, repeat: Infinity }}
            style={{ backgroundSize: "200% 200%" }}
          >
            {title}
          </motion.span>
          
          {/* Sparkle effects around title */}
          {[...Array(8)].map((_, i) => (
            <motion.span
              key={i}
              className="absolute text-cyan-400"
              initial={{ opacity: 0, scale: 0 }}
              animate={{
                opacity: [0, 1, 0],
                scale: [0, 1.5, 0],
                rotate: [0, 180]
              }}
              transition={{
                duration: 2,
                delay: i * 0.25 + 0.5,
                repeat: Infinity,
                repeatDelay: 4
              }}
              style={{
                left: `${10 + i * 12}%`,
                top: `${i % 2 === 0 ? '-10%' : '110%'}`
              }}
            >
              ✨
            </motion.span>
          ))}
        </motion.h1>
      </motion.div>
      
      <motion.p
        initial={{ y: 30, opacity: 0 }}
        animate={{ y: 0, opacity: 1 }}
        transition={{ delay: 0.4, duration: 0.6 }}
        className="mt-6 text-2xl md:text-3xl text-white/60 font-light"
      >
        {subtitle}
