      {/* Animated underline */}
      <motion.div
        initial={{ scaleX: 0 }}
        animate={{ scaleX: 1 }}
        transition={{ delay: 0.8, duration: 1 }}
        className="mt-8 h-1 w-64 mx-auto bg-gradient-to-r from-transparent via-cyan-400 to-transparent rounded-full"
      />
    </div>
  );
}

