          }

          .spotlightPurple {
            transform: translate(calc(50vw - 520px), calc(50vh - 200px));
          }

          .nexusCopy p,
          .nexusCopy button {
            transform: none;
          }

          .portalOverlay,
          .portalText {
            display: none;
          }
        }
      `}</style>
    </section>
  );
}

"use client";

import { memo } from "react";
import Link from "next/link";
import { motion } from "framer-motion";
import { allAgents, type HomeAgent } from "@/data/agents";
import { getAgentImage, AGENT_IMAGE_FALLBACK } from "@/lib/getAgentImage";

const GLOW_COLORS: Record<string, string> = {
  nexus: "rgba(0,212,255,0.5)",
  volt: "rgba(251,191,36,0.5)",
  aurora: "rgba(236,72,153,0.5)",
  kaos: "rgba(239,68,68,0.5)",
  cipher: "rgba(16,185,129,0.5)",
