"use client";

import { useState } from "react";
import { motion } from "framer-motion";
import { Pause, Play, Lightbulb, Undo2, RotateCcw } from "lucide-react";
import type { ExperimentPhase } from "@/hooks/useExperimentEngine";

interface HumanInterventionProps {
  phase: ExperimentPhase;
  history: Array<{ agent: string; facts: string[]; timestamp: number }>;
  onPause: () => void;
  onResume: () => void;
  onInjectIdea: (idea: string) => void;
  onRollback: (targetStep: number, injectIdea?: string) => void;
}

export function HumanIntervention({
  phase,
  history,
  onPause,
  onResume,
  onInjectIdea,
  onRollback,
}: HumanInterventionProps) {
  const [ideaInput, setIdeaInput] = useState("");
  const [showRollback, setShowRollback] = useState(false);
  const [selectedStep, setSelectedStep] = useState<number | null>(null);

  const handleInject = () => {
    const idea = ideaInput.trim();
    if (!idea) return;
    onInjectIdea(idea);
    setIdeaInput("");
  };

  const handleRollback = () => {
    if (selectedStep === null) return;
    const idea = ideaInput.trim() || undefined;
    onRollback(selectedStep, idea);
    setShowRollback(false);
    setSelectedStep(null);
    setIdeaInput("");
  };

  const isRunning = phase === "running";
  const isPaused = phase === "paused";
  const isComplete = phase === "complete";

  return (
    <div
      className="rounded-xl p-3"
      style={{
        background: "rgba(14, 20, 32, 0.8)",
        border: "1px solid rgba(255,255,255,0.04)",
      }}
    >
      <p
        className="text-[9px] font-mono uppercase tracking-[0.25em] mb-3"
        style={{ color: "var(--accent-cyan)" }}
      >
        🎮 INTERVENÇÃO HUMANA
      </p>

      <div className="flex flex-wrap gap-2 mb-3">
        {/* Pause / Resume */}
        {!isComplete && (
          <button
            onClick={isRunning ? onPause : onResume}
            className="flex items-center gap-1.5 px-3 py-1.5 rounded-full text-[10px] font-bold transition-all duration-200 hover:brightness-125"
            style={{
              background: isRunning
                ? "rgba(255,107,53,0.1)"
                : "rgba(0,255,136,0.1)",
              color: isRunning ? "#ff6b35" : "#00ff88",
              border: `1px solid ${isRunning ? "rgba(255,107,53,0.2)" : "rgba(0,255,136,0.2)"}`,
            }}
          >
            {isRunning ? <Pause size={11} /> : <Play size={11} />}
            {isRunning ? "Pausar" : "Continuar"}
          </button>
        )}

        {/* Inject idea */}
        {!isComplete && (
          <button
            onClick={() => {
              if (ideaInput.trim()) handleInject();
            }}
            className="flex items-center gap-1.5 px-3 py-1.5 rounded-full text-[10px] font-bold transition-all duration-200 hover:brightness-125"
            style={{
              background: "rgba(167,139,250,0.1)",
              color: "#a78bfa",
              border: "1px solid rgba(167,139,250,0.2)",
            }}
          >
            <Lightbulb size={11} />
            Injetar ideia
          </button>
        )}

        {/* Rollback */}
        {history.length > 0 && (
          <button
            onClick={() => setShowRollback(!showRollback)}
            className="flex items-center gap-1.5 px-3 py-1.5 rounded-full text-[10px] font-bold transition-all duration-200 hover:brightness-125"
            style={{
              background: "rgba(255,255,255,0.03)",
              color: "rgba(255,255,255,0.4)",
              border: "1px solid rgba(255,255,255,0.06)",
            }}
          >
            <Undo2 size={11} />
            Voltar passo
          </button>
        )}
      </div>

      {/* Idea input */}
      {!isComplete && (
        <div className="flex gap-2 mb-2">
          <input
            type="text"
            value={ideaInput}
            onChange={(e) => setIdeaInput(e.target.value)}
            onKeyDown={(e) => e.key === "Enter" && handleInject()}
            placeholder="Injete uma ideia no experimento..."
            className="flex-1 px-3 py-1.5 rounded-full text-[10px] outline-none transition-all duration-200 focus:border-[var(--accent-cyan)]"
            style={{
              background: "rgba(255,255,255,0.03)",
              border: "1px solid rgba(255,255,255,0.06)",
              color: "rgba(255,255,255,0.6)",
            }}
          />
        </div>
      )}

      {/* Rollback selector */}
      {showRollback && (
        <motion.div
          initial={{ opacity: 0, height: 0 }}
          animate={{ opacity: 1, height: "auto" }}
          className="mt-2 pt-2 border-t border-white/[0.04]"
        >
          <p className="text-[9px] text-white/25 mb-2 font-mono uppercase tracking-wider">
            ⏮️ SELECIONE O PASSO PARA VOLTAR
          </p>
          <div className="space-y-1 mb-2 max-h-[120px] overflow-y-auto">
            {history.map((step, i) => (
              <button
                key={i}
                onClick={() => setSelectedStep(i)}
                className={`w-full text-left px-2.5 py-1.5 rounded-lg text-[10px] transition-all duration-150 ${
                  selectedStep === i ? "brightness-125" : ""
                }`}
                style={{
                  background:
                    selectedStep === i
                      ? "rgba(0,245,255,0.08)"
                      : "rgba(255,255,255,0.02)",
                  border:
                    selectedStep === i
                      ? "1px solid rgba(0,245,255,0.2)"
                      : "1px solid transparent",
                  color: "rgba(255,255,255,0.5)",
                }}
              >
                <span className="text-white/25 mr-2">Passo {i + 1}</span>
                <span
                  className="uppercase font-bold"
                  style={{
                    color:
                      step.agent === "nexus"
                        ? "#00f5ff"
                        : step.agent === "cipher"
                        ? "#00ff88"
                        : step.agent === "kaos"
                        ? "#ff6b35"
                        : step.agent === "aurora"
                        ? "#a78bfa"
                        : "#fff",
                  }}
                >
                  {step.agent}
                </span>
                <span className="text-white/15 ml-2">
                  {step.facts.length} descobertas
                </span>
              </button>
            ))}
          </div>
          <button
            onClick={handleRollback}
            disabled={selectedStep === null}
            className="w-full flex items-center justify-center gap-1.5 px-3 py-1.5 rounded-full text-[10px] font-bold transition-all duration-200 disabled:opacity-30"
            style={{
              background: "rgba(167,139,250,0.1)",
              color: "#a78bfa",
              border: "1px solid rgba(167,139,250,0.2)",
            }}
          >
            <RotateCcw size={11} />
            Confirmar rollback
          </button>
        </motion.div>
      )}
    </div>
  );
}

/**
 * LabAudioButton.tsx - Botão de áudio do Laboratório MENTE.AI
 * 
 * Usa AudioContext isolado para TTS ElevenLabs para evitar conflitos
 * com o ambientEngine (Tone.js) e outros sistemas de áudio.
 */

'use client';

import { useState, useCallback, useRef, useEffect } from 'react';
import { Volume2, VolumeX, Loader2 } from 'lucide-react';

interface LabAudioButtonProps {
  text: string;
  voiceId?: string;
  agentName?: string;
  className?: string;
}

/**
 * Hook personalizado para TTS com AudioContext isolado
 */
function useIsolatedTTS() {
  const [isPlaying, setIsPlaying] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const audioRef = useRef<HTMLAudioElement | null>(null);
  const speechRef = useRef<SpeechSynthesisUtterance | null>(null);

  const stop = useCallback(() => {
    // Para áudio ElevenLabs
    if (audioRef.current) {
      audioRef.current.pause();
      audioRef.current.currentTime = 0;
      audioRef.current = null;
    }
    
    // Para TTS do navegador
    if ('speechSynthesis' in window) {
      window.speechSynthesis.cancel();
    }
    
    setIsPlaying(false);
    setError(null);
  }, []);

  const play = useCallback(async (
    text: string,
    options?: { 
      voiceId?: string;
      useElevenLabs?: boolean;
      onProgress?: (playing: boolean) => void;
    }
  ) => {
    stop();

    const { voiceId, useElevenLabs = false, onProgress } = options || {};

    try {
      // Tenta ElevenLabs primeiro se voiceId estiver disponível
      if (useElevenLabs && voiceId) {
        // Cria AudioContext isolado para ElevenLabs
        const audioContext = new (window.AudioContext || (window as any).webkitAudioContext)();
        
        const response = await fetch('/api/elevenlabs/speak', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            text: encodeURIComponent(text),
            voiceId: voiceId,
          }),
        });

        if (!response.ok) {
          const errorText = await response.text().catch(() => "");
          throw new Error(errorText || `ElevenLabs API error: ${response.status}`);
        }

        const audioBuffer = await response.arrayBuffer();
        const decodedBuffer = await audioContext.decodeAudioData(audioBuffer);
        
        const source = audioContext.createBufferSource();
        source.buffer = decodedBuffer;
        source.connect(audioContext.destination);
        
        await new Promise<void>((resolve, reject) => {
          source.onended = () => {
            setIsPlaying(false);
            onProgress?.(false);
            resolve();
          };
          // AudioBufferSourceNode não tem onerror, usamos try/catch no play
          source.start(0);
          setIsPlaying(true);
          onProgress?.(true);
        });

        await audioContext.close();
        return;
      }

      // Fallback para TTS do navegador
      if ('speechSynthesis' in window) {
        // Aguarda vozes estarem disponíveis
        const voices = window.speechSynthesis.getVoices();
        
        const utterance = new SpeechSynthesisUtterance(text);
        utterance.lang = 'pt-BR';
        utterance.rate = 0.95;
        utterance.pitch = 1;
        utterance.volume = 1;

        // Seleciona voz em português
        const ptVoice = 
          voices.find(v => v.lang === 'pt-BR') ||
          voices.find(v => v.lang.includes('pt')) ||
          voices.find(v => v.name.toLowerCase().includes('portuguese'));
        
        if (ptVoice) {
          utterance.voice = ptVoice;
        }

        utterance.onstart = () => {
          setIsPlaying(true);
          setError(null);
          onProgress?.(true);
        };
        
        utterance.onend = () => {
          setIsPlaying(false);
          onProgress?.(false);
        };
        
        utterance.onerror = (event) => {
          console.error('Erro TTS:', event);
          setError(event.error);
          setIsPlaying(false);
          onProgress?.(false);
        };

        speechRef.current = utterance;
        window.speechSynthesis.speak(utterance);
        return;
      }

      // Sem suporte a TTS
      throw new Error('Speech synthesis não suportado neste navegador');

    } catch (err) {
      console.error('Erro ao tocar áudio:', err);
      setError(err instanceof Error ? err.message : 'Erro desconhecido');
      setIsPlaying(false);
      onProgress?.(false);
    }
  }, [stop]);

  useEffect(() => {
    return () => {
      stop();
    };
  }, [stop]);

  return { isPlaying, error, play, stop };
}

/**
 * Botão de áudio para o Laboratório
 * 
 * Recursos:
 * - AudioContext isolado para ElevenLabs
 * - Fallback para SpeechSynthesis API
 * - Tratamento robusto de erros
 * - Indicador visual de estado
 */
export default function LabAudioButton({ 
  text, 
  voiceId, 
  agentName = 'NEXUS',
  className = ''
}: LabAudioButtonProps) {
  const { isPlaying, error, play, stop } = useIsolatedTTS();
  const [showFallback, setShowFallback] = useState(false);

  const handleToggle = useCallback(() => {
    if (isPlaying) {
      stop();
    } else {
      // Tenta ElevenLabs primeiro, fallback para TTS
      play(text, { 
        voiceId, 
        useElevenLabs: !!voiceId,
        onProgress: (playing) => {
          if (!playing && error) {
            setShowFallback(true);
          }
        }
      });
    }
  }, [isPlaying, text, voiceId, play, stop, error]);

  return (
    <div className={`inline-flex items-center gap-2 ${className}`}>
      <button
        onClick={handleToggle}
        disabled={isPlaying && !error}
        className={`
          inline-flex items-center gap-2 px-4 py-2 rounded-lg font-semibold transition-all
          ${isPlaying 
            ? 'bg-purple-500/20 text-purple-300 border border-purple-500/40' 
            : 'bg-white/10 text-white border border-white/20 hover:bg-white/20'
          }
          disabled:opacity-50 disabled:cursor-not-allowed
        `}
        aria-label={isPlaying ? 'Parar áudio' : 'Ouvir introdução'}
        title={isPlaying ? 'Parar áudio' : 'Ouvir introdução'}
      >
        {isPlaying ? (
          <>
            <Loader2 className="w-4 h-4 animate-spin" />
            <span className="text-sm">Tocando...</span>
          </>
        ) : error ? (
          <>
            <VolumeX className="w-4 h-4 text-red-400" />
            <span className="text-sm text-red-300">Erro no áudio</span>
          </>
        ) : (
          <>
            <Volume2 className="w-4 h-4" />
            <span className="text-sm">Ouvir {agentName}</span>
          </>
        )}
      </button>

      {error && (
        <div className="text-xs text-red-300 bg-red-500/10 border border-red-500/20 rounded px-2 py-1">
          {error}. Verifique as permissões de áudio do navegador.
        </div>
      )}
    </div>
  );
}

'use client'

import { useRef, useMemo, useEffect, useState } from 'react'
import { Canvas, useFrame } from '@react-three/fiber'
import { Float, PointMaterial, Points } from '@react-three/drei'
import { EffectComposer, Bloom, ChromaticAberration } from '@react-three/postprocessing'
import * as THREE from 'three'
import { useLabStore } from '@/store/useLabStore'
import { AGENTS, type AgentId } from '@/canon/agents/canon'

const PARTICLE_COUNT = 500
const SPHERE_RADIUS = 20

function LabScene() {
  const meshRef = useRef<THREE.Mesh>(null!)
  const pointsRef = useRef<THREE.Points>(null!)
  const sceneColor = useLabStore((s) => s.sceneColor)
  const chatIntensity = useLabStore((s) => s.chatIntensity)
  const activeAgent = useLabStore((s) => s.activeAgent)

  const targetColor = useMemo(() => new THREE.Color(sceneColor), [sceneColor])
  const [positions, sizes] = useMemo(() => {
    const pos = new Float32Array(PARTICLE_COUNT * 3)
    const siz = new Float32Array(PARTICLE_COUNT)
    for (let i = 0; i < PARTICLE_COUNT; i++) {
      const theta = Math.random() * Math.PI * 2
      const phi = Math.acos(2 * Math.random() - 1)
      const r = SPHERE_RADIUS * (0.6 + Math.random() * 0.4)
      pos[i * 3] = r * Math.sin(phi) * Math.cos(theta)
      pos[i * 3 + 1] = r * Math.sin(phi) * Math.sin(theta)
      pos[i * 3 + 2] = r * Math.cos(phi)
      siz[i] = 0.5 + Math.random() * 1.5
    }
    return [pos, siz]
  }, [])

  useFrame((state, delta) => {
    const elapsed = state.clock.getElapsedTime()
    const intensity = Math.max(0, 1 - (Date.now() - chatIntensity) / 1000)

    if (meshRef.current) {
      meshRef.current.rotation.x += delta * (0.15 + intensity * 0.3)
      meshRef.current.rotation.y += delta * (0.2 + intensity * 0.4)
      const scale = 1 + Math.sin(elapsed * 2) * 0.02 + intensity * 0.05
      meshRef.current.scale.setScalar(scale)
      const mat = meshRef.current.material as THREE.MeshStandardMaterial
      mat.color.lerp(targetColor, delta * 2)
      mat.emissiveIntensity = 0.3 + intensity * 0.5
    }

    if (pointsRef.current) {
      const geo = pointsRef.current.geometry
      const posAttr = geo.attributes.position
      const array = posAttr.array as Float32Array
      const speed = delta * (0.05 + intensity * 0.2)
      for (let i = 0; i < PARTICLE_COUNT; i++) {
        const idx = i * 3
        const x = array[idx]
        const y = array[idx + 1]
        const z = array[idx + 2]
        const theta = Math.atan2(z, x) + speed
        const r = Math.sqrt(x * x + z * z)
        array[idx] = r * Math.cos(theta)
        array[idx + 2] = r * Math.sin(theta)
        array[idx + 1] += Math.sin(elapsed * 0.5 + i) * delta * 0.1
      }
      posAttr.needsUpdate = true
    }
  })

  return (
    <>
      <ambientLight intensity={0.2} />
      <pointLight position={[10, 10, 10]} intensity={0.5} color={targetColor} />
      <Float speed={0.5} rotationIntensity={0.1} floatIntensity={0.5}>
        <mesh ref={meshRef}>
          <icosahedronGeometry args={[2, 0]} />
          <meshStandardMaterial
            color="#00f5ff"
            emissive="#00f5ff"
            emissiveIntensity={0.3}
            wireframe={false}
            roughness={0.2}
            metalness={0.8}
          />
        </mesh>
      </Float>
      <Points ref={pointsRef} positions={positions} sizes={sizes}>
        <PointMaterial
          size={0.15}
          color={targetColor}
          transparent
          opacity={0.6}
          sizeAttenuation
          depthWrite={false}
        />
      </Points>
      <EffectComposer>
        <Bloom luminanceThreshold={0.3} luminanceSmoothing={0.9} intensity={0.5} />
        <ChromaticAberration offset={[0.002, 0.002]} />
      </EffectComposer>
    </>
  )
}

export default function LabCanvas() {
  const [hasWebGL, setHasWebGL] = useState(true)

  useEffect(() => {
    try {
      const canvas = document.createElement('canvas')
      const gl = canvas.getContext('webgl2') || canvas.getContext('webgl')
      if (!gl) setHasWebGL(false)
    } catch {
      setHasWebGL(false)
    }
  }, [])

  if (!hasWebGL) return null

  return (
    <div
      className="fixed inset-0 z-0 pointer-events-none"
      style={{ background: '#0a0a14' }}
    >
      <Canvas
        camera={{ position: [0, 0, 8], fov: 60 }}
        dpr={[1, 1.5]}
        gl={{ antialias: true, alpha: false, powerPreference: 'high-performance' }}
      >
        <LabScene />
      </Canvas>
    </div>
  )
}

"use client";

import { useState, useEffect } from "react";
import { motion } from "framer-motion";
import { Brain, Zap, ArrowRight } from "lucide-react";

interface RateLimitScreenProps {
  window: "5min" | "hour" | "day" | "global";
  resetIn: number; // seconds
  message?: { title: string; body: string; suggestion: string };
  cachedQuestions: string[];
  onTryCached: (question: string) => void;
  onReset: () => void;
}

export function RateLimitScreen({
  window: rlWindow,
  resetIn,
  message,
  cachedQuestions,
  onTryCached,
  onReset,
}: RateLimitScreenProps) {
  const [timeLeft, setTimeLeft] = useState(resetIn);

  // Countdown
  useEffect(() => {
    if (timeLeft <= 0) {
      onReset();
      return;
    }
    const timer = setTimeout(() => setTimeLeft((t) => t - 1), 1000);
    return () => clearTimeout(timer);
  }, [timeLeft, onReset]);

  const minutes = Math.floor(timeLeft / 60);
  const seconds = timeLeft % 60;
  const display = `${minutes}:${seconds.toString().padStart(2, "0")}`;
  const progress = Math.min(100, ((resetIn - timeLeft) / resetIn) * 100);

  // Default message fallback
  const msg = message || {
    title: "🧠 Calibrando frequência neural...",
    body: "O laboratório está sincronizando seus experimentos. Novos experimentos estarão disponíveis em breve.",
    suggestion: "Enquanto isso, perguntas do cache respondem instantaneamente ⚡",
  };

  return (
    <motion.div
      initial={{ opacity: 0, scale: 0.95 }}
      animate={{ opacity: 1, scale: 1 }}
      transition={{ duration: 0.5 }}
      className="flex flex-col items-center gap-6 p-8 max-w-lg mx-auto text-center"
    >
      {/* Animated brain/pulse icon */}
      <motion.div
        animate={{ scale: [1, 1.08, 1] }}
        transition={{ repeat: Infinity, duration: 2.5, ease: "easeInOut" }}
        className="relative"
      >
        <div
          className="w-20 h-20 rounded-full flex items-center justify-center"
          style={{
            background: "rgba(0,245,255,0.06)",
            border: "1px solid rgba(0,245,255,0.12)",
            boxShadow: "0 0 40px rgba(0,245,255,0.08)",
          }}
        >
          <Brain size={32} style={{ color: "var(--accent-cyan)" }} />
        </div>
        {/* Pulse ring */}
        <motion.div
          animate={{ scale: [1, 1.4, 1], opacity: [0.3, 0, 0.3] }}
          transition={{ repeat: Infinity, duration: 2.5 }}
          className="absolute inset-0 rounded-full"
          style={{ border: "1px solid rgba(0,245,255,0.15)" }}
        />
      </motion.div>

      {/* Title */}
      <h3
        className="text-lg font-bold leading-snug"
        style={{ color: "var(--accent-cyan)", fontFamily: "var(--font-display)" }}
      >
        {msg.title}
      </h3>

      {/* Body */}
      <p className="text-white/45 text-sm leading-relaxed max-w-sm">{msg.body}</p>

      {/* Suggestion */}
      <p className="text-white/25 text-xs italic leading-relaxed">{msg.suggestion}</p>

      {/* Countdown + progress bar */}
      <div className="w-full max-w-xs">
        <div className="flex items-center justify-between text-[10px] font-mono text-white/25 mb-2">
          <span>Disponível em</span>
          <span className="text-white/50 font-bold">{display}</span>
        </div>
        <div className="h-1.5 rounded-full bg-white/[0.04] overflow-hidden">
          <motion.div
            className="h-full rounded-full"
            style={{ background: "var(--accent-cyan)" }}
            initial={{ width: 0 }}
            animate={{ width: `${progress}%` }}
            transition={{ duration: 0.5 }}
          />
        </div>
      </div>

      {/* Cached suggestions */}
      {cachedQuestions.length > 0 && (
        <div className="w-full max-w-sm">
          <p className="text-[9px] font-mono uppercase tracking-[0.2em] text-white/15 mb-3">
            ⚡ Disponíveis agora (instantâneo)
          </p>
          <div className="flex flex-wrap gap-2 justify-center">
            {cachedQuestions.slice(0, 6).map((q) => (
              <motion.button
                key={q}
                whileHover={{ scale: 1.04 }}
                whileTap={{ scale: 0.96 }}
                onClick={() => onTryCached(q)}
                className="flex items-center gap-1.5 px-3 py-1.5 rounded-full text-[10px] font-medium transition-all duration-200 hover:brightness-125"
                style={{
                  background: "rgba(0,245,255,0.06)",
                  border: "1px solid rgba(0,245,255,0.1)",
                  color: "rgba(255,255,255,0.6)",
                }}
              >
                <Zap size={9} style={{ color: "var(--accent-cyan)" }} />
                {q}
              </motion.button>
            ))}
          </div>
        </div>
      )}

      {/* Try again hint */}
      <p className="text-white/10 text-[9px] font-mono uppercase tracking-wider">
        {rlWindow === "day"
          ? "Reinicia à meia-noite"
          : rlWindow === "global"
          ? "Processando em lote"
          : "Calibrando frequência"}
      </p>
    </motion.div>
  );
}

