                <div className="p-4 bg-[#0f0f1a]">
                  <h3 className="text-sm font-bold text-white mb-1 truncate">{agent.name}</h3>
                  <p className="text-xs text-white/40 line-clamp-2">{agent.personality.approach.slice(0, 70)}...</p>
