const GRID_COORDS = [-4, -2, 0, 2, 4] as const;

function GridNode({ x, z, phase }: { x: number; z: number; phase: number }) {
  const ref = useRef<THREE.Mesh>(null!);
  useFrame(({ clock }) => {
    ref.current.scale.y = 0.6 + Math.sin(clock.elapsedTime * 1.2 + phase) * 0.5;
  });
  return (
    <mesh ref={ref} position={[x, -4, z]}>
      <boxGeometry args={[0.12, 0.6, 0.12]} />
      <meshStandardMaterial color="#60A5FA" emissive="#3B82F6" emissiveIntensity={1.5} />
    </mesh>
  );
}

function PlatonicSolid({
  position,
  speed,
  color,
  emissive,
  geoType,
}: {
  position: [number, number, number];
  speed: number;
  color: string;
  emissive: string;
  geoType: 'tetra' | 'octa' | 'dodeca' | 'icosa';
}) {
  const ref = useRef<THREE.Mesh>(null!);
  useFrame(({ clock }) => {
    ref.current.rotation.y = clock.elapsedTime * speed;
    ref.current.rotation.x = clock.elapsedTime * speed * 0.5;
    ref.current.position.y =
      position[1] + Math.sin(clock.elapsedTime * 0.4 + speed * 2) * 0.7;
  });
  return (
    <mesh ref={ref} position={position}>
      {geoType === 'tetra'  && <tetrahedronGeometry  args={[1.1, 0]} />}
      {geoType === 'octa'   && <octahedronGeometry   args={[0.9, 0]} />}
      {geoType === 'dodeca' && <dodecahedronGeometry args={[0.9, 0]} />}
      {geoType === 'icosa'  && <icosahedronGeometry  args={[0.9, 0]} />}
      <meshStandardMaterial
        color={color}
        emissive={emissive}
        emissiveIntensity={2.5}
        wireframe
      />
    </mesh>
  );
}

export function AxiomScene() {
  const { scene } = useThree()
  useEffect(() => { scene.background = new THREE.Color('#020510') }, [scene])
  return (
    <>
      <ambientLight intensity={0.08} />
      <pointLight position={[0, 8, 0]} intensity={18} color="#3B82F6" />
      <pointLight position={[0, -2, 6]} intensity={8} color="#F1F5F9" />

      {GRID_COORDS.flatMap((x) =>
        GRID_COORDS.map((z) => (
          <GridNode key={`${x}-${z}`} x={x} z={z} phase={(x + z) * 0.4} />
        ))
      )}

      <PlatonicSolid
        position={[-4, 1, -2]} speed={0.40} geoType="tetra"
        color="#3B82F6" emissive="#1D4ED8"
      />
      <PlatonicSolid
        position={[4, 2, 1]} speed={0.30} geoType="octa"
        color="#F1F5F9" emissive="#CBD5E1"
      />
      <PlatonicSolid
        position={[-2, 0.5, 3]} speed={0.20} geoType="dodeca"
        color="#60A5FA" emissive="#2563EB"
      />
      <PlatonicSolid
        position={[3, -1, -3]} speed={0.50} geoType="icosa"
        color="#F8FAFC" emissive="#E2E8F0"
      />

      <Sparkles count={280} scale={22} size={1.3} speed={0.5} color="#3B82F6" />
      <Sparkles count={90}  scale={12} size={2.5} speed={0.8} color="#F1F5F9" />
    </>
  );
}

export default AxiomScene;

'use client';
import { useRef, useEffect } from 'react';
import { useFrame, useThree } from '@react-three/fiber';
import { Sparkles } from '@react-three/drei';
import * as THREE from 'three';

const TOP    = 8;
const HEIGHT = 16;
// Deterministic pseudo-RNG — no Math.random(), stable across renders
const rng = (s: number) => Math.abs(Math.sin(s * 127.1 + 311.7));
const BIT_COLORS = ['#4ADE80', '#22C55E', '#10B981'] as const;

interface BitProps {
  x: number;
  z: number;
  speed: number;
  startOffset: number;
  color: string;
  size: number;
}

function DataBit({ x, z, speed, startOffset, color, size }: BitProps) {
  const ref = useRef<THREE.Mesh>(null!);
  useFrame(({ clock }) => {
    // Cascade from TOP downward, wrap back to top
    ref.current.position.y = TOP - ((clock.elapsedTime * speed + startOffset) % HEIGHT);
  });
  return (
    <mesh ref={ref} position={[x, 0, z]}>
      <boxGeometry args={[size, size, size]} />
      <meshStandardMaterial color={color} emissive={color} emissiveIntensity={4} />
    </mesh>
  );
}

// 20 columns × 3 bits per column = 60 cascading data bits
const BITS: BitProps[] = Array.from({ length: 20 }, (_, ci) => {
  const x     = (rng(ci * 3)  - 0.5) * 18;
  const z     = (rng(ci * 7)  - 0.5) * 12;
  const speed = 2 + rng(ci * 11) * 3;
  return [0, 1, 2].map((bi) => ({
    x,
    z,
    speed,
    startOffset: bi * (HEIGHT / 3),
    color: BIT_COLORS[bi],
    size: bi === 0 ? 0.16 : 0.10,
  }));
}).flat();

export function CipherScene() {
  const { scene } = useThree()
  useEffect(() => { scene.background = new THREE.Color('#000a02') }, [scene])
  return (
    <>
      <ambientLight intensity={0.06} />
      <pointLight position={[0,  8, 0]} intensity={16} color="#4ADE80" />
      <pointLight position={[0, -4, 4]} intensity={8}  color="#10B981" />

      {BITS.map((b, i) => (
        <DataBit key={i} {...b} />
      ))}

      <Sparkles count={320} scale={22} size={1.5} speed={0.7} color="#4ADE80" />
      <Sparkles count={110} scale={12} size={2.5} speed={1.0} color="#10B981" />
    </>
  );
}

export default CipherScene;

"use client";

import dynamic from "next/dynamic";
import type { ComponentType } from "react";

/**
 * DynamicScene — Carregador lazy universal para cenas Three.js.
 *
 * Cada cena 3D (~150-300 linhas, importa Three.js + @react-three/fiber/drei)
 * é carregada sob demanda APENAS quando o universo correspondente é visitado.
 *
 * Isso remove ~500KB (Three.js + drei) do bundle inicial e distribui
 * o custo entre as 12 rotas de universo.
 *
 * Uso:
 *   <DynamicScene scene="AuroraScene" />
 *   <DynamicScene scene="NexusScene" />
 */

const SCENE_MAP: Record<string, () => Promise<{ default: ComponentType }>> = {
  AuroraScene: () =>
    import("@/components/scenes/AuroraScene").then((m) => ({
      default: m.AuroraScene,
    })),
  AxiomScene: () =>
    import("@/components/scenes/AxiomScene").then((m) => ({
      default: m.AxiomScene,
    })),
  CipherScene: () =>
    import("@/components/scenes/CipherScene").then((m) => ({
      default: m.CipherScene,
    })),
  EthosScene: () =>
    import("@/components/scenes/EthosScene").then((m) => ({
      default: m.EthosScene,
    })),
  JanusScene: () =>
    import("@/components/scenes/JanusScene").then((m) => ({
      default: m.JanusScene,
    })),
  KaosScene: () =>
    import("@/components/scenes/KaosScene").then((m) => ({
      default: m.KaosScene,
    })),
  LyraScene: () =>
    import("@/components/scenes/LyraScene").then((m) => ({
      default: m.LyraScene,
    })),
  PrismScene: () =>
    import("@/components/scenes/PrismScene").then((m) => ({
      default: m.PrismScene,
    })),
  StratosScene: () =>
    import("@/components/scenes/StratosScene").then((m) => ({
      default: m.StratosScene,
    })),
  TerraScene: () =>
    import("@/components/scenes/TerraScene").then((m) => ({
      default: m.TerraScene,
    })),
  VoltScene: () =>
    import("@/components/scenes/VoltScene").then((m) => ({
      default: m.VoltScene,
    })),
  NexusScene: () =>
    import("@/components/universo/NexusScene").then((m) => ({
      default: m.NexusScene,
    })),
};

/**
 * Fallback exibido enquanto a cena 3D carrega.
 * Minimalista para não competir com o loading.tsx da rota.
 */
function SceneLoadingFallback() {
  return (
    <div className="flex h-full min-h-[300px] items-center justify-center">
      <div className="h-8 w-8 animate-spin rounded-full border-2 border-white/5 border-t-[#a855f7]/50" />
    </div>
  );
}

interface DynamicSceneProps {
  scene: keyof typeof SCENE_MAP;
  className?: string;
}

export function DynamicScene({ scene, className }: DynamicSceneProps) {
  const loader = SCENE_MAP[scene];
  if (!loader) {
    console.warn(`[DynamicScene] Cena "${scene}" não encontrada no mapa.`);
    return null;
  }

  const LazyScene = dynamic(loader, {
    ssr: false,
    loading: () => <SceneLoadingFallback />,
  });

  return (
    <div className={className}>
      <LazyScene />
    </div>
  );
}

'use client';
import { useRef, useEffect } from 'react';
import { useFrame, useThree } from '@react-three/fiber';
import { Sparkles } from '@react-three/drei';
import * as THREE from 'three';

const PILLAR_COUNT = 8;
const ORBIT_R = 5.5;

function LogicCore() {
  const ref = useRef<THREE.Mesh>(null!);
  useFrame(({ clock }) => {
    ref.current.rotation.y = clock.elapsedTime * 0.3;
    ref.current.rotation.x = clock.elapsedTime * 0.15;
  });
  return (
    <mesh ref={ref}>
      <dodecahedronGeometry args={[1.3, 0]} />
      <meshStandardMaterial
        color="#FDE047"
        emissive="#F59E0B"
        emissiveIntensity={3.5}
        wireframe
      />
    </mesh>
  );
}

function Pillar({
  angle,
  phase,
  isGold,
}: {
  angle: number;
  phase: number;
  isGold: boolean;
}) {
  const ref = useRef<THREE.Mesh>(null!);
  const x = Math.cos(angle) * ORBIT_R;
  const z = Math.sin(angle) * ORBIT_R;
  const col = isGold ? '#F59E0B' : '#F1F5F9';
  const em = isGold ? '#D97706' : '#CBD5E1';

  useFrame(({ clock }) => {
    const sy = 1 + Math.sin(clock.elapsedTime * 0.8 + phase) * 0.45;
    ref.current.scale.y = sy;
    ref.current.position.y = (sy - 1) * 2;
  });

  return (
    <mesh ref={ref} position={[x, 0, z]}>
      <cylinderGeometry args={[0.14, 0.22, 4, 6]} />
      <meshStandardMaterial color={col} emissive={em} emissiveIntensity={2.5} />
    </mesh>
  );
}

const PILLARS = Array.from({ length: PILLAR_COUNT }, (_, i) => ({
  angle: (i / PILLAR_COUNT) * Math.PI * 2,
  phase: (i / PILLAR_COUNT) * Math.PI * 2,
  isGold: i % 2 === 0,
}));

export function EthosScene() {
  const { scene } = useThree()
  useEffect(() => { scene.background = new THREE.Color('#050308') }, [scene])
  return (
    <>
      <ambientLight intensity={0.08} />
      <pointLight position={[0, 8, 0]} intensity={20} color="#F59E0B" />
      <pointLight position={[0, -5, 0]} intensity={8} color="#F1F5F9" />

      <LogicCore />

      {PILLARS.map((p, i) => (
        <Pillar key={i} {...p} />
      ))}

      <Sparkles count={300} scale={22} size={1.5} speed={0.5} color="#F59E0B" />
      <Sparkles count={100} scale={14} size={3.0} speed={0.8} color="#F1F5F9" />
    </>
  );
}

export default EthosScene;

'use client';
import { useRef, useEffect } from 'react';
import { useFrame, useThree } from '@react-three/fiber';
import { Sparkles } from '@react-three/drei';
import * as THREE from 'three';

function Portal({
  posX,
  rotDir,
  color,
  emissive,
  tiltZ,
}: {
  posX: number;
  rotDir: number;
  color: string;
  emissive: string;
  tiltZ: number;
}) {
  const outerRef = useRef<THREE.Mesh>(null!);
  const innerRef = useRef<THREE.Mesh>(null!);

  useFrame(({ clock }) => {
    outerRef.current.rotation.y = clock.elapsedTime * 0.30 * rotDir;
    outerRef.current.rotation.z = tiltZ + Math.sin(clock.elapsedTime * 0.2) * 0.05;
    innerRef.current.rotation.y = clock.elapsedTime * 0.65 * -rotDir;
    innerRef.current.rotation.x = clock.elapsedTime * 0.40 * rotDir;
  });

  return (
    <>
      <mesh ref={outerRef} position={[posX, 0, 0]}>
        <torusGeometry args={[3.2, 0.10, 12, 80]} />
        <meshStandardMaterial color={color} emissive={emissive} emissiveIntensity={3} />
      </mesh>
      <mesh ref={innerRef} position={[posX, 0, 0]}>
        <torusGeometry args={[2.0, 0.07, 10, 60]} />
        <meshStandardMaterial color={color} emissive={emissive} emissiveIntensity={2} />
      </mesh>
    </>
  );
}

function Nexus() {
  const ref = useRef<THREE.Mesh>(null!);
  useFrame(({ clock }) => {
    ref.current.rotation.y = clock.elapsedTime * 0.5;
    ref.current.rotation.x = clock.elapsedTime * 0.25;
  });
  return (
    <mesh ref={ref}>
      <octahedronGeometry args={[0.8, 0]} />
      <meshStandardMaterial
        color="#E2E8F0"
        emissive="#CBD5E1"
        emissiveIntensity={3}
        wireframe
      />
    </mesh>
  );
}

