'use client';
import { useRef, useEffect } from 'react';
import { useFrame, useThree } from '@react-three/fiber';
import { Sparkles } from '@react-three/drei';
import * as THREE from 'three';

function ChessTile({
  x,
  z,
  phase,
  isDark,
}: {
  x: number;
  z: number;
  phase: number;
  isDark: boolean;
}) {
  const ref = useRef<THREE.Mesh>(null!);
  const color = isDark ? '#10B981' : '#0EA5E9';
  useFrame(({ clock }) => {
    ref.current.position.y = Math.sin(clock.elapsedTime * 0.7 + phase) * 1.2 - 1.5;
  });
  return (
    <mesh ref={ref} position={[x * 2.6, -1.5, z * 2.6]}>
      <boxGeometry args={[2.3, 0.1, 2.3]} />
      <meshStandardMaterial color={color} emissive={color} emissiveIntensity={0.6} />
    </mesh>
  );
}

function Pillar({ x, z, phase }: { x: number; z: number; phase: number }) {
  const ref = useRef<THREE.Mesh>(null!);
  useFrame(({ clock }) => {
    ref.current.scale.y = 0.6 + Math.sin(clock.elapsedTime * 0.5 + phase) * 0.35;
    ref.current.position.y = Math.sin(clock.elapsedTime * 0.5 + phase) * 1.2 - 0.5;
  });
  return (
    <mesh ref={ref} position={[x * 5.2, 0, z * 5.2]}>
      <cylinderGeometry args={[0.1, 0.1, 4, 6]} />
      <meshStandardMaterial color="#0EA5E9" emissive="#0EA5E9" emissiveIntensity={2} />
    </mesh>
  );
}

const GRID = [-2, -1, 0, 1, 2] as const;
const CORNERS: [number, number][] = [[-1, -1], [1, -1], [-1, 1], [1, 1]];

export function StratosScene() {
  const { scene } = useThree()
  useEffect(() => { scene.background = new THREE.Color('#010a07') }, [scene])
  return (
    <>
      <ambientLight intensity={0.15} />
      <pointLight position={[0, 12, 0]} intensity={8} color="#10B981" />
      <pointLight position={[0, -4, 10]} intensity={4} color="#0EA5E9" />

      {GRID.flatMap((x) =>
        GRID.map((z) => (
          <ChessTile
            key={`${x}-${z}`}
            x={x}
            z={z}
            phase={(x + z) * 0.4}
            isDark={(Math.abs(x) + Math.abs(z)) % 2 === 0}
          />
        ))
      )}

      {CORNERS.map(([x, z]) => (
        <Pillar key={`p${x}${z}`} x={x} z={z} phase={x * z * 0.5} />
      ))}

      <Sparkles count={200} scale={22} size={1.5} speed={0.6} color="#10B981" />
      <Sparkles count={70} scale={12} size={3.5} speed={1.2} color="#0EA5E9" />
    </>
  );
}

export default StratosScene;

'use client';
import { useRef, useMemo, useEffect } from 'react';
import { useFrame, useThree } from '@react-three/fiber';
import { Sparkles } from '@react-three/drei';
import * as THREE from 'three';

// Deterministic pseudo-RNG — no Math.random(), stable across renders
const rng = (s: number) => Math.abs(Math.sin(s * 127.1 + 311.7));

interface StoneProps {
  position: [number, number, number];
  size: number;
  speed: number;
  isAmber: boolean;
  floatPhase: number;
}

function FloatingStone({ position, size, speed, isAmber, floatPhase }: StoneProps) {
  const ref = useRef<THREE.Mesh>(null!);
  const col = isAmber ? '#F59E0B' : '#14B8A6';
  const em  = isAmber ? '#D97706' : '#0D9488';

  useFrame(({ clock }) => {
    ref.current.rotation.y = clock.elapsedTime * speed;
    ref.current.rotation.x = clock.elapsedTime * speed * 0.6;
    ref.current.position.y =
      position[1] + Math.sin(clock.elapsedTime * 0.5 + floatPhase) * 0.6;
  });

  return (
    <mesh ref={ref} position={position}>
      <icosahedronGeometry args={[size, 0]} />
      <meshStandardMaterial color={col} emissive={em} emissiveIntensity={1.8} />
    </mesh>
  );
}

// Hex ground platforms — 1 center + 6 ring
const HEX_CENTERS: [number, number][] = [
  [0, 0],
  [3, 0],
  [-3, 0],
  [1.5, 2.6],
  [-1.5, 2.6],
  [1.5, -2.6],
  [-1.5, -2.6],
];

function HexPlatform({ cx, cz }: { cx: number; cz: number }) {
  return (
    <mesh position={[cx, -3.5, cz]}>
      <cylinderGeometry args={[1.2, 1.2, 0.15, 6]} />
      <meshStandardMaterial
        color="#78350F"
        emissive="#92400E"
        emissiveIntensity={0.8}
      />
    </mesh>
  );
}

export function TerraScene() {
  const { scene } = useThree()
  useEffect(() => { scene.background = new THREE.Color('#050a03') }, [scene])
  const stones = useMemo<StoneProps[]>(
    () =>
      Array.from({ length: 12 }, (_, i) => ({
        position: [
          (rng(i * 3) - 0.5) * 14,
          rng(i * 7) * 5 - 1,
          (rng(i * 11) - 0.5) * 10,
        ] as [number, number, number],
        size: 0.3 + rng(i * 13) * 0.7,
        speed: 0.2 + rng(i * 17) * 0.4,
        isAmber: i % 3 !== 0,
        floatPhase: i * 0.7,
      })),
    []
  );

  return (
    <>
      <ambientLight intensity={0.1} />
      <pointLight position={[0, 6, 0]} intensity={15} color="#F59E0B" />
      <pointLight position={[0, -2, 6]} intensity={8} color="#14B8A6" />

      {HEX_CENTERS.map(([cx, cz], i) => (
        <HexPlatform key={i} cx={cx} cz={cz} />
      ))}

      {stones.map((s, i) => (
        <FloatingStone key={i} {...s} />
      ))}

      <Sparkles count={250} scale={20} size={1.8} speed={0.6} color="#F59E0B" />
      <Sparkles count={80} scale={12} size={3.0} speed={1.0} color="#14B8A6" />
    </>
  );
}

export default TerraScene;

'use client';
import { useRef, useEffect } from 'react';
import { useFrame, useThree } from '@react-three/fiber';
import { Sparkles } from '@react-three/drei';
import * as THREE from 'three';

function OrbitRing({
  radius,
  speed,
  tiltX = 0,
  tiltZ = 0,
  color,
}: {
  radius: number;
  speed: number;
  tiltX?: number;
  tiltZ?: number;
  color: string;
}) {
  const ref = useRef<THREE.Mesh>(null!);
  useFrame(({ clock }) => {
    ref.current.rotation.y = clock.elapsedTime * speed;
    ref.current.rotation.x = tiltX;
    ref.current.rotation.z = tiltZ;
  });
  return (
    <mesh ref={ref}>
      <torusGeometry args={[radius, 0.045, 12, 80]} />
      <meshBasicMaterial color={color} />
    </mesh>
  );
}

function PulsingCore() {
  const ref = useRef<THREE.Mesh>(null!);
  useFrame(({ clock }) => {
    const s = 1 + Math.sin(clock.elapsedTime * 4) * 0.15;
    ref.current.scale.setScalar(s);
    ref.current.rotation.y = clock.elapsedTime * 0.5;
    ref.current.rotation.x = clock.elapsedTime * 0.3;
  });
  return (
    <mesh ref={ref}>
      <icosahedronGeometry args={[1.4, 1]} />
      <meshStandardMaterial
        color="#FDE047"
        emissive="#F59E0B"
        emissiveIntensity={4}
        wireframe
      />
    </mesh>
  );
}

export function VoltScene() {
  const { scene } = useThree()
  useEffect(() => { scene.background = new THREE.Color('#030200') }, [scene])
  return (
    <>
      <ambientLight intensity={0.1} />
      <pointLight position={[0, 0, 6]} intensity={20} color="#F59E0B" />
      <pointLight position={[6, 6, 0]} intensity={10} color="#FB923C" />

      <PulsingCore />

      <OrbitRing radius={3.5} speed={0.6} tiltX={0.2} color="#F59E0B" />
      <OrbitRing radius={5.5} speed={-0.35} tiltX={Math.PI / 4} tiltZ={0.3} color="#FDE047" />
      <OrbitRing radius={8} speed={0.18} tiltX={Math.PI / 2.5} tiltZ={-0.2} color="#FB923C" />

      <Sparkles count={500} scale={24} size={2.2} speed={3} color="#F59E0B" />
      <Sparkles count={120} scale={10} size={5} speed={5} color="#FDE047" />
    </>
  );
}

export default VoltScene;

'use client'

import { useState, useEffect, useCallback } from 'react'
import { motion, AnimatePresence } from 'framer-motion'

// ─── MOCK DATA ─────────────────────────────────────────────────────────────

const MOCK_PROFILE = {
