} as const

// ─── SUB-COMPONENTS ────────────────────────────────────────────────────────

function DimensionBar({
  id,
  value,
  animating,
}: {
  id: keyof typeof DIMENSION_META
  value: number
  animating: boolean
}) {
  const meta = DIMENSION_META[id]

  return (
    <div className="space-y-2">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
