export const PRISM_T01E02_UNIT=U("ku-prism-t01-e02","A Troca de Lentes","prism-t01-e02-troca-de-lentes","Entender como mudar intencionalmente de perspectiva para resolver problemas.","understand",["perspective-shift","reframing"],["fundamentos","lentes"]);
export const PRISM_T01E02_ASSET=A("ka-prism-t01-e02","ku-prism-t01-e02",2,"PRISM gira um cristal e a sala inteira muda. O que era ameaçador vira belo. O que era confuso vira claro. 'A mágica não está no objeto. Está na lente. Quando você muda a lente, o mundo muda junto.'","Einstein disse: 'Não podemos resolver problemas usando o mesmo tipo de pensamento que usamos quando os criamos.' Isso é troca de lentes. Um problema financeiro pode ser um problema de marketing. Um conflito pessoal pode ser uma oportunidade de crescimento. A solução não está em pensar MAIS — está em pensar DIFERENTE.","'Você trocou de lente. Mas algumas perspectivas são invisíveis. Amanhã, a visão que ninguém tem.'","O Prisma","A Visão Invisível",false,[
  { pergunta: "O que Einstein quis dizer com 'não podemos resolver problemas com o mesmo pensamento que usamos para criá-los'?", opcoes: ["A. Que problemas são insolúveis", "B. Que precisamos mudar nossa forma de pensar para encontrar soluções inovadoras", "C. Que Einstein não gostava de matemática"], continuacoes: ["Não são insolúveis — mas exigem uma MUDANÇA DE NÍVEL. Um problema criado por um certo padrão de pensamento não pode ser resolvido pelo MESMO padrão. Precisa de um salto — uma nova lente.", "Exato! Essa citação é a essência da troca de lentes. Se você está preso em um problema, a resposta não é se esforçar MAIS com a mesma abordagem — é mudar completamente a abordagem. Pensar diferente, não pensar mais.", "Não é sobre gostar ou não de matemática. Einstein está falando sobre a estrutura do pensamento. Às vezes, a solução para um problema financeiro está numa lente de marketing, ou a solução para um conflito pessoal está em vê-lo como oportunidade de crescimento."] },
  { pergunta: "Como PRISM demonstra a troca de lentes na prática?", opcoes: ["A. Girando um cristal que transforma a percepção da sala inteira", "B. Pintando as paredes de outra cor", "C. Trocando os móveis de lugar"], continuacoes: ["PRISM usa o cristal como metáfora visual. Girá-lo não muda a realidade objetiva — muda a FORMA como você a percebe. A mágica não está no objeto, mas na lente através da qual você o observa.", "Isso mesmo! A transformação não acontece no mundo externo — acontece na sua PERCEPÇÃO. Um problema que parecia ameaçador pode se revelar uma oportunidade bela quando você muda o ângulo de visão.", "Não é sobre rearrumar o ambiente físico. A troca de lentes é interna: você muda sua PERSPECTIVA, e o mundo à sua volta parece mudar. Não é ilusão — é a descoberta de aspectos que estavam ali mas você não via."] }
