export const PRISM_T01E03_UNIT=U("ku-prism-t01-e03","A Visão Invisível","prism-t01-e03-visao-invisivel","Aplicar empatia para enxergar perspectivas de grupos marginalizados.","understand",["empathy","invisible-perspectives"],["fundamentos","invisível"]);
export const PRISM_T01E03_ASSET=A("ka-prism-t01-e03","ku-prism-t01-e03",3,"A sala escurece. Alguns espelhos estão cobertos. PRISM os revela um a um. 'Estas são as perspectivas que ninguém vê. Os silenciados. Os ignorados. A empatia não é sentir pena — é ver o mundo pelos olhos de quem você nunca foi.'","Quando o Airbnb começou, fotos de anfitriões negros recebiam menos reservas — mesmo com preços iguais. O viés era invisível para quem não era afetado. O Airbnb criou o 'Instant Book' — reserva sem aprovação do anfitrião. A solução não foi 'conscientizar' — foi REDESENHAR o sistema.","'Você viu o invisível. Mas múltiplas perspectivas geram conflito. Amanhã, a arte do diálogo.'","A Troca de Lentes","O Diálogo Infinito",true,[
  { pergunta: "Qual a diferença entre empatia e 'sentir pena' segundo PRISM?", opcoes: ["A. São a mesma coisa", "B. Sentir pena é uma emoção passiva; empatia é ver ativamente o mundo pelos olhos do outro", "C. Empatia é mais fraca que sentir pena"], continuacoes: ["Não são a mesma coisa. Sentir pena é observar de fora — uma emoção distante. Empatia é um exercício ativo de mudança de perspectiva: você se coloca no lugar do outro e tenta VER como ele vê.", "Perfeito! Sentir pena mantém a distância entre 'nós' e 'eles'. Empatia EXIGE que você se aproxime. Não é 'coitadinho' — é 'como seria se EU estivesse na pele dessa pessoa?'. Uma postura radicalmente diferente.", "Pelo contrário, empatia é mais EXIGENTE. Sentir pena não demanda ação — você sente e segue. Empatia te TRANSFORMA porque você passa a enxergar o que antes era invisível para você. É um trabalho ativo, não passivo."] },
  { pergunta: "O que o caso do Airbnb ensina sobre viés invisível?", opcoes: ["A. Que o racismo não existe em plataformas digitais", "B. Que o viés pode ser sistêmico e invisível para quem não é afetado, e a solução prática é melhor que apenas conscientizar", "C. Que fotos não importam em plataformas digitais"], continuacoes: ["Infelizmente, o racismo existe mesmo em plataformas digitais. O caso do Airbnb mostrou que algoritmos e sistemas podem perpetuar vieses raciais mesmo sem intenção explícita. O viés era invisível para os anfitriões brancos, mas muito real para os negros.", "Exato! O caso é brilhante porque mostra que CONSCIENTIZAR (dizer 'não sejam racistas') não foi a solução mais eficaz. REDESENHAR o sistema (Instant Book) removeu a oportunidade do viés operar. É uma lição poderosa sobre design de sistemas e justiça.", "Não é sobre fotos não importarem — é sobre como O MESMO anúncio com fotos de pessoas negras gerava menos reservas. O viés não estava na foto ou no anúncio — estava na mente dos usuários. E a solução foi mudar o SISTEMA, não as pessoas."] }
]);
