/**
 * phase-router.ts - Roteamento por Fases e Temporadas
 * 
 * Sistema LEGO que conecta:
 * - 5 Fases Narrativas
 * - 50 Temporadas
 * - 12 Agentes
 * - 3 Dimensões do perfil
 */

import { 
  type Season, 
  type Phase, 
  type AgentId,
  getPhaseForSeason,
  getPhaseConfig,
  getAgentForSeason,
  canAccessSeason,
  getNextSeason,
  PHASES
} from '@/config/seasons';

import { getSeasonByNumber, getSeasonsByPhase, getSeasonSummary } from '@/data/seasons';

import type { Archetype } from './router';

export interface PhaseRouterDecision {
  currentSeason: number;
  currentPhase: Phase;
  currentAgent: AgentId;
  season: Season;
  availableSeasons: number[];
  nextSeason: number;
  canProceed: boolean;
  learningPath: Season[];
  conceptProgress: string[];
  emotionalArc: string;
}

export interface UserProgress {
  currentSeason: number;
  completedSeasons: number[];
  archetype: Archetype;
  emotionalScore: number;
  intellectualScore: number;
  moralScore: number;
}

// ============================================================================
// MAIN FUNCTION - O "Montador de LEGO"
// ============================================================================

export function routeSeason(userProgress: UserProgress): PhaseRouterDecision {
  const { currentSeason, completedSeasons } = userProgress;
  
  // 1. Obter configuração da fase atual
  const phase = getPhaseForSeason(currentSeason);
  const phaseConfig = getPhaseConfig(phase);
  
  // 2. Obter a temporada atual
  const season = getSeasonByNumber(currentSeason) || getSeasonByNumber(1)!;
  
  // 3. Determinar o agente basedo no perfil do usuário
  const currentAgent = getAgentForSeason(currentSeason, userProgress.archetype);
  
  // 4. Calcular próximos passos
  const canProceed = canAccessSeason(currentSeason + 1, completedSeasons);
  const nextSeason = canProceed 
    ? getNextSeason(currentSeason) 
    : currentSeason;
  
  // 5. Gerar caminho de aprendizado (próximas 3 temporadas)
  const learningPath = generateLearningPath(currentSeason, userProgress.archetype);
  
  // 6. Calcular progresso conceitual
  const conceptProgress = calculateConceptProgress(completedSeasons);
  
  // 7. Determinar arco emocional da fase
  const emotionalArc = determineEmotionalArc(phase, userProgress.emotionalScore);
  
  // 8. Lista de temporadas disponíveis para esta fase
  const availableSeasons = getSeasonsByPhase(phase).map(s => s.number);

  return {
    currentSeason,
    currentPhase: phase,
    currentAgent,
    season,
    availableSeasons,
    nextSeason,
    canProceed,
    learningPath,
    conceptProgress,
    emotionalArc,
  };
}

// ============================================================================
// HELPERS - Funções auxiliares de montagem
// ============================================================================

function generateLearningPath(startSeason: number, archetype?: string): Season[] {
  const path: Season[] = [];
  const nextSeasons = [startSeason + 1, startSeason + 2, startSeason + 3];
  
  for (const num of nextSeasons) {
    if (num > 50) break;
    const season = getSeasonByNumber(num);
    if (season) path.push(season);
  }
  
  return path;
}

function calculateConceptProgress(completedSeasons: number[]): string[] {
  const concepts: string[] = [];
  
  for (const num of completedSeasons.slice(-5)) {
    const season = getSeasonByNumber(num);
    if (season) {
      concepts.push(season.conceptKey);
    }
  }
  
  return [...new Set(concepts)]; // Remove duplicates
}

function determineEmotionalArc(phase: Phase, emotionalScore: number): string {
  const phaseArcs: Record<Phase, string> = {
    DESPERTAR: 'Curiosidade → Surpresa → Primeiras dúvidas',
    TENSÃO: 'Tensão → Conflito → Primeiros medos reais',
    RUPTURA: 'Desconforto → Raiva produtiva → Ruptura intelectual',
    CONVERGÊNCIA: 'Clareza → Responsabilidade → Maturidade intelectual',
    TRANSCENDÊNCIA: 'Gravidade → Transcendência → Responsabilidade geracional',
  };
  
  // Ajusta baseado no score emocional do usuário
  if (emotionalScore > 2) {
    return `${phaseArcs[phase]} (positivo)`;
  } else if (emotionalScore < -2) {
    return `${phaseArcs[phase]} (desafiado)`;
  }
  
  return phaseArcs[phase];
}

// ============================================================================
// BACKTRACKING - Função para "desmontar e remontar" o LEGO
// ============================================================================

export function shouldBacktrackToPhase(
  currentSeason: number,
  userProgress: UserProgress
): { shouldBacktrack: boolean; targetSeason: number; reason: string } {
  const phase = getPhaseForSeason(currentSeason);
  const completedInPhase = userProgress.completedSeasons.filter(
    s => getPhaseForSeason(s) === phase
  );
  
  // Se o usuário completou menos de 3 temporadas nesta fase, considerar backtrack
  if (completedInPhase.length < 3 && currentSeason > 1) {
    const phaseConfig = getPhaseConfig(phase);
    const targetSeason = phaseConfig.range[0]; // Primeira temporada da fase
    
    return {
      shouldBacktrack: true,
      targetSeason,
      reason: `Revisar fundamentos da fase ${phaseConfig.name} antes de avançar`,
    };
  }
  
  return {
    shouldBacktrack: false,
    targetSeason: currentSeason,
    reason: '',
  };
}

// ============================================================================
// SEASON UNLOCK SYSTEM - Quando o LEGO pode ser montado
// ============================================================================

export function canUnlockSeason(
  seasonNumber: number,
  userProgress: UserProgress
): { canUnlock: boolean; required: number[]; reason: string } {
  if (seasonNumber === 1) {
    return { canUnlock: true, required: [], reason: 'Primeira temporada disponível' };
  }
  
  const requiredSeasons: number[] = [];
  
  // Temporada anterior é sempre necessária
  if (!userProgress.completedSeasons.includes(seasonNumber - 1)) {
    requiredSeasons.push(seasonNumber - 1);
  }
  
  // Se é o início de uma nova fase, verificar se completou a fase anterior
  const currentPhase = getPhaseForSeason(seasonNumber);
  const phaseConfig = getPhaseConfig(currentPhase);
  
  if (seasonNumber === phaseConfig.range[0]) {
    // É primeira temporada da fase - verificar se completou fase anterior
    const phases: Phase[] = ['DESPERTAR', 'TENSÃO', 'RUPTURA', 'CONVERGÊNCIA', 'TRANSCENDÊNCIA'];
    const currentPhaseIndex = phases.indexOf(currentPhase);
    
    if (currentPhaseIndex > 0) {
      const previousPhase = phases[currentPhaseIndex - 1];
      const prevPhaseConfig = getPhaseConfig(previousPhase);
      const lastOfPrevPhase = prevPhaseConfig.range[1];
      
      if (!userProgress.completedSeasons.includes(lastOfPrevPhase)) {
        requiredSeasons.push(lastOfPrevPhase);
      }
    }
  }
  
  const canUnlock = requiredSeasons.length === 0;
  
  return {
    canUnlock,
    required: requiredSeasons,
    reason: canUnlock 
      ? 'Temporada desbloqueada' 
      : `Complete: ${requiredSeasons.map(n => `T${n.toString().padStart(2, '0')}`).join(', ')}`,
  };
}

// ============================================================================
// EXPORT PARA USO NO ROUTER PRINCIPAL
// ============================================================================

export function integrateWithMainRouter(
  currentSeason: number,
  userArchetype: Archetype,
  emotionalScore: number,
  intellectualScore: number,
  moralScore: number
): {
  agent: AgentId;
  season: Season;
  phaseConfig: typeof PHASES[Phase];
  nextAgent: AgentId;
  phaseTransition: boolean;
} {
  const phase = getPhaseForSeason(currentSeason);
  const phaseConfig = getPhaseConfig(phase);
  const season = getSeasonByNumber(currentSeason) || getSeasonByNumber(1)!;
  
  // Agent basedo no perfil do usuário
  const agent = getAgentForSeason(currentSeason, userArchetype);
  
  // Próximo agente baseado nas escolhas
  let nextAgent = getAgentForSeason(currentSeason + 1, userArchetype);
  
  // Detectar transição de fase
  const nextPhase = getPhaseForSeason(currentSeason + 1);
  const phaseTransition = nextPhase !== phase;
  
  if (phaseTransition) {
    // Na transição de fase, usar agente dominannte da nova fase
    nextAgent = getPhaseConfig(nextPhase).dominantAgent;
  }
  
  return {
    agent,
    season,
    phaseConfig,
    nextAgent,
    phaseTransition,
  };
}

import { db } from "@/lib/db";
import { interactiveDecisions } from "@/lib/db/schema";
import { userProfile } from "@/lib/db/schema-narrative";
import { eq } from "drizzle-orm";

const VALID_ARCHETYPES = [
  "analytical", "rebel", "paralyzed", "empathetic", "strategic", "creative", "explorer",
];

function archetypeFromScores(emotional: number, intellectual: number, moral: number): string {
  if (intellectual > 0.6) return "analytical";
  if (emotional > 0.6) return "empathetic";
  if (moral > 0.6) return "strategic";
  if (emotional < 0.3 && intellectual < 0.3) return "paralyzed";
  if (emotional > 0.4 && intellectual > 0.4) return "creative";
  return "explorer";
}

function scoreToDimension(score: number): string {
  return String(Math.max(0, Math.min(1, Number(score.toFixed(2)))));
}

export type EmotionalSignal = "curiosity" | "fear" | "rebellion" | "conformity";
export type IntellectualSignal = "logical" | "intuitive";
export type MoralSignal = "protected_humanity" | "expanded_ai_power";

export interface ProfileSignals {
  emotional: EmotionalSignal;
  intellectual: IntellectualSignal;
  moral: MoralSignal;
  emotionalScore: number;
  intellectualScore: number;
  moralScore: number;
}

export interface InteractionContext {
  userId: number;
  episodeId?: number;
  seriesId?: number;
  agentId?: string;
  choiceId?: string;
  choiceLabel: string;
  narrativeResponse?: string;
}

const emotionalPatterns: Record<EmotionalSignal, RegExp[]> = {
  curiosity: [/curios/i, /explor/i, /e se/i, /quero entender/i, /why/i, /how/i],
  fear: [/medo/i, /insegur/i, /perigo/i, /ansio/i, /não consigo/i, /travado/i],
  rebellion: [/quebrar/i, /rebel/i, /subverter/i, /contra regra/i, /hack/i, /ruptura/i],
  conformity: [/seguir/i, /manual/i, /regra/i, /protocolo/i, /padr[aã]o/i, /compliance/i],
};

const intellectualPatterns: Record<IntellectualSignal, RegExp[]> = {
  logical: [/l[oó]gic/i, /prova/i, /evid[eê]n/i, /analis/i, /passo a passo/i, /axioma/i],
  intuitive: [/intui/i, /sentir/i, /insight/i, /vis[aã]o/i, /imagin/i, /instinto/i],
};

const moralPatterns: Record<MoralSignal, RegExp[]> = {
  protected_humanity: [/human/i, /seguran[aç]/i, /[eé]tic/i, /limite/i, /prote[çc][aã]o/i],
  expanded_ai_power: [/escalar ia/i, /autonom/i, /expand/i, /superintelig/i, /mais poder/i],
};

function countMatches(input: string, patterns: RegExp[]): number {
  return patterns.reduce((acc, pattern) => acc + (pattern.test(input) ? 1 : 0), 0);
}

function clampProfileRange(value: number): number {
  return Math.max(-9.99, Math.min(9.99, Number(value.toFixed(2))));
}

function chooseDominant<T extends string>(scores: Record<T, number>, fallback: T): T {
  const entries = Object.entries(scores) as Array<[T, number]>;
  const winner = entries.sort((a, b) => b[1] - a[1])[0];
  return winner && winner[1] > 0 ? winner[0] : fallback;
}

function normalizeDelta(left: number, right: number): number {
  const total = left + right;
  if (!total) return 0;
  return Number((((left - right) / total) * 1.8).toFixed(2));
}

export function extractProfileSignals(choiceLabel: string): ProfileSignals {
  const normalized = choiceLabel.toLowerCase();

  const emotionalCounts = {
    curiosity: countMatches(normalized, emotionalPatterns.curiosity),
    fear: countMatches(normalized, emotionalPatterns.fear),
    rebellion: countMatches(normalized, emotionalPatterns.rebellion),
    conformity: countMatches(normalized, emotionalPatterns.conformity),
  };

  const intellectualCounts = {
    logical: countMatches(normalized, intellectualPatterns.logical),
    intuitive: countMatches(normalized, intellectualPatterns.intuitive),
  };

  const moralCounts = {
    protected_humanity: countMatches(normalized, moralPatterns.protected_humanity),
    expanded_ai_power: countMatches(normalized, moralPatterns.expanded_ai_power),
  };

  const emotional = chooseDominant(emotionalCounts, "curiosity");
  const intellectual = chooseDominant(intellectualCounts, "logical");
  const moral = chooseDominant(moralCounts, "protected_humanity");

  const emotionalScore = Number(
    normalizeDelta(
      emotionalCounts.curiosity + emotionalCounts.rebellion,
      emotionalCounts.fear + emotionalCounts.conformity,
    ).toFixed(2),
  );
  const intellectualScore = Number(normalizeDelta(intellectualCounts.logical, intellectualCounts.intuitive).toFixed(2));
  const moralScore = Number(normalizeDelta(moralCounts.protected_humanity, moralCounts.expanded_ai_power).toFixed(2));

  return { emotional, intellectual, moral, emotionalScore, intellectualScore, moralScore };
}

