const STORAGE_KEY = 'mente_ai_user_profile';

interface StoredProfile {
  emotionalScore: number;
  intellectualScore: number;
  moralScore: number;
  archetype: string;
  currentAgent: string;
  decisionHistory: Array<{
    choice: string;
    agentId: string;
    emotionalDelta: number;
    intellectualDelta: number;
    moralDelta: number;
    timestamp: number;
  }>;
  lastUpdated: number;
}

function getStoredProfile(): StoredProfile | null {
  if (typeof window === 'undefined') return null;
  const stored = localStorage.getItem(STORAGE_KEY);
  if (!stored) return null;
  try {
    return JSON.parse(stored);
  } catch {
    return null;
  }
}

function setStoredProfile(profile: StoredProfile): void {
  if (typeof window === 'undefined') return;
  localStorage.setItem(STORAGE_KEY, JSON.stringify(profile));
}

export async function getUserProfile(userId: number): Promise<{
  emotionalScore: number;
  intellectualScore: number;
  moralScore: number;
  archetype: string;
  currentAgent: string;
  decisionHistory: Array<{
    choice: string;
    agentId: string;
    emotionalDelta: number;
    intellectualDelta: number;
    moralDelta: number;
    timestamp: number;
  }>;
  lastUpdated: number;
} | null> {
  // Try DB first (persistent across sessions)
  try {
    const rows = await db
      .select()
      .from(userProfile)
      .where(eq(userProfile.userId, userId))
      .limit(1);
    if (rows.length > 0) {
      const row = rows[0];
      const profile: StoredProfile = {
        emotionalScore: Number(row.emotionalDim),
        intellectualScore: Number(row.intellectualDim),
        moralScore: Number(row.moralDim),
        archetype: row.archetypeLabel || "explorer",
        currentAgent: row.lastAgentId || "nexus",
        decisionHistory: [],
        lastUpdated: row.updatedAt ? new Date(row.updatedAt).getTime() : Date.now(),
      };
      // Sync to localStorage for offline/guest fallback
      setStoredProfile(profile);
      return profile;
    }
  } catch {
    // DB unavailable — fall through to localStorage
  }

  // Fallback: localStorage (works without login or offline)
  const local = getStoredProfile();
  if (local) return local;

  return null;
}

export async function updateUserProfile(
  userId: number,
  updates: Partial<StoredProfile>
): Promise<void> {
  const current = getStoredProfile() || {
    emotionalScore: 0,
    intellectualScore: 0,
    moralScore: 0,
    archetype: 'creative',
    currentAgent: 'nexus',
    decisionHistory: [],
    lastUpdated: Date.now(),
  };

  const updated = { ...current, ...updates, lastUpdated: Date.now() };
  setStoredProfile(updated);

  // Sync to DB (fire-and-forget — não bloqueia o fluxo do usuário)
  try {
    const emotionalScore = updated.emotionalScore ?? 0;
    const intellectualScore = updated.intellectualScore ?? 0;
    const moralScore = updated.moralScore ?? 0;
    const archetype = updated.archetype ?? archetypeFromScores(emotionalScore, intellectualScore, moralScore);
    const currentAgent = updated.currentAgent ?? "nexus";

    const profileData = {
      userId,
      emotionalDim: scoreToDimension(emotionalScore),
      intellectualDim: scoreToDimension(intellectualScore),
      moralDim: scoreToDimension(moralScore),
      archetypeLabel: archetype,
      lastAgentId: currentAgent,
    };

    const existing = await db
      .select()
      .from(userProfile)
      .where(eq(userProfile.userId, userId))
      .limit(1);

    if (existing.length > 0) {
      await db
        .update(userProfile)
        .set(profileData)
        .where(eq(userProfile.userId, userId));
    } else {
      await db.insert(userProfile).values(profileData);
    }
  } catch {
    // DB sync failure não interrompe o fluxo — localStorage está salvo
    console.warn("[PROFILER] Falha ao sincronizar perfil com DB");
  }
}

export function getLocalProfile(): StoredProfile | null {
  return getStoredProfile();
}

import { desc, eq } from "drizzle-orm";
import { db } from "@/lib/db";
import { interactiveDecisions } from "@/lib/db/schema";
// NOTE (Phase 0): universeTransitions and userProfiles are Phase 2 tables.
// All inserts/updates to those tables are stubbed out until migrations land.
import { getUserProfile, updateUserProfile } from "@/engine/profiler";
import { getActiveConflicts, type AgentId } from "./agent-conflicts";
import { findTransition } from "./narrative-transitions";
import { analyzeWithLangChain, buildSystemPromptForAgent, type UserProfile } from "./langchain-integration";
import { 
  routeSeason, 
  integrateWithMainRouter,
  canUnlockSeason,
  shouldBacktrackToPhase,
  type UserProgress 
} from "./phase-router";
import { getSeasonByNumber } from "@/data/seasons";

export type Archetype = "analytical" | "rebel" | "paralyzed" | "empathetic" | "strategic" | "creative";
export type UniverseId = "NEXUS" | "AXIOM" | "KAOS" | "ETHOS" | "VOLT" | "TERRA" | "LYRA" | "STRATOS" | "PRISM" | "AURORA";

export interface RouterDecision {
  archetype: Archetype;
  selectedUniverse: UniverseId;
  alternatives: UniverseId[];
  reason: string;
  backtrackApplied: boolean;
  hasConflict?: boolean;
  conflictDetails?: import('./agent-conflicts').AgentConflict[];
  transition?: import('./narrative-transitions').NarrativeTransition;
  langchainDecision?: import('./langchain-integration').NarrativeDecision;
  // Sistema de Temporadas (LEGO)
  season?: { number: number; title: string; theme: string; centralDilemma: string; agent: string };
  phase?: { id: string; name: string; range: [number, number]; concept: string; emotion: string };
  nextAgent?: string;
  phaseTransition?: boolean;
  canAccessSeason?: boolean;
}

const ARCHETYPE_DESTINATIONS: Record<Archetype, UniverseId[]> = {
  analytical: ["NEXUS", "AXIOM"],
  rebel: ["KAOS", "ETHOS"],
  paralyzed: ["VOLT"],
  empathetic: ["TERRA", "LYRA"],
  strategic: ["STRATOS"],
  creative: ["PRISM", "AURORA"],
};

function classifyArchetype(emotional: number, intellectual: number, moral: number): Archetype {
  if (emotional <= -1.4 && intellectual >= 1.2) return "analytical";
  if (emotional >= 1.2 && moral <= -0.8) return "rebel";
  if (emotional <= -1.1 && intellectual <= -0.9) return "paralyzed";
  if (moral >= 1.1 && emotional >= 0.4) return "empathetic";
  if (intellectual >= 1.1 && moral >= 0.3) return "strategic";
  return "creative";
}

async function runTreeOfThoughtsHeuristic(args: {
  archetype: Archetype;
  userText: string;
  currentAgent?: string;
}): Promise<{ selectedUniverse: UniverseId; reason: string }> {
  const candidates = ARCHETYPE_DESTINATIONS[args.archetype];
  const candidateA = candidates[0];
  const candidateB = candidates[1] ?? candidates[0];

  const thought1 = `Thought 1: Se o usuário pediu estrutura/clareza, priorizar ${candidateA}.`;
  const thought2 = `Thought 2: Se pediu contraste/alternativa, priorizar ${candidateB}.`;
  const thought3 = `Thought 3: Evitar repetir universo atual para destravar avanço.`;

  const lowered = args.userText.toLowerCase();
  const asksAlternative = /alternativa|outra|diferente|new angle|different/i.test(lowered);
  const selectedUniverse = asksAlternative ? candidateB : candidateA;

  try {
    // Optional runtime integration; if LangChain is unavailable, heuristic remains active.
    const dynamicImporter = new Function("specifier", "return import(specifier);") as (specifier: string) => Promise<unknown>;
    const maybeLangchain = await dynamicImporter("langchain/chains");
    if (maybeLangchain) {
      return {
        selectedUniverse,
        reason: `${thought1} ${thought2} ${thought3} (Tree-of-Thoughts via LangChain enabled)`,
      };
    }
  } catch {
    // silent fallback to deterministic route
  }

  return {
    selectedUniverse,
    reason: `${thought1} ${thought2} ${thought3} (deterministic ToT fallback)`,
  };
}

async function shouldBacktrackForStagnation(userId: number): Promise<boolean> {
  const rows = await db
    .select({ choiceId: interactiveDecisions.choiceId })
    .from(interactiveDecisions)
    .where(eq(interactiveDecisions.userId, userId))
    .orderBy(desc(interactiveDecisions.createdAt))
    .limit(3);

  if (rows.length < 3) return false;
  return rows.every((r) => r.choiceId === rows[0].choiceId);
}

async function shouldBacktrackForNoProgress(userId: number): Promise<boolean> {
  const rows = await db
    .select({ narrativeResponse: interactiveDecisions.narrativeResponse })
    .from(interactiveDecisions)
    .where(eq(interactiveDecisions.userId, userId))
    .orderBy(desc(interactiveDecisions.createdAt))
    .limit(5);

  if (rows.length < 5) return false;
  return rows.every((row) => (row.narrativeResponse ?? "").trim().length < 30);
}

function selectDifferentPerspective(currentUniverse: UniverseId | null, alternatives: UniverseId[]): UniverseId {
  if (!currentUniverse) return alternatives[0];
  const different = alternatives.find((u) => u !== currentUniverse);
  return different ?? alternatives[0];
}

function mapAgentToUniverse(agentId?: string | null): UniverseId | null {
  if (!agentId) return null;
  const token = agentId.toUpperCase();
  if (["NEXUS", "AXIOM", "KAOS", "ETHOS", "VOLT", "TERRA", "LYRA", "STRATOS", "PRISM", "AURORA"].includes(token)) {
    return token as UniverseId;
  }
  return null;
}

function mapUniverseToAgent(universe: UniverseId): string {
  return universe.toLowerCase();
}

export async function routeAdaptiveNarrative(params: {
  userId: number;
  userText: string;
  currentAgent?: string;
}): Promise<RouterDecision> {
  const profile = await getUserProfile(params.userId);

  const emotional = profile?.emotionalScore ?? 0;
  const intellectual = profile?.intellectualScore ?? 0;
  const moral = profile?.moralScore ?? 0;

  const archetype = classifyArchetype(emotional, intellectual, moral);
  const alternatives = ARCHETYPE_DESTINATIONS[archetype];

  const tot = await runTreeOfThoughtsHeuristic({
    archetype,
    userText: params.userText,
    currentAgent: params.currentAgent,
  });

  const currentUniverse = mapAgentToUniverse(params.currentAgent);
  let selectedUniverse = tot.selectedUniverse;
  let backtrackApplied = false;
  let reason = tot.reason;

  const stagnated = await shouldBacktrackForStagnation(params.userId);
  const noProgress = await shouldBacktrackForNoProgress(params.userId);

  if (stagnated || noProgress) {
    selectedUniverse = selectDifferentPerspective(currentUniverse, alternatives);
    backtrackApplied = true;
    reason = "stagnation";

    // NOTE (Phase 0): universeTransitions insert stubbed — table added in Phase 2 migration
    // await db.insert(universeTransitions).values({ userId: params.userId, fromAgent: params.currentAgent ?? "nexus", toAgent: mapUniverseToAgent(selectedUniverse), reason: "stagnation" });
  } else if (currentUniverse && currentUniverse !== selectedUniverse) {
    // NOTE (Phase 0): universeTransitions insert stubbed — table added in Phase 2 migration
    // await db.insert(universeTransitions).values({ userId: params.userId, fromAgent: params.currentAgent ?? "nexus", toAgent: mapUniverseToAgent(selectedUniverse), reason: "adaptive_route" });
  }

  // NOTE (Phase 0): userProfiles update stubbed — table added in Phase 2 migration
  // await db.update(userProfiles).set({ archetypeLabel: archetype, lastAgentId: mapUniverseToAgent(selectedUniverse), updatedAt: new Date() }).where(eq(userProfiles.userId, params.userId));

  // Silence unused variable warning from mapUniverseToAgent while stubs are active
  void mapUniverseToAgent(selectedUniverse);

  // 🔀 Sistema de Conflitos entre Agentes
  const currentAgentId = params.currentAgent as AgentId;
  const decisionHistory: { agentId: AgentId; choice: string }[] = []; // Would come from DB in Phase 2
  const activeConflicts = currentAgentId ? getActiveConflicts([...decisionHistory, { agentId: currentAgentId, choice: params.userText }]) : [];
  const hasConflict = activeConflicts.length > 0;

  // 🌟 Sistema de Transições Narrativas
  const transition = currentAgentId ? findTransition(currentAgentId, params.userText) : null;
  
  // 🤖 Análise LangChain (se disponível)
  let langchainAnalysis = null;
  if (profile) {
    const userProfileForLangchain: UserProfile = {
      userId: params.userId,
      emotionalScore: emotional,
      intellectualScore: intellectual,
      moralScore: moral,
      archetype,
      currentAgent: (params.currentAgent as AgentId) || 'nexus',
      decisionHistory: [],
      lastUpdated: Date.now(),
    };
    
    langchainAnalysis = await analyzeWithLangChain(
      params.userText,
      userProfileForLangchain,
      (params.currentAgent as AgentId) || 'nexus'
    );
    
    if (langchainAnalysis.confidence > 0.7 && langchainAnalysis.nextAgent !== currentAgentId) {
      selectedUniverse = mapAgentToUniverse(langchainAnalysis.nextAgent) || selectedUniverse;
      reason = `${reason} | LangChain: ${langchainAnalysis.reason}`;
    }
  }

  // 🎬 Sistema de Temporadas (LEGO)
  // Se o usuário especificar uma temporada, processa a temporada
  const seasonNumber = (params as { seasonNumber?: number }).seasonNumber || 1;
  
  const seasonIntegration = integrateWithMainRouter(
    seasonNumber,
    archetype,
    emotional,
    intellectual,
    moral
  );
  
  const canAccess = canUnlockSeason(seasonNumber, {
    currentSeason: seasonNumber,
    completedSeasons: [],
    archetype,
    emotionalScore: emotional,
    intellectualScore: intellectual,
    moralScore: moral,
  });

  return {
    archetype,
    selectedUniverse,
    alternatives,
    reason,
    backtrackApplied,
    hasConflict,
    // Sistema de Temporadas
    season: seasonIntegration.season,
    phase: seasonIntegration.phaseConfig,
    nextAgent: seasonIntegration.nextAgent as string,
    phaseTransition: seasonIntegration.phaseTransition,
    canAccessSeason: canAccess.canUnlock,
    conflictDetails: hasConflict ? activeConflicts : undefined,
    transition: transition || undefined,
    langchainDecision: langchainAnalysis || undefined,
  };
  
  if (langchainAnalysis) {
    await updateUserProfile(params.userId, {
      emotionalScore: emotional,
      intellectualScore: intellectual,
      moralScore: moral,
      archetype,
      currentAgent: langchainAnalysis.nextAgent,
      decisionHistory: [
        ...(profile?.decisionHistory || []),
        {
          choice: params.userText.slice(0, 100),
          agentId: langchainAnalysis.nextAgent,
          emotionalDelta: langchainAnalysis.confidence > 0.8 ? 0.5 : 0,
          intellectualDelta: 0,
          moralDelta: 0,
          timestamp: Date.now(),
        },
      ],
    });
  }
}

