"use client";

import { useCallback, useEffect, useMemo, useState } from "react";

type MyListItemType = "agent" | "module";

type MyListItem = {
  type: MyListItemType;
  id: string;
};

const STORAGE_KEY = "mente_ai_my_list";

function keyOf(item: MyListItem) {
  return `${item.type}:${item.id}`;
}

function parseStorage(value: string | null): MyListItem[] {
  if (!value) return [];
  try {
    const parsed = JSON.parse(value) as unknown;
    if (!Array.isArray(parsed)) return [];
    const out: MyListItem[] = [];
    for (const v of parsed) {
      if (!v || typeof v !== "object") continue;
      const rec = v as { type?: unknown; id?: unknown };
      if ((rec.type === "agent" || rec.type === "module") && typeof rec.id === "string" && rec.id.trim()) {
        out.push({ type: rec.type, id: rec.id.trim() });
      }
    }
    return out;
  } catch {
    return [];
  }
}

export function useMyList() {
  const [items, setItems] = useState<MyListItem[]>([]);

  useEffect(() => {
    setItems(parseStorage(globalThis.localStorage?.getItem(STORAGE_KEY) ?? null));
  }, []);

  const index = useMemo(() => {
    const map = new Set<string>();
    for (const it of items) map.add(keyOf(it));
    return map;
  }, [items]);

  const isInList = useCallback(
    (type: MyListItemType, id: string) => {
      return index.has(`${type}:${id}`);
    },
    [index]
  );

  const toggle = useCallback((type: MyListItemType, id: string) => {
    setItems((prev) => {
      const normalizedId = id.trim();
      const k = `${type}:${normalizedId}`;
      const exists = prev.some((p) => keyOf(p) === k);
      const next = exists ? prev.filter((p) => keyOf(p) !== k) : [...prev, { type, id: normalizedId }];
      try {
        globalThis.localStorage?.setItem(STORAGE_KEY, JSON.stringify(next));
      } catch (_e) {
        void _e;
      }
      return next;
    });
  }, []);

  return { items, isInList, toggle };
}

"use client";

import { useState, useCallback, useRef, useEffect } from "react";

type TTSState = "idle" | "loading" | "playing" | "error";

interface UseTTSReturn {
  state: TTSState;
  play: (text: string, agentId: string) => Promise<void>;
  stop: () => void;
}

const VOICE_MAP: Record<string, string> = {
  nexus: "pNInz6obpgDQGcFmaJgB",
  cipher: "pNInz6obpgDQGcFmaJgB",
  kaos: "pNInz6obpgDQGcFmaJgB",
  aurora: "pNInz6obpgDQGcFmaJgB",
  volt: "pNInz6obpgDQGcFmaJgB",
  ethos: "pNInz6obpgDQGcFmaJgB",
};

export function useTTS(): UseTTSReturn {
  const [state, setState] = useState<TTSState>("idle");
  const audioRef = useRef<HTMLAudioElement | null>(null);
  const generationRef = useRef(0);

  // Cleanup crítico: para o áudio quando o componente desmonta
  useEffect(() => {
    return () => {
      generationRef.current++;
      if (audioRef.current) {
        audioRef.current.pause();
        audioRef.current.src = "";
        audioRef.current = null;
      }
      setState("idle");
    };
  }, []);

  const stop = useCallback(() => {
    generationRef.current++;
    if (audioRef.current) {
      audioRef.current.pause();
      audioRef.current.src = "";
      audioRef.current = null;
      setState("idle");
    }
  }, []);

  const play = useCallback(async (text: string, agentId: string) => {
    const gen = ++generationRef.current;
    stop();

    const voiceId = VOICE_MAP[agentId] || VOICE_MAP["nexus"];

    try {
      setState("loading");

      const res = await fetch("/api/elevenlabs/speak", {
        method: "POST",
        credentials: "include",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ text, voice_id: voiceId }),
      });

      if (!res.ok) throw new Error(`TTS ${res.status}`);

      // Se stop() foi chamado durante o fetch, aborta — evita race condition
      if (gen !== generationRef.current) return;

      const blob = await res.blob();
      const url = URL.createObjectURL(blob);

      if (gen !== generationRef.current) {
        URL.revokeObjectURL(url);
        return;
      }

      const audio = new Audio(url);
      audioRef.current = audio;

      audio.onended = () => {
        URL.revokeObjectURL(url);
        if (audioRef.current === audio) {
          audioRef.current = null;
        }
        setState("idle");
      };

      audio.onerror = () => {
        URL.revokeObjectURL(url);
        if (audioRef.current === audio) {
          audioRef.current = null;
        }
        setState("error");
      };

      await audio.play();
      setState("playing");
    } catch {
      setState("error");
    }
  }, [stop]);

  return { state, play, stop };
}

