import { AgentFull, Category } from "@/types/agent";

const DEFAULT_COLOR = "#6366F1";

export function buildCategories(agents: AgentFull[], maxPerCategory = 10): Category[] {
  const byTag = agents.reduce((acc, agent) => {
    const key = agent.tag || "geral";
    if (!acc[key]) acc[key] = [];
    if (!acc[key].includes(agent.name)) {
      acc[key].push(agent.name);
    }
    return acc;
  }, {} as Record<string, string[]>);

  const categories = Object.entries(byTag)
    .map(([title, items]) => ({
      title: title.charAt(0).toUpperCase() + title.slice(1),
      items: items.slice(0, maxPerCategory),
    }))
    .filter((cat) => cat.items.length > 0);

  return categories;
}

export function getHeroAgent(agents: AgentFull[]): AgentFull | null {
  if (!agents.length) return null;
  const prioritized = agents.filter((a) => a.role === "mentor");
  return prioritized[0] || agents[0] || null;
}

// CLIENT ONLY — runs in browser only
// Handles localStorage cache for learned answers

const CACHE_KEY = "mente_ai_lab_cache";
const CACHE_VERSION = "v1";
const MAX_CACHE_SIZE = 50; // keep last 50 answers

export function normalizeQuestion(q: string): string {
  return q
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-z0-9 ]/g, "")
    .replace(/\s+/g, " ")
    .trim();
}

export function findInLocalCache(question: string) {
  try {
    const normalized = normalizeQuestion(question);
    const raw = localStorage.getItem(`${CACHE_KEY}_${CACHE_VERSION}`);
    if (!raw) return null;
    const localCache = JSON.parse(raw);
    return localCache[normalized] || null;
  } catch {
    return null;
  }
}

export function saveToLocalCache(question: string, answer: any) {
  try {
    const normalized = normalizeQuestion(question);
    const raw = localStorage.getItem(`${CACHE_KEY}_${CACHE_VERSION}`) || "{}";
    const localCache = JSON.parse(raw);

    localCache[normalized] = {
      ...answer,
      source: "learned",
      savedAt: Date.now(),
    };

    // Keep only last MAX_CACHE_SIZE entries
    const keys = Object.keys(localCache);
    if (keys.length > MAX_CACHE_SIZE) {
      const oldest = keys
        .map((k) => ({ key: k, ts: localCache[k]?.savedAt || 0 }))
        .sort((a, b) => a.ts - b.ts);
      for (let i = 0; i < oldest.length - MAX_CACHE_SIZE; i++) {
        delete localCache[oldest[i].key];
      }
    }

    localStorage.setItem(`${CACHE_KEY}_${CACHE_VERSION}`, JSON.stringify(localCache));
  } catch (e) {
    console.error("[client-cache] Save failed:", e);
  }
}

/** Monitor unanswered questions for cache expansion */
export function logUnansweredQuestion(question: string) {
  try {
    const raw = localStorage.getItem("mente_ai_unanswered") || "[]";
    const unanswered = JSON.parse(raw);
    unanswered.push({ question: normalizeQuestion(question), timestamp: Date.now() });
    // Keep only last 100
    const trimmed = unanswered.slice(-100);
    localStorage.setItem("mente_ai_unanswered", JSON.stringify(trimmed));
  } catch (error) { console.error('[MENTE.AI] Error in client-cache.ts:', error); }
}

/** Check which questions are available offline */
export function getLocalQuestions(): string[] {
  try {
    const raw = localStorage.getItem(`${CACHE_KEY}_${CACHE_VERSION}`);
    if (!raw) return [];
    return Object.keys(JSON.parse(raw));
  } catch {
    return [];
  }
}

import { drizzle } from "drizzle-orm/mysql2";
import mysql from "mysql2/promise";
import * as schema from "./schema";
import "server-only";

let _pool: any;
let _db: any;

function getPool(): mysql.Pool {
  if (_pool) return _pool as mysql.Pool;

  const url = process.env.DATABASE_URL;
  if (!url) {
    throw new Error(
      "[MENTE.AI] DATABASE_URL não definida. Adicione-a ao .env.local."
    );
  }

  const parsed = new URL(url);

  _pool = mysql.createPool({
    host: parsed.hostname,
    port: parseInt(parsed.port || "4000"),
    user: parsed.username,
    password: decodeURIComponent(parsed.password),
    database: parsed.pathname.replace("/", ""),
    ssl: { rejectUnauthorized: true },
    waitForConnections: true,
    connectionLimit: 5,
    queueLimit: 0,
  });

  return _pool as mysql.Pool;
}

function getDbInstance(): ReturnType<typeof drizzle> {
  if (_db) return _db as ReturnType<typeof drizzle>;
  _db = drizzle(getPool(), { schema, mode: "default" });
  return _db as ReturnType<typeof drizzle>;
}

export { getDbInstance as getDb };

export const db: ReturnType<typeof drizzle> = new Proxy(
  {} as ReturnType<typeof drizzle>,
  {
    get(_target, prop) {
      const instance = getDbInstance();
      const value = (instance as unknown as Record<string | symbol, unknown>)[prop];
      if (typeof value === "function") {
        return (value as Function).bind(instance);
      }
      return value;
    },
  }
);

export const pool: mysql.Pool = new Proxy({} as mysql.Pool, {
  get(_target, prop) {
    const p = getPool();
    const value = (p as unknown as Record<string | symbol, unknown>)[prop];
    if (typeof value === "function") {
      return (value as Function).bind(p);
    }
    return value;
  },
});

