/**
 * identity-profiler.ts — Perfilador de Identidade de Longo Prazo.
 *
 * Analisa padrões de memória consolidada para gerar traços de identidade
 * de alto nível, similar a traços de personalidade em psicologia cognitiva.
 *
 * IMPORTANTE: Este módulo NÃO faz diagnóstico psicológico.
 * Ele detecta PADRÕES DE INTERAÇÃO com agentes AI, não traços clínicos.
 *
 * Traits gerados:
 *   - curiosity_level     (0..1): frequência de perguntas exploratórias
 *   - emotional_openness  (0..1): disposição para expressar emoções
 *   - analytical_depth    (0..1): tendência a raciocínio lógico/analítico
 *   - narrative_engagement(0..1): envolvimento com arcos narrativos
 *   - preference_stability(0..1): consistência de preferências ao longo do tempo
 */

import { eq, desc, sql } from "drizzle-orm";
import { getDb } from "@/lib/db";
import { agentMemories } from "@/lib/db/schema";

// ─── Tipos ────────────────────────────────────────────────────────────────────

export interface IdentityTraits {
  /** 0..1 — frequência de curiosidade e exploração */
  curiosityLevel: number;
  /** 0..1 — abertura para expressão emocional */
  emotionalOpenness: number;
  /** 0..1 — tendência ao pensamento analítico */
  analyticalDepth: number;
  /** 0..1 — envolvimento com narrativas */
  narrativeEngagement: number;
  /** 0..1 — consistência de preferências */
  preferenceStability: number;
  /** Data da última atualização */
  lastUpdated: string;
  /** Quantas memórias foram analisadas */
  sampleSize: number;
}

// ─── Análise ──────────────────────────────────────────────────────────────────

/**
 * Analisa memórias de um usuário e extrai traços de identidade.
 *
 * Usa padrões simples de contagem por tipo de memória para inferir
 * tendências comportamentais — sem LLM, sem diagnóstico.
 */
export async function analyzeIdentity(
  userId: number,
  agentId?: string,
): Promise<IdentityTraits | null> {
  const db = getDb();

  try {
    const conditions = [eq(agentMemories.userId, userId)];
    if (agentId) conditions.push(eq(agentMemories.agentId, agentId));

    // Busca memórias recentes (últimos 90 dias)
    const ninetyDaysAgo = new Date(Date.now() - 90 * 86400 * 1000);
    conditions.push(sql`${agentMemories.createdAt} >= ${ninetyDaysAgo}`);

    const memories = await db
      .select()
      .from(agentMemories)
      .where(sql`${conditions.join(" AND ")}`)
      .orderBy(desc(agentMemories.createdAt))
      .limit(100);

    if (memories.length < 5) return null; // Amostra insuficiente

    const total = memories.length;

    // Contagem por tipo
    const typeCounts = { emotional: 0, factual: 0, preference: 0, narrative: 0 };
    let totalEmotionalWeight = 0;

    for (const m of memories) {
      const type = m.memoryType as keyof typeof typeCounts;
      if (type in typeCounts) typeCounts[type]++;
      totalEmotionalWeight += Math.abs(Number(m.emotionalWeight ?? 0));
    }

    // Traços derivados
    const emotionalOpenness = Math.min(
      1,
      typeCounts.emotional / Math.max(total * 0.3, 1),
    );
    const analyticalDepth = Math.min(
      1,
      (typeCounts.factual + typeCounts.preference) / Math.max(total * 0.4, 1),
    );
    const curiosityLevel = Math.min(
      1,
      typeCounts.factual / Math.max(total * 0.25, 1),
    );
    const narrativeEngagement = Math.min(
      1,
      typeCounts.narrative / Math.max(total * 0.2, 1),
    );

    // Estabilidade de preferências: quantas preferências consolidadas existem
    const consolidatedPrefs = memories.filter(
      (m) =>
        m.memoryType === "preference" &&
        Array.isArray(m.tags) &&
        (m.tags as string[]).includes("consolidated"),
    ).length;

    const preferenceStability = Math.min(
      1,
      consolidatedPrefs / Math.max(typeCounts.preference, 1),
    );

    return {
      curiosityLevel: Math.round(curiosityLevel * 100) / 100,
      emotionalOpenness: Math.round(emotionalOpenness * 100) / 100,
      analyticalDepth: Math.round(analyticalDepth * 100) / 100,
      narrativeEngagement: Math.round(narrativeEngagement * 100) / 100,
      preferenceStability: Math.round(preferenceStability * 100) / 100,
      lastUpdated: new Date().toISOString(),
      sampleSize: total,
    };
  } catch (err) {
    // Silencioso — identidade é non-critical
    return null;
  }
}

/**
 * Formata traços de identidade para injeção no system prompt.
 *
 * Exemplo de saída:
 *   "PERFIL COGNITIVO: curiosidade alta (0.8), abertura emocional moderada (0.5),
 *    engajamento narrativo alto (0.75). Prefere abordagem analítica."
 */
export function formatIdentityContext(traits: IdentityTraits): string {
  const level = (v: number) =>
    v > 0.7 ? "alta" : v > 0.4 ? "moderada" : "baixa";

  const parts: string[] = [];

  if (traits.curiosityLevel > 0.3) {
    parts.push(
      `curiosidade ${level(traits.curiosityLevel)} (${traits.curiosityLevel})`,
    );
  }
  if (traits.emotionalOpenness > 0.3) {
    parts.push(
      `abertura emocional ${level(traits.emotionalOpenness)} (${traits.emotionalOpenness})`,
    );
  }
  if (traits.analyticalDepth > 0.3) {
    parts.push(
      `profundidade analítica ${level(traits.analyticalDepth)} (${traits.analyticalDepth})`,
    );
  }
  if (traits.narrativeEngagement > 0.3) {
    parts.push(
      `engajamento narrativo ${level(traits.narrativeEngagement)} (${traits.narrativeEngagement})`,
    );
  }

  if (parts.length === 0) return "";

  return `\n\n--- PERFIL COGNITIVO DO USUÁRIO ---\n${parts.join(", ")}.\nAdapte o tom e a profundidade da resposta a este perfil, sem mencioná-lo explicitamente.`;
}

/**
 * memory-consolidator.ts — Motor de Consolidação de Memória de Longo Prazo.
 *
 * Inspirado na consolidação da memória humana:
 *   - Memórias similares são agrupadas (clustering semântico)
 *   - Grupos são comprimidos em resumos abstratos (sumarização)
 *   - Memórias originais expiram, resumos persistem (compressão)
 *
 * O ciclo de consolidação é executado periodicamente (cron job)
 * e transforma memórias episódicas em conhecimento consolidado.
 *
 * CAMADAS DE MEMÓRIA:
 *   RAW (episódica) → CLUSTERED (agrupada) → CONSOLIDATED (comprimida)
 *
 * Exemplo:
 *   RAW:     "ansioso com IA", "medo de tecnologia", "preocupado com futuro"
 *   CLUSTER: Grupo temático "ansiedade_tecnologica" (3 memórias)
 *   CONSOL:  "Padrão recorrente de ansiedade sobre impacto tecnológico e IA"
 */

import { eq, and, gte, sql, inArray, lt } from "drizzle-orm";
import { getDb } from "@/lib/db";
import { agentMemories, type AgentMemory } from "@/lib/db/schema";
import { findSemanticMatches } from "./semantic-memory";
import { logger } from "@/lib/logger";

// ─── Constantes ───────────────────────────────────────────────────────────────

/** Mínimo de memórias similares para formar um cluster */
const MIN_CLUSTER_SIZE = 3;
/** Similaridade mínima para considerar duas memórias relacionadas */
const CLUSTER_SIMILARITY_THRESHOLD = 0.15;
/** Máximo de clusters processados por execução (evita sobrecarga) */
const MAX_CLUSTERS_PER_RUN = 5;
/** Idade mínima (horas) para memória ser candidata à consolidação */
const MIN_AGE_HOURS = 24;
/** TTL reduzido para memórias consolidadas (7 dias vs 90) */
const CONSOLIDATED_TTL_DAYS = 7;

// ─── Tipos ────────────────────────────────────────────────────────────────────

interface MemoryCluster {
  /** Tema central do cluster (tópico mais frequente) */
  theme: string;
  /** Memórias que pertencem a este cluster */
  memories: AgentMemory[];
  /** Score médio de similaridade interna */
  cohesion: number;
  /** Tipo de memória dominante no cluster */
  dominantType: string;
}

interface ConsolidatedMemory {
  /** Resumo comprimido do cluster */
  summary: string;
  /** Tipo dominante */
  type: string;
  /** Peso emocional médio do cluster */
  emotionalWeight: number;
  /** Quantas memórias foram consolidadas */
  sourceCount: number;
  /** IDs das memórias originais (para marcar como consolidadas) */
  sourceIds: string[];
}

// ─── Clustering ───────────────────────────────────────────────────────────────

/**
 * Agrupa memórias por similaridade semântica usando TF-IDF.
 *
 * Algoritmo:
 *   1. Para cada memória, busca as top-K mais similares
 *   2. Agrupa em clusters com similaridade mútua > threshold
 *   3. Filtra clusters com tamanho >= MIN_CLUSTER_SIZE
 */
function buildClusters(memories: AgentMemory[]): MemoryCluster[] {
  if (memories.length < MIN_CLUSTER_SIZE) return [];

  const assigned = new Set<string>();
  const clusters: MemoryCluster[] = [];

  for (const seed of memories) {
    if (assigned.has(seed.id)) continue;

    const matches = findSemanticMatches(
      seed.content,
      memories.filter((m) => m.id !== seed.id),
      memories.length,
      CLUSTER_SIMILARITY_THRESHOLD,
    );

    // Coleta memórias similares não atribuídas
    const clusterMembers: AgentMemory[] = [seed];
    let totalScore = 0;

    for (const match of matches) {
      if (!assigned.has(match.memory.id)) {
        clusterMembers.push(match.memory);
        totalScore += match.score;
      }
    }

    if (clusterMembers.length >= MIN_CLUSTER_SIZE) {
      // Marca como atribuídas
      for (const m of clusterMembers) {
        assigned.add(m.id);
      }

      // Determina tipo dominante
      const typeCounts = new Map<string, number>();
      for (const m of clusterMembers) {
        typeCounts.set(m.memoryType, (typeCounts.get(m.memoryType) ?? 0) + 1);
      }
      let dominantType = "factual";
      let maxCount = 0;
      for (const [t, c] of typeCounts) {
        if (c > maxCount) {
          maxCount = c;
          dominantType = t;
        }
      }

      clusters.push({
        theme: extractTheme(clusterMembers),
        memories: clusterMembers,
        cohesion: clusterMembers.length > 1
          ? totalScore / (clusterMembers.length - 1)
          : 1,
        dominantType,
      });
    }
  }

  return clusters;
}

// ─── Extração de Tema ─────────────────────────────────────────────────────────

/**
 * Extrai o tema central de um cluster baseado nas palavras mais frequentes.
 */
function extractTheme(memories: AgentMemory[]): string {
  const wordFreq = new Map<string, number>();
  const stopwords = new Set([
    "usuário", "usuaria", "expressou", "detectada", "detectado",
    "compreendeu", "aprendeu", "demonstrou", "durante", "sobre",
    "para", "com", "uma", "que", "não", "foi",
  ]);

  for (const m of memories) {
    const words = m.content
      .toLowerCase()
      .replace(/[^a-záàâãéêíóôõúüç\s-]/g, " ")
      .split(/\s+/)
      .filter((w) => w.length >= 3 && !stopwords.has(w));

    for (const w of words) {
      wordFreq.set(w, (wordFreq.get(w) ?? 0) + 1);
    }
  }

  // Top 3 palavras mais frequentes como tema
  const sorted = [...wordFreq.entries()]
    .sort((a, b) => b[1] - a[1])
    .slice(0, 3)
    .map(([w]) => w);

  return sorted.join("_");
}

// ─── Sumarização ──────────────────────────────────────────────────────────────

/**
 * Gera um resumo comprimido de um cluster de memórias.
 *
 * Usa heurísticas linguísticas (sem LLM) para comprimir:
 *   - Extrai frases comuns entre memórias
 *   - Detecta padrão temporal ("recorrente", "frequente")
 *   - Preserva carga emocional
 */
function summarizeCluster(cluster: MemoryCluster): ConsolidatedMemory {
  const count = cluster.memories.length;
  const avgWeight =
    cluster.memories.reduce(
      (sum, m) => sum + Math.abs(Number(m.emotionalWeight ?? 0)),
      0,
    ) / count;

  // Template por tipo de memória dominante
  const templates: Record<string, string> = {
    emotional: `Padrão emocional recorrente (${count} ocorrências): ${cluster.theme.replace(/_/g, " ")}`,
    factual: `Conhecimento consolidado (${count} interações): ${cluster.theme.replace(/_/g, " ")}`,
    preference: `Preferência consistente detectada (${count} confirmações): ${cluster.theme.replace(/_/g, " ")}`,
    narrative: `Arco narrativo recorrente (${count} eventos): ${cluster.theme.replace(/_/g, " ")}`,
  };

  const summary =
    templates[cluster.dominantType] ??
    `Memória consolidada (${count} ocorrências): ${cluster.theme.replace(/_/g, " ")}`;

  return {
    summary,
    type: cluster.dominantType,
    emotionalWeight: Math.min(1, avgWeight),
    sourceCount: count,
    sourceIds: cluster.memories.map((m) => m.id),
  };
}

// ─── API Principal ────────────────────────────────────────────────────────────

export interface ConsolidationResult {
  /** Quantos clusters foram formados */
  clustersFound: number;
  /** Quantas memórias consolidadas foram criadas */
  consolidatedCreated: number;
  /** Quantas memórias originais foram marcadas para expiração */
  sourcesExpired: number;
  /** Detalhes dos clusters para debug */
  details: Array<{
    theme: string;
    count: number;
    cohesion: number;
    summary: string;
  }>;
}

/**
 * Executa um ciclo de consolidação de memória.
 *
 * Deve ser chamado periodicamente (cron job diário).
 *
 * @param userId  ID do usuário (ou undefined para todos)
 * @param agentId ID do agente (ou undefined para todos)
 */
export async function runConsolidationCycle(params?: {
  userId?: number;
  agentId?: string;
}): Promise<ConsolidationResult> {
  const db = getDb();
  const result: ConsolidationResult = {
    clustersFound: 0,
    consolidatedCreated: 0,
    sourcesExpired: 0,
    details: [],
  };

  try {
    // Busca memórias não consolidadas com idade >= MIN_AGE_HOURS
    const minDate = new Date(Date.now() - MIN_AGE_HOURS * 3600 * 1000);

    const conditions = [
      // Apenas memórias não consolidadas (tags não contêm "consolidated")
      sql`NOT JSON_CONTAINS(${agentMemories.tags}, '"consolidated"')`,
      gte(agentMemories.createdAt, minDate),
    ];

    if (params?.userId) {
      conditions.push(eq(agentMemories.userId, params.userId));
    }
    if (params?.agentId) {
      conditions.push(eq(agentMemories.agentId, params.agentId));
    }

    const rawMemories = await db
      .select()
      .from(agentMemories)
      .where(and(...conditions))
      .limit(200); // Limite de segurança

    if (rawMemories.length < MIN_CLUSTER_SIZE) {
      return result;
    }

    // 1. Clustering semântico
    const clusters = buildClusters(
      rawMemories as unknown as AgentMemory[],
    ).slice(0, MAX_CLUSTERS_PER_RUN);

    result.clustersFound = clusters.length;

    // 2. Para cada cluster: sumarizar e armazenar
    for (const cluster of clusters) {
      const consolidated = summarizeCluster(cluster);

      // Armazena a memória consolidada
      const memoryId = crypto.randomUUID?.() ??
        `${Date.now()}-${Math.random().toString(36).slice(2, 10)}`;

      await db
        .insert(agentMemories)
        .values({
          id: memoryId,
          userId: cluster.memories[0].userId,
          agentId: cluster.memories[0].agentId,
          memoryType: consolidated.type as typeof cluster.memories[0]["memoryType"],
          content: consolidated.summary,
          emotionalWeight: String(consolidated.emotionalWeight),
          tags: ["consolidated", `cluster:${cluster.theme}`],
          contexto: {
            sourceCount: consolidated.sourceCount,
            cohesion: Math.round(cluster.cohesion * 100) / 100,
            consolidatedAt: new Date().toISOString(),
          },
          ttlDays: CONSOLIDATED_TTL_DAYS,
          expiresAt: new Date(
            Date.now() + CONSOLIDATED_TTL_DAYS * 86400 * 1000,
          ),
          accessCount: 0,
          createdAt: new Date(),
        })
        .catch((err) => {
          logger.warn("Falha ao armazenar memória consolidada", {
            theme: cluster.theme,
            error: String(err),
          });
        });

      // Marca originais para expiração rápida (serão removidas pelo cleanup)
      const sourceIds = consolidated.sourceIds;
      if (sourceIds.length > 0) {
        await db
          .update(agentMemories)
          .set({
            ttlDays: CONSOLIDATED_TTL_DAYS,
          })
          .where(inArray(agentMemories.id, sourceIds))
          .catch(() => {
            // Non-critical
          });
      }

      result.consolidatedCreated++;
      result.sourcesExpired += consolidated.sourceCount;
      result.details.push({
        theme: cluster.theme,
        count: cluster.memories.length,
        cohesion: Math.round(cluster.cohesion * 100) / 100,
        summary: consolidated.summary,
      });
    }

    if (result.clustersFound > 0) {
      logger.info("Ciclo de consolidação concluído", {
        clusters: result.clustersFound,
        consolidated: result.consolidatedCreated,
        expired: result.sourcesExpired,
      });
    }
  } catch (err) {
    logger.error("Falha no ciclo de consolidação", { error: String(err) });
  }

  return result;
}

/**
 * Retorna estatísticas de consolidação para debug/monitoramento.
 */
export async function getConsolidationStats(params?: {
  userId?: number;
  agentId?: string;
}): Promise<{
  totalMemories: number;
  consolidatedMemories: number;
  consolidationRatio: number;
}> {
  const db = getDb();

  const conditions = [];
  if (params?.userId) conditions.push(eq(agentMemories.userId, params.userId));
  if (params?.agentId) conditions.push(eq(agentMemories.agentId, params.agentId));

  const total = await db
    .select({ count: sql<number>`count(*)` })
    .from(agentMemories)
    .where(conditions.length > 0 ? and(...conditions) : undefined);

  const consolidated = await db
    .select({ count: sql<number>`count(*)` })
    .from(agentMemories)
    .where(
      and(
        ...(conditions.length > 0 ? conditions : [sql`1=1`]),
        sql`JSON_CONTAINS(${agentMemories.tags}, '"consolidated"')`,
      ),
    );

  return {
    totalMemories: total[0]?.count ?? 0,
    consolidatedMemories: consolidated[0]?.count ?? 0,
    consolidationRatio:
      (total[0]?.count ?? 0) > 0
        ? (consolidated[0]?.count ?? 0) / (total[0]?.count ?? 1)
        : 0,
  };
}

/**
 * memory-orchestrator.ts — Orquestrador híbrido de recuperação de memória.
 *
 * Combina três sinais de relevância em um ranking unificado:
 *
 *   1. RECÊNCIA (recency)          — memórias mais novas pesam mais
 *   2. PESO EMOCIONAL (emotional)  — memórias com carga emocional pesam mais
 *   3. SIMILARIDADE SEMÂNTICA      — TF-IDF cosine similarity com a query
 *
 * Score final = (recency × w1) + (emotional × w2) + (semantic × w3)
 *
 * Os pesos são ajustáveis por agente, permitindo que:
 *   - TERRA priorize memórias emocionais (emotional weight alto)
 *   - AXIOM priorize similaridade factual (semantic weight alto)
 *   - NEXUS use balanceamento padrão
 */

import type { AgentMemory, MemoryType } from "@/lib/db/schema";
import { findSemanticMatches, type SemanticMatch } from "./semantic-memory";

// ─── Tipos ────────────────────────────────────────────────────────────────────

export interface RetrievalWeights {
  /** Peso da recência (0..1, padrão 0.3) */
  recency: number;
  /** Peso da carga emocional (0..1, padrão 0.3) */
  emotional: number;
  /** Peso da similaridade semântica (0..1, padrão 0.4) */
  semantic: number;
}

export interface RankedMemory {
  memory: AgentMemory;
  finalScore: number;   // 0..1
  recencyScore: number;  // 0..1
  emotionalScore: number;// 0..1
  semanticScore: number; // 0..1
}

// ─── Pesos por tipo de agente ─────────────────────────────────────────────────

const DEFAULT_WEIGHTS: RetrievalWeights = {
  recency: 0.3,
  emotional: 0.3,
  semantic: 0.4,
};

/**
 * Pesos customizados por dimensão do agente.
 * Agentes emocionais priorizam carga emocional;
 * agentes analíticos priorizam similaridade semântica.
 */
const AGENT_WEIGHTS: Record<string, RetrievalWeights> = {
  // Emocionais: priorizam peso emocional
  terra: { recency: 0.2, emotional: 0.5, semantic: 0.3 },
  lyra: { recency: 0.2, emotional: 0.5, semantic: 0.3 },
  // Analíticos: priorizam similaridade semântica
  axiom: { recency: 0.2, emotional: 0.15, semantic: 0.65 },
  cipher: { recency: 0.15, emotional: 0.2, semantic: 0.65 },
  stratos: { recency: 0.2, emotional: 0.15, semantic: 0.65 },
  // Criativos: balanceamento
  aurora: { recency: 0.25, emotional: 0.4, semantic: 0.35 },
  kaos: { recency: 0.2, emotional: 0.45, semantic: 0.35 },
  // Éticos: priorizam narrativa
  ethos: { recency: 0.25, emotional: 0.35, semantic: 0.4 },
  prism: { recency: 0.2, emotional: 0.35, semantic: 0.45 },
  // Padrão para os demais
  nexus: { recency: 0.3, emotional: 0.3, semantic: 0.4 },
  volt: { recency: 0.3, emotional: 0.3, semantic: 0.4 },
  janus: { recency: 0.25, emotional: 0.4, semantic: 0.35 },
};

// ─── Funções de scoring ───────────────────────────────────────────────────────

/** Score de recência: memórias mais novas → score mais alto */
function computeRecencyScore(memory: AgentMemory): number {
  const now = Date.now();
  const created = memory.createdAt
    ? new Date(memory.createdAt).getTime()
    : now;
  const ageHours = (now - created) / (1000 * 60 * 60);

  // Decaimento exponencial: meia-vida de 7 dias (168 horas)
  return Math.exp(-ageHours / 168);
}

/** Score emocional: |emotionalWeight| normalizado para 0..1 */
function computeEmotionalScore(memory: AgentMemory): number {
  const weight = Number(memory.emotionalWeight ?? 0);
  return Math.abs(weight); // 0..1
}

/** Normaliza scores semânticos para o intervalo 0..1 */
function normalizeSemanticScores(
  matches: SemanticMatch[],
): Map<string, number> {
  const map = new Map<string, number>();
  if (matches.length === 0) return map;

  const maxScore = matches[0]?.score ?? 1;
  for (const match of matches) {
    // Normaliza: score / maxScore para manter proporções
    map.set(match.memory.id, match.score / Math.max(maxScore, 0.01));
  }
  return map;
}

// ─── API Principal ────────────────────────────────────────────────────────────

/**
 * Recupera e ranqueia memórias usando scoring híbrido.
 *
 * @param query      Texto da mensagem do usuário (para matching semântico)
 * @param memories   Pool de memórias candidatas (já filtradas por userId + agentId)
 * @param agentId    ID do agente para selecionar pesos customizados
 * @param topK       Quantas memórias retornar no ranking final
 * @returns          Memórias ranqueadas por score final (maior primeiro)
 */
export function rankMemories(
  query: string,
  memories: AgentMemory[],
  agentId: string,
  topK: number = 5,
): RankedMemory[] {
  if (memories.length === 0) return [];

  const weights = AGENT_WEIGHTS[agentId] ?? DEFAULT_WEIGHTS;

  // 1. Busca semântica
  const semanticMatches = findSemanticMatches(query, memories, memories.length, 0.02);
  const semanticMap = normalizeSemanticScores(semanticMatches);

  // 2. Computa scores individuais e combina
  const ranked: RankedMemory[] = memories.map((memory) => {
    const recencyScore = computeRecencyScore(memory);
    const emotionalScore = computeEmotionalScore(memory);
    const semanticScore = semanticMap.get(memory.id) ?? 0;

    // Score final = soma ponderada
    const finalScore =
      recencyScore * weights.recency +
      emotionalScore * weights.emotional +
      semanticScore * weights.semantic;

    return {
      memory,
      finalScore: Math.min(1, Math.max(0, finalScore)),
      recencyScore,
      emotionalScore,
      semanticScore,
    };
  });

  // 3. Ordena por score final e retorna topK
  return ranked
    .sort((a, b) => b.finalScore - a.finalScore)
    .slice(0, topK);
}

/**
 * Formata memórias ranqueadas para injeção no system prompt.
 * Similar ao getMemoryContext() mas com scoring híbrido.
 */
export function formatRankedMemories(
  ranked: RankedMemory[],
  maxChars: number = 600,
): string {
  if (ranked.length === 0) return "";

  const lines: string[] = [];

  for (const r of ranked) {
    const prefix =
      r.memory.memoryType === "emotional"
        ? "🧠"
        : r.memory.memoryType === "factual"
          ? "📚"
          : r.memory.memoryType === "preference"
            ? "⭐"
            : "📖";

    const relevance =
      r.finalScore > 0.7 ? "↑" : r.finalScore > 0.4 ? "→" : "↓";

    lines.push(
      `${prefix}${relevance} [${r.memory.memoryType}] ${r.memory.content}`,
    );
  }

  let result = `\n\n--- MEMÓRIAS PERSISTENTES (busca semântica) ---\n${lines.join("\n")}\nUse estas memórias para personalizar sua resposta, mas não as mencione explicitamente a menos que seja relevante.`;

  // Trunca se exceder limite de caracteres
  if (result.length > maxChars) {
    result = result.slice(0, maxChars - 3) + "...";
  }

  return result;
}

/**
 * Retorna os pesos de retrieval para um agente específico.
 * Útil para debugging e ajuste fino.
 */
export function getAgentWeights(agentId: string): RetrievalWeights {
  return AGENT_WEIGHTS[agentId] ?? DEFAULT_WEIGHTS;
}

/**
 * memory-recall.ts — Motor de Recall Moments (Momentos de Recordação Controlada).
 *
 * Permite que agentes façam referências SUTIS e NATURAIS a interações
 * passadas significativas, criando uma percepção de continuidade
 * narrativa sem parecer artificial ou obsessivo.
 *
 * PRINCÍPIOS:
 *   - Recall é OPCIONAL ("Se for natural, você pode mencionar...")
 *   - Cooldown entre recalls (mínimo 5 interações entre menções)
 *   - Probabilístico (nem toda oportunidade gera recall)
 *   - Agent-specific (cada agente expressa recall no seu tom)
 *   - Token-efficient (diretiva de UMA frase)
 *
 * EXEMPLOS DE BOM RECALL:
 *   "Você parece mais confiante sobre ética de IA do que antes."
 *   "Este tema ecoa questões que você explorou com outros agentes."
 *   "Sua forma de raciocinar sobre isso amadureceu visivelmente."
 *
 * EXEMPLOS PROIBIDOS:
 *   "Eu me lembro perfeitamente de tudo que você disse."
 *   "Tenho pensado muito sobre nossas conversas."
 *   "Você é uma pessoa especial para mim."
 */

import type { AgentMemory } from "@/lib/db/schema";
import { getDb } from "@/lib/db";
import { agentMemories } from "@/lib/db/schema";
import { eq, and, desc, sql } from "drizzle-orm";
import { findSemanticMatches } from "./semantic-memory";

// ─── Constantes ───────────────────────────────────────────────────────────────

/** Mínimo de interações entre recall moments (cooldown) */
const RECALL_COOLDOWN = 5;
/** Probabilidade base de recall quando triggers são detectados */
const RECALL_PROBABILITY = 0.35;
/** Mínimo de memórias totais para considerar recall */
const MIN_MEMORIES_FOR_RECALL = 5;
/** Tamanho máximo da diretiva de recall (caracteres) */
const MAX_RECALL_DIRECTIVE_CHARS = 250;

// ─── Tipos ────────────────────────────────────────────────────────────────────

export type RecallTrigger =
  | "emotional_recurrence"    // Tema emocional apareceu 2+ vezes
  | "conceptual_evolution"    // Usuário demonstrou evolução em um conceito
  | "learning_milestone"      // Primeira vez que usuário demonstra domínio
  | "narrative_echo"          // Tema atual ecoa conversa passada significativa
  | "preference_reinforcement" // Preferência reafirmada após intervalo
  | "cross_agent_pattern";    // Padrão detectado entre múltiplos agentes

export interface RecallOpportunity {
  trigger: RecallTrigger;
  /** Score de relevância (0..1) — quanto maior, mais pertinente */
  relevance: number;
  /** A memória específica que gerou o recall (se aplicável) */
  sourceMemory?: AgentMemory;
  /** Contexto narrativo para o agente */
  narrativeContext: string;
}

export interface RecallDirective {
  /** A diretiva textual para injetar no system prompt */
  directive: string;
  /** O trigger que gerou o recall */
  trigger: RecallTrigger;
  /** Se deve ser aplicado (probabilístico + cooldown) */
  shouldApply: boolean;
}

// ─── Cooldown Tracker (in-memory — reseta entre deploys) ──────────────────────

const cooldownTracker = new Map<string, number>(); // key: "userId:agentId" → lastRecallIndex

function isOnCooldown(userId: number, agentId: string, currentIndex: number): boolean {
  const key = `${userId}:${agentId}`;
  const lastRecall = cooldownTracker.get(key) ?? -RECALL_COOLDOWN;
  return currentIndex - lastRecall < RECALL_COOLDOWN;
}

function setCooldown(userId: number, agentId: string, currentIndex: number): void {
  cooldownTracker.set(`${userId}:${agentId}`, currentIndex);
  // Limpeza periódica do tracker (evita memory leak)
  if (cooldownTracker.size > 1000) {
    const keys = [...cooldownTracker.keys()].slice(0, 200);
    for (const k of keys) cooldownTracker.delete(k);
  }
}

// ─── Detecção de Triggers ─────────────────────────────────────────────────────

/**
 * Analisa memórias e detecta oportunidades de recall.
 *
 * Triggers detectados:
 *   1. EMOTIONAL_RECURRENCE: mesmo tema emocional aparece 2+ vezes
 *   2. CONCEPTUAL_EVOLUTION: usuário mostra compreensão mais profunda
 *   3. LEARNING_MILESTONE: primeira memória factual após várias emocionais
 *   4. NARRATIVE_ECHO: mensagem atual é semanticamente similar a memória antiga
 *   5. PREFERENCE_REINFORCEMENT: preferência aparece novamente após intervalo
 */
async function detectRecallOpportunities(params: {
  userId: number;
  agentId: string;
  userMessage: string;
  interactionIndex: number;
}): Promise<RecallOpportunity[]> {
  const opportunities: RecallOpportunity[] = [];

  try {
    const db = getDb();

    // Busca memórias recentes (últimas 30)
    const memories = await db
      .select()
      .from(agentMemories)
      .where(
        and(
          eq(agentMemories.userId, params.userId),
          eq(agentMemories.agentId, params.agentId),
        ),
      )
      .orderBy(desc(agentMemories.createdAt))
      .limit(30);

    if (memories.length < MIN_MEMORIES_FOR_RECALL) return [];

    const typedMemories = memories as unknown as AgentMemory[];

    // Trigger 1: EMOTIONAL_RECURRENCE
    const emotionalMems = typedMemories.filter((m) => m.memoryType === "emotional");
    if (emotionalMems.length >= 2) {
      // Verifica se há clusters semânticos entre memórias emocionais
      const emotionalTexts = emotionalMems.map((m) => m.content).join(" ");
      const hasRecurrence =
        /(ansied|preocup|medo|insegur)/i.test(emotionalTexts) &&
        emotionalMems.length >= 2;

      if (hasRecurrence) {
        opportunities.push({
          trigger: "emotional_recurrence",
          relevance: 0.6,
          sourceMemory: emotionalMems[0],
          narrativeContext:
            "Temas emocionais relacionados à ansiedade/preocupação têm aparecido em várias conversas.",
        });
      }
    }

    // Trigger 2: CONCEPTUAL_EVOLUTION
    const factualMems = typedMemories.filter((m) => m.memoryType === "factual");
    if (factualMems.length >= 3) {
      // Verifica se há progressão conceitual (memórias factuais mais recentes)
      const recentFactuals = factualMems.slice(0, 3);
      const olderFactuals = factualMems.slice(3);

      if (olderFactuals.length > 0) {
        opportunities.push({
          trigger: "conceptual_evolution",
          relevance: 0.55,
          sourceMemory: recentFactuals[0],
          narrativeContext:
            "O usuário demonstra compreensão cada vez mais profunda dos conceitos discutidos.",
        });
      }
    }

    // Trigger 3: LEARNING_MILESTONE
    if (
      factualMems.length === 1 &&
      emotionalMems.length >= 4 &&
      params.interactionIndex > 10
    ) {
      opportunities.push({
        trigger: "learning_milestone",
        relevance: 0.7,
        sourceMemory: factualMems[0],
        narrativeContext:
          "Esta é uma das primeiras vezes que o usuário demonstra compreensão factual após um período de exploração emocional.",
      });
    }

    // Trigger 4: NARRATIVE_ECHO (busca semântica)
    if (params.userMessage.trim().length >= 20) {
      const semanticMatches = findSemanticMatches(
        params.userMessage,
        typedMemories,
        1,
        0.15,
      );

      if (semanticMatches.length > 0 && semanticMatches[0].score > 0.25) {
        const match = semanticMatches[0];
        const ageHours =
          (Date.now() -
            new Date(match.memory.createdAt ?? Date.now()).getTime()) /
          (3600 * 1000);

        // Só considera echo se a memória tem pelo menos 6 horas
        if (ageHours > 6) {
          opportunities.push({
            trigger: "narrative_echo",
            relevance: match.score,
            sourceMemory: match.memory,
            narrativeContext: `A conversa atual ecoa um tema de ${Math.round(ageHours)}h atrás: "${match.memory.content.slice(0, 100)}"`,
          });
        }
      }
    }

    // Trigger 5: PREFERENCE_REINFORCEMENT
    const prefMems = typedMemories.filter((m) => m.memoryType === "preference");
    if (prefMems.length >= 2) {
      const recent = prefMems[0];
      const older = prefMems.slice(1).find(
        (m) =>
          m.createdAt &&
          recent.createdAt &&
          new Date(recent.createdAt).getTime() -
            new Date(m.createdAt).getTime() >
            86400 * 1000, // 24h+ de intervalo
      );

      if (older) {
        opportunities.push({
          trigger: "preference_reinforcement",
          relevance: 0.5,
          sourceMemory: recent,
          narrativeContext:
            "O usuário reafirmou uma preferência que já havia demonstrado anteriormente.",
        });
      }
    }
  } catch {
    // Silencioso — recall é enhancement
  }

  return opportunities;
}

