import { PLATFORM_SECTIONS, UNLOCK_TYPES } from "./types";

// ─── SECTION ROUTE MAP ────────────────────────────────────────────────────────

export const SECTION_ROUTES: Record<PlatformSection, string> = {
  home: "/home",
