/**
 * ─── NEXUS EVENTS — Governed Event Channels ───────────────────────────────────
 *
 * The Nexus wraps the existing universeBus with a governance layer that:
 *   1. Preserves ALL existing event contracts (zero breaking changes)
 *   2. Adds 3 new event channels: MEMORY_SYNC, AGENT_LIFECYCLE, RUNTIME_HEALTH
 *   3. Enforces authority rules (agents can't emit directly without Nexus approval)
 *   4. Tracks event provenance for debugging and conflict resolution
 *
 * The universeBus singleton is NOT modified. This file adds a governance wrapper
 * that sits between agents and the bus, enforcing Nexus authority.
 *
 * PHASE 0: Foundation Hardening — Extraction (not rewrite)
 */

import { universeBus, type UniverseEvent, type UniverseEventType, type UniverseSubscriber } from "../universe/event-bus";
import type { PlanetId, PlanetState } from "../universe/planet-registry";
import type { AgentLifecycleState, AgentAuthorityScope, NexusHealthMetrics } from "./nexus.types";

// ═══════════════════════════════════════════════════════════════════════════════
// EXISTING EVENT CONTRACTS (PRESERVED — NO CHANGES)
// ═══════════════════════════════════════════════════════════════════════════════

// Re-export ALL existing event types so nothing breaks.
// Components importing from nexus.events get the full event catalog.
export type {
  UniverseEvent,
  UniverseEventType,
  UniverseSubscriber,
} from "../universe/event-bus";

// ═══════════════════════════════════════════════════════════════════════════════
// NEW EVENT CHANNEL #1: MEMORY_SYNC
// ═══════════════════════════════════════════════════════════════════════════════

/**
 * MEMORY_SYNC events govern synchronization between Memory Keeper and Nexus.
 *
 * Memory Keeper is the canonical owner of User Cognitive Profile data.
 * When Memory Keeper updates a profile, it emits a MEMORY_SYNC event.
 * Nexus listens and updates its runtime cache — but NEVER modifies the canonical copy.
 */
export type MemorySyncEvent =
  | {
      type: "MEMORY_SYNC";
      subtype: "PROFILE_UPDATED";
      /** User ID affected */
      userId: number;
      /** What field was updated */
      field: string;
      /** New value (serializable) */
      newValue: unknown;
      /** Previous value for rollback */
      previousValue: unknown;
      /** Agent that triggered the update */
      sourceAgentId: string;
    }
  | {
      type: "MEMORY_SYNC";
      subtype: "INSIGHT_STORED";
      /** User ID */
      userId: number;
      /** The stored insight */
      insight: string;
      /** Which planet context this insight belongs to */
      planetId: PlanetId;
      /** Agent that generated the insight */
      sourceAgentId: string;
    }
  | {
      type: "MEMORY_SYNC";
      subtype: "CONTEXT_COMPACTION_REQUESTED";
      /** Which planet needs compaction */
      planetId: PlanetId;
      /** Current token count (triggers compaction if over limit) */
      currentTokens: number;
      /** Max allowed for this planet */
      maxTokens: number;
    }
  | {
      type: "MEMORY_SYNC";
      subtype: "MEMORY_HEALTH_CHECK";
      /** Total entries in memory store */
      totalEntries: number;
      /** Estimated total token count */
      estimatedTokens: number;
      /** Memory domains active */
      activeDomains: string[];
    };

// ═══════════════════════════════════════════════════════════════════════════════
// NEW EVENT CHANNEL #2: AGENT_LIFECYCLE
// ═══════════════════════════════════════════════════════════════════════════════

/**
 * AGENT_LIFECYCLE events track agent state transitions.
 *
 * Only the Nexus may emit AGENT_LIFECYCLE events.
 * Agents request state changes via delta proposals — never directly.
 */
export type AgentLifecycleEvent =
  | {
      type: "AGENT_LIFECYCLE";
      subtype: "REGISTERED";
      /** Agent that was registered */
      agentId: string;
      /** Scope injected at registration */
      scope: AgentAuthorityScope;
    }
  | {
      type: "AGENT_LIFECYCLE";
      subtype: "STATE_TRANSITION";
      /** Agent transitioning */
      agentId: string;
      /** Previous state */
      fromState: AgentLifecycleState;
      /** New state */
      toState: AgentLifecycleState;
      /** Human-readable reason */
      reason: string;
    }
  | {
      type: "AGENT_LIFECYCLE";
      subtype: "ERROR_THRESHOLD_EXCEEDED";
      /** Agent that hit the error threshold */
      agentId: string;
      /** Consecutive error count */
      errorCount: number;
      /** Action taken (suspended | terminated) */
      action: "suspended" | "terminated";
    }
  | {
      type: "AGENT_LIFECYCLE";
      subtype: "SCOPE_UPDATED";
      /** Agent whose scope changed */
      agentId: string;
      /** Previous scope */
      previousScope: AgentAuthorityScope;
      /** New scope */
      newScope: AgentAuthorityScope;
    };

// ═══════════════════════════════════════════════════════════════════════════════
// NEW EVENT CHANNEL #3: RUNTIME_HEALTH
// ═══════════════════════════════════════════════════════════════════════════════

/**
 * RUNTIME_HEALTH events broadcast runtime status for monitoring.
 *
 * Emitted by the Nexus on every state change, on a periodic heartbeat,
 * and when health transitions between healthy/unhealthy.
 */
export type RuntimeHealthEvent =
  | {
      type: "RUNTIME_HEALTH";
      subtype: "HEARTBEAT";
      /** Current health metrics snapshot */
      metrics: NexusHealthMetrics;
      /** Uptime in milliseconds */
      uptimeMs: number;
    }
  | {
      type: "RUNTIME_HEALTH";
      subtype: "STATE_TRANSITION";
      /** Previous health state */
      previousState: "healthy" | "unhealthy";
      /** New health state */
      newState: "healthy" | "unhealthy";
      /** What caused the transition */
      trigger: string;
    }
  | {
      type: "RUNTIME_HEALTH";
      subtype: "CONFLICT_RESOLVED";
      /** The conflict that was resolved */
      conflict: import("./nexus.types").ConflictReport;
      /** How it was resolved */
      resolution: string;
    }
  | {
      type: "RUNTIME_HEALTH";
      subtype: "SYNC_COMPLETED";
      /** Timestamp of last sync */
      syncTimestamp: number;
      /** Agents synchronized */
      syncedAgents: string[];
    };

// ═══════════════════════════════════════════════════════════════════════════════
// UNIFIED NEXUS EVENT TYPE
// ═══════════════════════════════════════════════════════════════════════════════

/**
 * Every event in the MENTE.AI ecosystem.
 *
 * Includes:
 *   - All existing UniverseEvent types (preserved from universeBus)
 *   - 3 new Nexus-governed event channels
 *
 * Subscribers can filter by `type` (UniverseEventType) OR by the new `type` values
 * ("MEMORY_SYNC", "AGENT_LIFECYCLE", "RUNTIME_HEALTH").
 */
export type NexusEvent =
  | UniverseEvent          // Preserved: all 10 existing event types
  | MemorySyncEvent        // New: Memory Keeper ↔ Nexus sync
  | AgentLifecycleEvent    // New: Agent lifecycle transitions
  | RuntimeHealthEvent;    // New: Runtime health monitoring

export type NexusEventType = NexusEvent["type"];

// ═══════════════════════════════════════════════════════════════════════════════
// GOVERNED EVENT BUS — WRAPPER AROUND universeBus
// ═══════════════════════════════════════════════════════════════════════════════

type GovernedSubscriber = {
  eventType: NexusEventType | "*";
  subscriber: (event: NexusEvent) => void;
  id: number;
};

let governedNextId = 0;

/**
 * GovernedEventBus wraps universeBus with authority enforcement.
 *
 * What the wrapper does:
 *   1. ALL events flow through this wrapper — never to universeBus directly
 *   2. Existing universe events are forwarded to universeBus (backward compat)
 *   3. New nexus-only events (MEMORY_SYNC, AGENT_LIFECYCLE, RUNTIME_HEALTH)
 *      are distributed ONLY through this wrapper
 *   4. Authority checks are enforced per agent
 *
 * Usage:
 *   import { nexusBus } from "@/lib/nexus/nexus.events";
 *
 *   // Subscribe (same API as universeBus)
 *   nexusBus.subscribe("AGENT_LIFECYCLE", (event) => { ... });
 *
 *   // Emit (governed — Nexus validates before emitting)
 *   nexusBus.emit({ type: "AGENT_LIFECYCLE", subtype: "REGISTERED", ... });
 */
class GovernedEventBus {
  private subscribers: GovernedSubscriber[] = [];

  /**
   * Emit an event through the governed bus.
   *
   * Rules:
   *   - Universe events (PLANET_UNLOCKED, etc.) → forwarded to universeBus
   *   - Nexus events (MEMORY_SYNC, AGENT_LIFECYCLE, RUNTIME_HEALTH) → local only
   *   - One subscriber crash never affects others
   */
  emit(event: NexusEvent): void {
    const eventType = event.type as NexusEventType;

    // Forward universe events to the existing universeBus for backward compat
    if (isUniverseEvent(event)) {
      universeBus.emit(event);
    }

    // Distribute to governed subscribers
    for (const sub of this.subscribers) {
      if (sub.eventType === "*" || sub.eventType === eventType) {
        try {
          sub.subscriber(event);
        } catch (err) {
          console.error(
            `[GovernedEventBus] Subscriber error for "${eventType}":`,
            err
          );
        }
      }
    }
  }

  /**
   * Subscribe to governed events.
   * Returns an unsubscribe function (cleanup-safe for useEffect).
   */
  subscribe<T extends NexusEvent>(
    eventType: NexusEventType | "*",
    subscriber: (event: T) => void
  ): () => void {
    const id = governedNextId++;
    const sub: GovernedSubscriber = {
      eventType,
      subscriber: subscriber as (event: NexusEvent) => void,
      id,
    };
    this.subscribers.push(sub);

    return () => {
      this.subscribers = this.subscribers.filter((s) => s.id !== id);
    };
  }

  /**
   * Subscribe to universe events directly via the wrapper.
   * Delegates to universeBus.subscribe().
   * Provides a unified subscription API.
   */
  subscribeUniverse<T extends UniverseEvent>(
    eventType: UniverseEventType | "*",
    subscriber: UniverseSubscriber<T>
  ): () => void {
    return universeBus.subscribe(eventType, subscriber);
  }

  /** Remove all subscribers. For testing and cleanup. */
  reset(): void {
    this.subscribers = [];
    universeBus.reset();
  }

  /** Subscriber count across both buses */
  get subscriberCount(): number {
    return this.subscribers.length + universeBus.subscriberCount;
  }
}

// ── TYPE GUARD ────────────────────────────────────────────────────────────────

/** Check if an event is a universe-level event (should forward to universeBus). */
function isUniverseEvent(event: NexusEvent): event is UniverseEvent {
  const universeEventTypes: UniverseEventType[] = [
    "PLANET_UNLOCKED",
    "PLANET_ACTIVATED",
    "PLANET_COMPLETED",
    "SIGNAL_DETECTED",
    "MISSION_COMPLETED",
    "MISSION_FAILED",
    "HINT_GENERATED",
    "PROGRESSION_STATE_CHANGED",
    "AUDIO_STATE_CHANGED",
    "CONTEXT_COMPRESSED",
  ];
  return universeEventTypes.includes(event.type as UniverseEventType);
}

// ═══════════════════════════════════════════════════════════════════════════════
// SINGLETON
// ═══════════════════════════════════════════════════════════════════════════════

/**
 * The single governed event bus for the entire MENTE.AI ecosystem.
 *
 * Import this instead of universeBus in new code.
 * Existing universeBus references continue to work — but new event channels
 * (MEMORY_SYNC, AGENT_LIFECYCLE, RUNTIME_HEALTH) only flow through nexusBus.
 */
export const nexusBus = new GovernedEventBus();

/**
 * Re-export universeBus for backward compatibility.
 * Existing code that imports universeBus directly still works.
 * New code should import nexusBus from this module.
 */
export { universeBus };

/**
 * ─── NEXUS GUARDS — Runtime Validation & Conflict Detection ───────────────────
 *
 * Guards are pure validation functions that the Nexus calls before applying
 * any delta proposal. They enforce:
 *   1. Ownership: who can write what asset (ownership matrix)
 *   2. Cooldown: rate limiting between proposals
 *   3. State validity: is the proposed state transition legal?
 *   4. Conflict detection: two agents trying to write the same asset
 *   5. Authority: does the agent have scope to make this change?
 *
 * ALL guards are synchronous, pure functions — deterministic, testable.
 *
 * PHASE 0: Foundation Hardening — Extraction (not rewrite)
 */

import type { PlanetId } from "../universe/planet-registry";
import type {
  DeltaProposal,
  DeltaProposalType,
  NexusCanonicalState,
  AgentRuntimeRecord,
  AgentLifecycleState,
  ConflictReport,
  OwnershipEntry,
  RuntimeAssetOwner,
} from "./nexus.types";
import { OWNERSHIP_MATRIX, type AgentAuthorityScope } from "./nexus.types";

// ═══════════════════════════════════════════════════════════════════════════════
// GUARD #1: AUTHORITY CHECK
// ═══════════════════════════════════════════════════════════════════════════════

/**
 * Validate that the proposing agent has authority for this delta type.
 *
 * Maps each proposal type to the asset it touches, then checks
 * the ownership matrix to verify the agent has write access.
 */
export function validateAuthority(
  proposal: DeltaProposal,
  agent: AgentRuntimeRecord
): { valid: boolean; reason?: string } {
  // Determine which asset this proposal touches
  const asset = mapProposalToAsset(proposal.type);
  if (!asset) {
    return { valid: false, reason: `Unknown proposal type: ${proposal.type}` };
  }

  // Find the ownership entry
  const entry = OWNERSHIP_MATRIX.find((e) => e.asset === asset);
  if (!entry) {
    return { valid: false, reason: `No ownership entry for asset: ${asset}` };
  }

  // Map agent to runtime asset owner role
  const agentRole = mapAgentToOwnerRole(agent.agentId);

  // Check write access
  if (!entry.writeAccess.includes(agentRole)) {
    return {
      valid: false,
      reason: `Agent "${agent.agentId}" (role: ${agentRole}) has no write access to "${asset}". Owner: ${entry.owner}. Write access: ${entry.writeAccess.join(", ")}`,
    };
  }

  return { valid: true };
}

/** Map a proposal type to the runtime asset it modifies. */
function mapProposalToAsset(type: DeltaProposalType): string | null {
  switch (type) {
    case "PLANET_ACTIVATE":
    case "PLANET_COMPLETE":
    case "PROGRESSION_INIT":
      return "global_runtime_state";
    case "MEMORY_UPDATE":
      return "user_cognitive_profile";
    case "CONTEXT_SYNC":
    case "HINT_GENERATE":
    case "HINT_CLEAR":
      return "session_context";
    case "AGENT_STATE_CHANGE":
      return "agent_registry";
    default:
      return null;
  }
}

/**
 * Map agent IDs to runtime asset owner roles.
 * This is the authoritative mapping — extend when new agents are added.
 */
function mapAgentToOwnerRole(agentId: string): RuntimeAssetOwner {
  // The Nexus itself maps to "nexus"
  if (agentId === "nexus" || agentId === "__nexus_kernel__") return "nexus";

  // Memory Keeper (future: may be a separate agent)
  if (agentId === "memory_keeper" || agentId === "__memory_keeper__") return "memory_keeper";

  // Universe agents (planets) map to "runtime_layer"
  // They can read/write session context but NOT global state or registry
  return "runtime_layer";
}

// ═══════════════════════════════════════════════════════════════════════════════
// GUARD #2: SCOPE CHECK
// ═══════════════════════════════════════════════════════════════════════════════

/**
 * Validate that the proposal falls within the agent's authority scope.
 * Checks planet access, write permissions, and rate limits.
 */
export function validateScope(
  proposal: DeltaProposal,
  agent: AgentRuntimeRecord,
  state: NexusCanonicalState
): { valid: boolean; reason?: string } {
  const scope = agent.scope;

  // Check: agent must be in "active" lifecycle state
  if (agent.lifecycle !== "active") {
    return {
      valid: false,
      reason: `Agent "${agent.agentId}" is ${agent.lifecycle}, not active`,
    };
  }

  // Check: rate limit (max proposals per second)
  const msSinceLastProposal = proposal.timestamp - agent.lastProposalAt;
  const minIntervalMs = 1000 / scope.maxWriteRate;
  if (agent.lastProposalAt > 0 && msSinceLastProposal < minIntervalMs) {
    return {
      valid: false,
      reason: `Rate limit exceeded. Min interval: ${minIntervalMs}ms, actual: ${msSinceLastProposal}ms`,
    };
  }

  // Check: planet access for planet-specific proposals
  if (proposal.type === "PLANET_ACTIVATE" || proposal.type === "PLANET_COMPLETE") {
    const planetId = "payload" in proposal
      ? (proposal as DeltaProposal<"PLANET_ACTIVATE">).payload.planetId
      : (proposal as DeltaProposal<"PLANET_COMPLETE">).payload.planetId;

    if (scope.planetAccess.length > 0 && !scope.planetAccess.includes(planetId)) {
      return {
        valid: false,
        reason: `Agent "${agent.agentId}" has no planet access to "${planetId}"`,
      };
    }
  }

  // Check: memory write permission
  if (proposal.type === "MEMORY_UPDATE" && !scope.canWriteMemory) {
    return {
      valid: false,
      reason: `Agent "${agent.agentId}" does not have memory write permission`,
    };
  }

  return { valid: true };
}

// ═══════════════════════════════════════════════════════════════════════════════
// GUARD #3: STATE VALIDITY
// ═══════════════════════════════════════════════════════════════════════════════

/**
 * Validate that the proposed state transition is legal.
 *
 * Checks:
 *   - Planet state machine: can't activate an already-active planet
 *   - Cooldown: minimum time between progression changes
 *   - Prerequisites: all required planets must be completed
 */
export function validateStateTransition(
  proposal: DeltaProposal,
  agent: AgentRuntimeRecord,
  state: NexusCanonicalState
): { valid: boolean; reason?: string } {
  switch (proposal.type) {
    case "PLANET_ACTIVATE":
      return validatePlanetActivate(proposal as DeltaProposal<"PLANET_ACTIVATE">, state);
    case "PLANET_COMPLETE":
      return validatePlanetComplete(proposal as DeltaProposal<"PLANET_COMPLETE">, state);
    case "AGENT_STATE_CHANGE":
      return validateAgentStateChange(proposal as DeltaProposal<"AGENT_STATE_CHANGE">, state);
    case "HINT_GENERATE":
      return validateHintGenerate(proposal as DeltaProposal<"HINT_GENERATE">, state);
    default:
      // PROGRESSION_INIT, MEMORY_UPDATE, CONTEXT_SYNC, HINT_CLEAR are always valid
      // (authority + scope guards handle them)
      return { valid: true };
  }
}

function validatePlanetActivate(
  proposal: DeltaProposal<"PLANET_ACTIVATE">,
  state: NexusCanonicalState
): { valid: boolean; reason?: string } {
  const { planetId } = proposal.payload;
  const progression = state.playerProgression;

  if (!progression) {
    return { valid: false, reason: "No player progression loaded" };
  }

  // Can't activate if already active
  if (progression.activePlanet === planetId) {
    return { valid: false, reason: `Planet "${planetId}" is already active` };
  }

  // Can't activate if already completed
  if (progression.completed.includes(planetId)) {
    return { valid: false, reason: `Planet "${planetId}" is already completed` };
  }

  // Must be available
  if (!progression.available.includes(planetId)) {
    return { valid: false, reason: `Planet "${planetId}" is not available` };
  }

  return { valid: true };
}

function validatePlanetComplete(
  proposal: DeltaProposal<"PLANET_COMPLETE">,
  state: NexusCanonicalState
): { valid: boolean; reason?: string } {
  const { planetId } = proposal.payload;
  const progression = state.playerProgression;

  if (!progression) {
    return { valid: false, reason: "No player progression loaded" };
  }

  // Must be active to complete
  if (progression.activePlanet !== planetId) {
    return { valid: false, reason: `Planet "${planetId}" is not active (current: ${progression.activePlanet})` };
  }

  return { valid: true };
}

export function validateHintGenerate(
  proposal: DeltaProposal<"HINT_GENERATE">,
  state: NexusCanonicalState
): { valid: boolean; reason?: string } {
  const { planetId } = proposal.payload;
  const progression = state.playerProgression;

  if (!progression) {
    return { valid: false, reason: "No player progression loaded" };
  }

  // Planet must be active or available to receive hints
  if (progression.activePlanet !== planetId && !progression.available.includes(planetId)) {
    return { valid: false, reason: `Planet "${planetId}" is not active or available` };
  }

  return { valid: true };
}

function validateAgentStateChange(
  proposal: DeltaProposal<"AGENT_STATE_CHANGE">,
  state: NexusCanonicalState
): { valid: boolean; reason?: string } {
  const { agentId, toState } = proposal.payload;
  const agentRecord = state.agentRecords[agentId];

  if (!agentRecord) {
    return { valid: false, reason: `Agent "${agentId}" not found in registry` };
  }

  const currentState = agentRecord.lifecycle;

  // Valid transitions (one-directional state machine)
  const validTransitions: Record<AgentLifecycleState, AgentLifecycleState[]> = {
    unregistered: ["initializing"],
    initializing: ["active", "terminated"], // Can terminate during init
    active: ["suspended", "terminated"],
    suspended: ["active", "terminated"], // Can resume or terminate
    terminated: [], // Terminal state — no transitions out
  };

  const allowed = validTransitions[currentState] || [];
  if (!allowed.includes(toState)) {
    return {
      valid: false,
      reason: `Invalid state transition for "${agentId}": ${currentState} → ${toState}. Allowed: ${allowed.join(", ") || "none"}`,
    };
  }

  return { valid: true };
}

// ═══════════════════════════════════════════════════════════════════════════════
// GUARD #4: CONFLICT DETECTION
// ═══════════════════════════════════════════════════════════════════════════════

/**
 * Detect conflicts between two pending proposals.
 *
 * Scenarios:
 *   - Concurrent write: two agents propose changes to the same asset
 *   - State stale: a proposal references state that has since changed
 *   - Authority violation: an agent tries to write outside its scope
 */
export function detectConflict(
  proposalA: DeltaProposal,
  proposalB: DeltaProposal,
  state: NexusCanonicalState
): ConflictReport | null {
  // Both proposals target the same asset → concurrent write conflict
  const assetA = mapProposalToAsset(proposalA.type);
  const assetB = mapProposalToAsset(proposalB.type);

  if (assetA && assetB && assetA === assetB) {
    // If they target the same planet, it's a direct conflict
    if (proposalA.type === proposalB.type) {
      const conflict = resolveConcurrentWriteConflict(
        proposalA,
        proposalB,
        assetA,
        state
      );
      if (conflict) return conflict;
    }

    // Different types targeting the same asset → potential conflict
    // e.g., PLANET_ACTIVATE and PLANET_COMPLETE on the same asset
    const conflict: ConflictReport = {
      agentA: proposalA.agentId,
      agentB: proposalB.agentId,
      type: "concurrent_write",
      description: `Both agents propose changes to "${assetA}": ${proposalA.type} vs ${proposalB.type}`,
      blockedProposal: proposalB.proposalId, // B is blocked, A proceeds
      proceededProposal: proposalA.proposalId,
      detectedAt: Date.now(),
    };
    return conflict;
  }

  return null; // No conflict
}

/**
 * Resolve concurrent write conflicts.
 *
 * Strategy: timestamp-based — earlier proposal wins.
 * If timestamps are equal, the proposal with the lexicographically smaller
 * proposalId wins (deterministic tiebreaker).
 */
function resolveConcurrentWriteConflict(
  a: DeltaProposal,
  b: DeltaProposal,
  asset: string,
  state: NexusCanonicalState
): ConflictReport | null {
  // Same exact operation on same asset → real conflict
  if (a.type === b.type) {
    // Timestamp-based resolution
    const earlier = a.timestamp <= b.timestamp ? a : b;
    const later = earlier === a ? b : a;

    return {
      agentA: earlier.agentId,
      agentB: later.agentId,
      type: "concurrent_write",
      description: `Concurrent ${a.type} on "${asset}". Earlier timestamp wins.`,
      blockedProposal: later.proposalId,
      proceededProposal: earlier.proposalId,
      detectedAt: Date.now(),
    };
  }

  return null;
}

// ═══════════════════════════════════════════════════════════════════════════════
// GUARD #5: RUNTIME HEALTH CHECK
// ═══════════════════════════════════════════════════════════════════════════════

/**
 * Evaluate overall runtime health based on agent states, error counts,
 * and synchronization status.
 */
export function evaluateRuntimeHealth(state: NexusCanonicalState): {
  healthy: boolean;
  issues: string[];
} {
  const issues: string[] = [];

  // Check: any agent in terminal state with errors
  for (const record of Object.values(state.agentRecords)) {
    if (record.lifecycle === "terminated") {
      issues.push(`Agent "${record.agentId}" is terminated`);
    }
    if (record.consecutiveErrors >= 3) {
      issues.push(`Agent "${record.agentId}" has ${record.consecutiveErrors} consecutive errors`);
    }
  }

  // Check: no active agents
  const activeCount = Object.values(state.agentRecords).filter(
    (r) => r.lifecycle === "active"
  ).length;
  if (activeCount === 0 && Object.keys(state.agentRecords).length > 0) {
    issues.push("No active agents — runtime is idle");
  }

  // Check: stale sync (no sync in over 60 seconds while agents are active)
  if (activeCount > 0 && Date.now() - state.lastSyncAt > 60_000) {
    issues.push(`Last sync was ${Math.round((Date.now() - state.lastSyncAt) / 1000)}s ago`);
  }

  // Check: high rejection rate
  const totalProposals = state.health.proposalsProcessed + state.health.proposalsRejected;
  if (totalProposals > 10) {
    const rejectionRate = state.health.proposalsRejected / totalProposals;
    if (rejectionRate > 0.5) {
      issues.push(`High proposal rejection rate: ${Math.round(rejectionRate * 100)}%`);
    }
  }

  return {
    healthy: issues.length === 0,
    issues,
  };
}

// ═══════════════════════════════════════════════════════════════════════════════
// COMPOSITE GUARD — RUN ALL CHECKS
// ═══════════════════════════════════════════════════════════════════════════════

/**
 * Run all guards against a delta proposal.
 *
 * This is the single entry point for proposal validation.
 * Returns the first failing guard or success.
 *
 * Order matters:
 *   1. Authority (ownership matrix) — always first
 *   2. Scope (permissions + rate limits)
 *   3. State validity (legal transitions)
 *   4. Conflict detection (run externally against pending proposals)
 */
export function validateProposal(
  proposal: DeltaProposal,
  agent: AgentRuntimeRecord,
  state: NexusCanonicalState
): { valid: boolean; reason?: string } {
  // Guard 1: Authority
  const authority = validateAuthority(proposal, agent);
  if (!authority.valid) return authority;

  // Guard 2: Scope
  const scope = validateScope(proposal, agent, state);
  if (!scope.valid) return scope;

  // Guard 3: State validity
  const stateValidity = validateStateTransition(proposal, agent, state);
  if (!stateValidity.valid) return stateValidity;

  return { valid: true };
}

/**
 * relationship-state.ts — Motor de Evolução de Relacionamento Conversacional.
 *
 * Modela a progressão natural do relacionamento entre usuário e agente
 * ao longo do tempo, baseada em sinais objetivos (não emocionais):
 *   - Volume de interações
 *   - Diversidade de memórias
 *   - Profundidade cognitiva (via identity-profiler)
 *   - Consistência de engajamento
 *
 * ESTADOS DE RELACIONAMENTO (5 níveis progressivos):
 *
 *   1. NEWCOMER       — Primeiras interações
 *   2. CURIOUS        — Exploração inicial consistente
 *   3. ENGAGED        — Aprendizado ativo e regular
 *   4. STRATEGIC      — Pensamento crítico e conexões profundas
 *   5. COLLABORATIVE  — Parceria intelectual de longo prazo
 *
 * PRINCÍPIOS DE SEGURANÇA:
 *   - NUNCA simular romance ou afeto romântico
 *   - NUNCA criar senso de exclusividade ("você é especial")
 *   - NUNCA induzir dependência emocional
 *   - SEMPRE basear transições em dados objetivos
 *   - SEMPRE preservar autonomia do usuário
 */

import { getDb } from "@/lib/db";
import { agentMemories } from "@/lib/db/schema";
import { eq, sql } from "drizzle-orm";
import type { IdentityTraits } from "./identity-profiler";

// ─── Estados de Relacionamento ────────────────────────────────────────────────

export type RelationshipState =
  | "newcomer"
  | "curious"
  | "engaged"
  | "strategic"
  | "collaborative";

export const RELATIONSHIP_STATES: RelationshipState[] = [
  "newcomer",
  "curious",
  "engaged",
  "strategic",
  "collaborative",
];

export interface RelationshipProfile {
  state: RelationshipState;
  /** 0..1 — nível de progressão dentro do estado atual */
  progressionWithinState: number;
  /** Total estimado de interações */
  totalInteractions: number;
  /** Dias desde a primeira interação */
  daysSinceFirstInteraction: number;
  /** Quantos agentes diferentes o usuário já interagiu */
  uniqueAgentsCount: number;
  /** Data da última atualização */
  lastUpdated: string;
}

// ─── Thresholds de Transição ──────────────────────────────────────────────────

interface StateThresholds {
  minInteractions: number;
  minUniqueAgents: number;
  minDaysActive: number;
  minConsolidatedMemories: number;
  /** Traços de identidade desejáveis para este estado */
  expectedTraits?: Partial<IdentityTraits>;
}

const THRESHOLDS: Record<RelationshipState, StateThresholds> = {
  newcomer: {
    minInteractions: 0,
    minUniqueAgents: 0,
    minDaysActive: 0,
    minConsolidatedMemories: 0,
  },
  curious: {
    minInteractions: 8,
    minUniqueAgents: 2,
    minDaysActive: 1,
    minConsolidatedMemories: 0,
  },
  engaged: {
    minInteractions: 25,
    minUniqueAgents: 3,
    minDaysActive: 3,
    minConsolidatedMemories: 2,
    expectedTraits: { curiosityLevel: 0.3 },
  },
  strategic: {
    minInteractions: 60,
    minUniqueAgents: 5,
    minDaysActive: 7,
    minConsolidatedMemories: 5,
    expectedTraits: { analyticalDepth: 0.4, curiosityLevel: 0.5 },
  },
  collaborative: {
    minInteractions: 150,
    minUniqueAgents: 7,
    minDaysActive: 21,
    minConsolidatedMemories: 12,
    expectedTraits: {
      analyticalDepth: 0.5,
      curiosityLevel: 0.6,
      narrativeEngagement: 0.5,
    },
  },
};

// ─── Análise de Relacionamento ────────────────────────────────────────────────

/**
 * Calcula o estado de relacionamento atual do usuário.
 *
 * Baseado em:
 *   - Contagem de interações (memórias totais)
 *   - Diversidade de agentes (unique agentIds)
 *   - Dias ativos (desde a primeira memória)
 *   - Memórias consolidadas (aprendizado consolidado)
 *   - Traços de identidade (se disponíveis)
 */
export async function analyzeRelationship(
  userId: number,
  identity?: IdentityTraits | null,
): Promise<RelationshipProfile> {
  const db = getDb();

  try {
    // Contagem de interações (memórias totais)
    const countResult = await db
      .select({ count: sql<number>`count(*)` })
      .from(agentMemories)
      .where(eq(agentMemories.userId, userId));

    const totalInteractions = countResult[0]?.count ?? 0;

    // Primeira interação (memória mais antiga)
    const firstResult = await db
      .select({ firstDate: agentMemories.createdAt })
      .from(agentMemories)
      .where(eq(agentMemories.userId, userId))
      .orderBy(agentMemories.createdAt)
      .limit(1);

    const firstDate = firstResult[0]?.firstDate;
    const daysSinceFirst = firstDate
      ? Math.max(
          1,
          Math.round(
            (Date.now() - new Date(firstDate).getTime()) /
              (86400 * 1000),
          ),
        )
      : 0;

    // Agentes únicos
    const agentsResult = await db
      .select({ agentId: agentMemories.agentId })
      .from(agentMemories)
      .where(eq(agentMemories.userId, userId));

    const uniqueAgents = new Set(
      agentsResult.map((r) => r.agentId),
    ).size;

    // Memórias consolidadas
    const consolidatedCount = agentsResult.filter((r) => {
      // Verifica se a memória tem tag "consolidated" (via JSON_CONTAINS)
      return false; // Placeholder — a query completa exigiria JSON_CONTAINS
    }).length;

    // Simplificação: usa totalInteractions / 10 como proxy para consolidadas
    const estimatedConsolidated = Math.floor(totalInteractions / 10);

    // Determina o estado
    let state: RelationshipState = "newcomer";
    let progressionWithinState = 0;

    for (let i = RELATIONSHIP_STATES.length - 1; i >= 0; i--) {
      const candidate = RELATIONSHIP_STATES[i];
      const t = THRESHOLDS[candidate];

      const meetsInteraction = totalInteractions >= t.minInteractions;
      const meetsAgents = uniqueAgents >= t.minUniqueAgents;
      const meetsDays = daysSinceFirst >= t.minDaysActive;
      const meetsConsolidated =
        estimatedConsolidated >= t.minConsolidatedMemories;

      // Traços são opcionais — se não disponíveis, ignora
      let meetsTraits = true;
      if (t.expectedTraits && identity) {
        for (const [trait, minValue] of Object.entries(
          t.expectedTraits,
        )) {
          const actual =
            identity[trait as keyof IdentityTraits] ?? 0;
          if ((actual as number) < (minValue as number)) {
            meetsTraits = false;
            break;
          }
        }
      }

      if (
        meetsInteraction &&
        meetsAgents &&
        meetsDays &&
        meetsConsolidated &&
        meetsTraits
      ) {
        state = candidate;

        // Calcula progressão dentro do estado (0..1)
        const nextIdx = i + 1;
        if (nextIdx < RELATIONSHIP_STATES.length) {
          const next = THRESHOLDS[RELATIONSHIP_STATES[nextIdx]];
          const progressByInteraction =
            next.minInteractions > t.minInteractions
              ? (totalInteractions - t.minInteractions) /
                (next.minInteractions - t.minInteractions)
              : 0;
          const progressByAgents =
            next.minUniqueAgents > t.minUniqueAgents
              ? (uniqueAgents - t.minUniqueAgents) /
                (next.minUniqueAgents - t.minUniqueAgents)
              : 0;
          const progressByDays =
            next.minDaysActive > t.minDaysActive
              ? (daysSinceFirst - t.minDaysActive) /
                (next.minDaysActive - t.minDaysActive)
              : 0;

          progressionWithinState = Math.min(
            1,
            Math.max(
              0,
              (progressByInteraction +
                progressByAgents +
                progressByDays) /
                3,
            ),
          );
        } else {
          progressionWithinState = 1; // Já no estado máximo
        }
        break;
      }
    }

    return {
      state,
      progressionWithinState: Math.round(progressionWithinState * 100) / 100,
      totalInteractions,
      daysSinceFirstInteraction: daysSinceFirst,
      uniqueAgentsCount: uniqueAgents,
      lastUpdated: new Date().toISOString(),
    };
  } catch {
    // Fallback seguro
    return {
      state: "newcomer",
      progressionWithinState: 0,
      totalInteractions: 0,
      daysSinceFirstInteraction: 0,
      uniqueAgentsCount: 0,
      lastUpdated: new Date().toISOString(),
    };
  }
}

