/**
 * ─── AUDIO MANAGER — Singleton Runtime Audio System ───────────────────────────
 *
 * Rules:
 *   - Singleton architecture — one AudioContext for the entire app
 *   - Lazy initialization — AudioContext created on first user interaction
 *   - NO autoplay — audio only reacts through events
 *   - NO audio logic inside React components
 *   - Audio signatures map to procedural sound generation via Tone.js
 *   - Each planet has a distinct sonic identity
 */

import * as Tone from "tone";
import { planetRegistry, type PlanetId, type AudioSignature } from "./planet-registry";
import { universeBus } from "./event-bus";

// ─── TYPES ────────────────────────────────────────────────────────────────────

type AudioState = "idle" | "active" | "suspended";

interface ActiveSound {
  signature: AudioSignature;
  dispose: () => void;
  volume: Tone.Volume;
}

// ─── CONSTANTS ────────────────────────────────────────────────────────────────

/** Master output gain (ambient — barely audible) */
const MASTER_GAIN = 0.08;

/** Crossfade duration in seconds */
const CROSSFADE_S = 2;

// ─── SINGLETON ────────────────────────────────────────────────────────────────

class AudioManager {
  private state: AudioState = "idle";
  private initialized = false;
  private masterVolume: Tone.Volume | null = null;
  private reverb: Tone.Reverb | null = null;
  private activeSounds = new Map<PlanetId, ActiveSound>();

  /**
   * Initialize the audio system.
   * MUST be called from a user gesture handler (click, keypress).
   */
  async init(): Promise<void> {
    if (this.initialized) return;

    try {
      await Tone.start();
      this.masterVolume = new Tone.Volume(MASTER_GAIN).toDestination();

      // Shared reverb for spatial depth
      this.reverb = new Tone.Reverb({ decay: 3, wet: 0.15 });
      this.reverb.connect(this.masterVolume);

      this.state = "active";
      this.initialized = true;
      this.subscribeToEvents();
    } catch (err) {
      console.warn("[AudioManager] Init failed:", err);
    }
  }

  /** Resume a suspended context. */
  async resume(): Promise<void> {
    if (this.state === "suspended" && Tone.getContext().state === "suspended") {
      await Tone.getContext().resume();
      this.state = "active";
    }
  }

  /** Suspend audio (save resources). */
  async suspend(): Promise<void> {
    if (this.state === "active") {
      // Access underlying AudioContext directly — Tone.BaseContext may not expose suspend
      const ctx = (Tone.getContext() as any).rawContext?.context ?? Tone.getContext();
      if (typeof (ctx as any).suspend === "function") {
        await (ctx as any).suspend();
      }
      this.state = "suspended";
    }
  }

  /** Set master volume (0–1). */
  setVolume(value: number): void {
    if (this.masterVolume) {
      this.masterVolume.volume.rampTo(
        Tone.gainToDb(Math.max(0, Math.min(1, value))),
        0.5
      );
    }
  }

  getState(): AudioState {
    return this.state;
  }

  isAvailable(): boolean {
    return this.initialized;
  }

  /**
   * Play a procedural audio signature for a planet.
   * Crossfades if another planet is already playing.
   */
  playSignature(planetId: PlanetId): void {
    if (!this.initialized || !this.masterVolume) return;

    const planet = planetRegistry[planetId];
    const signature = planet.audioSignature;

    // void is silence — stop anything playing and return
    if (signature === "void") {
      this.fadeOutActive();
      return;
    }

    // Crossfade if another planet is active
    this.fadeOutActive();

    const sound = this.createSignature(planetId, signature);
    this.activeSounds.set(planetId, sound);

    // Fade in
    sound.volume.volume.value = -60;
    sound.volume.volume.rampTo(-6, CROSSFADE_S);
  }

  /** Stop audio for a specific planet with fade out. */
  stopSignature(planetId: PlanetId): void {
    const sound = this.activeSounds.get(planetId);
    if (sound) {
      sound.volume.volume.rampTo(-60, 1);
      setTimeout(() => {
        sound.dispose();
        this.activeSounds.delete(planetId);
      }, 1100);
    }
  }

  /** Stop all audio immediately. */
  stopAll(): void {
    for (const [, sound] of this.activeSounds) {
      sound.dispose();
    }
    this.activeSounds.clear();
  }

  // ── CROSSFADE ───────────────────────────────────────────────────────────

  private fadeOutActive(): void {
    for (const [id, sound] of this.activeSounds) {
      sound.volume.volume.rampTo(-60, CROSSFADE_S);
      setTimeout(() => {
        sound.dispose();
        this.activeSounds.delete(id);
      }, CROSSFADE_S * 1000 + 100);
    }
  }

  // ═══════════════════════════════════════════════════════════════════════════
  // SIGNATURE GENERATORS
  // ═══════════════════════════════════════════════════════════════════════════

  private createSignature(
    planetId: PlanetId,
    signature: AudioSignature
  ): ActiveSound {
    const volume = new Tone.Volume(-6);
    volume.connect(this.masterVolume!);

    // Optional: route through reverb for spatial depth
    const reverbSend = new Tone.Volume(-12);
    reverbSend.connect(this.reverb!);
    volume.connect(reverbSend);

    let dispose: () => void;

    switch (signature) {
      case "low-hum":
        dispose = this.buildLowHum(volume);
        break;
      case "pulse":
        dispose = this.buildPulse(volume);
        break;
      case "harmonic":
        dispose = this.buildHarmonic(volume);
        break;
      case "dissonant":
        dispose = this.buildDissonant(volume);
        break;
      case "bass-drone":
        dispose = this.buildBassDrone(volume);
        break;
      case "crystal":
        dispose = this.buildCrystal(volume);
        break;
      case "static":
        dispose = this.buildStatic(volume);
        break;
      case "choir":
        dispose = this.buildChoir(volume);
        break;
      case "rhythmic":
        dispose = this.buildRhythmic(volume);
        break;
      case "digital":
        dispose = this.buildDigital(volume);
        break;
      case "organic":
        dispose = this.buildOrganic(volume);
        break;
      case "void":
        dispose = () => {}; // silence — nothing to dispose
        break;
      default:
        dispose = () => {};
    }

    return { signature, dispose, volume };
  }

  // ── NEXUS: low-hum — deep grounding sine ────────────────────────────────
  private buildLowHum(output: Tone.Volume): () => void {
    const osc = new Tone.Oscillator({
      type: "sine",
      frequency: 55,
      volume: -12,
    }).connect(output);
    osc.start();

    // Subtle LFO on frequency for organic movement
    const lfo = new Tone.LFO({
      frequency: 0.1,
      min: 54.5,
      max: 55.5,
    }).connect(osc.frequency);
    lfo.start();

    return () => {
      osc.stop();
      osc.dispose();
      lfo.stop();
      lfo.dispose();
    };
  }

  // ── VOLT: pulse — rhythmic low-frequency electric ───────────────────────
  private buildPulse(output: Tone.Volume): () => void {
    const osc = new Tone.Oscillator({
      type: "square",
      frequency: 40,
      volume: -20,
    }).connect(output);

    // Rhythmic amplitude modulation
    const lfo = new Tone.LFO({
      frequency: 1.5,
      min: -30,
      max: -8,
    }).connect(osc.volume as any);
    lfo.start();

    osc.start();

    return () => {
      osc.stop();
      osc.dispose();
      lfo.stop();
      lfo.dispose();
    };
  }

  // ── LYRA: harmonic — layered sine waves (fundamental + octave + fifth) ──
  private buildHarmonic(output: Tone.Volume): () => void {
    const fundamentals = [130.81, 261.63, 392.0]; // C3, C4, G4
    const oscillators: Tone.Oscillator[] = [];
    const lfos: Tone.LFO[] = [];

    for (const freq of fundamentals) {
      const osc = new Tone.Oscillator({
        type: "sine",
        frequency: freq,
        volume: -18,
      }).connect(output);
      osc.start();
      oscillators.push(osc);

      // Gentle pitch drift for choral warmth
      const lfo = new Tone.LFO({
        frequency: 0.08 + Math.random() * 0.04,
        min: freq - 0.5,
        max: freq + 0.5,
      }).connect(osc.frequency);
      lfo.start();
      lfos.push(lfo);
    }

    return () => {
      for (const osc of oscillators) {
        osc.stop();
        osc.dispose();
      }
      for (const lfo of lfos) {
        lfo.stop();
        lfo.dispose();
      }
    };
  }

  // ── KAOS: dissonant — detuned sawtooths creating tension ────────────────
  private buildDissonant(output: Tone.Volume): () => void {
    const osc1 = new Tone.Oscillator({
      type: "sawtooth",
      frequency: 110,
      volume: -22,
    }).connect(output);

    const osc2 = new Tone.Oscillator({
      type: "sawtooth",
      frequency: 113, // +3Hz detune = beating/tension
      volume: -22,
    }).connect(output);

    // Slow filter sweep for evolving texture
    const filter = new Tone.Filter({
      type: "lowpass",
      frequency: 400,
      rolloff: -12,
    });
    osc1.disconnect(output);
    osc2.disconnect(output);
    osc1.connect(filter);
    osc2.connect(filter);
    filter.connect(output);

    const filterLfo = new Tone.LFO({
      frequency: 0.05,
      min: 200,
      max: 800,
    }).connect(filter.frequency);
    filterLfo.start();

    osc1.start();
    osc2.start();

    return () => {
      osc1.stop();
      osc1.dispose();
      osc2.stop();
      osc2.dispose();
      filterLfo.stop();
      filterLfo.dispose();
      filter.dispose();
    };
  }

  // ── AXIOM: bass-drone — sub-bass foundation with filtered noise ─────────
  private buildBassDrone(output: Tone.Volume): () => void {
    // Sub-bass sine
    const osc = new Tone.Oscillator({
      type: "sine",
      frequency: 32.7, // C1
      volume: -14,
    }).connect(output);
    osc.start();

    // Filtered noise for texture
    const noise = new Tone.Noise("pink").start();
    const noiseFilter = new Tone.Filter({
      type: "lowpass",
      frequency: 150,
      rolloff: -24,
    });
    const noiseVol = new Tone.Volume(-30);
    noise.connect(noiseFilter);
    noiseFilter.connect(noiseVol);
    noiseVol.connect(output);

    return () => {
      osc.stop();
      osc.dispose();
      noise.stop();
      noise.dispose();
      noiseFilter.dispose();
      noiseVol.dispose();
    };
  }

  // ── PRISM: crystal — FM bell-like tones with shimmer ────────────────────
  private buildCrystal(output: Tone.Volume): () => void {
    const fm = new Tone.FMSynth({
      harmonicity: 3.01,
      modulationIndex: 5,
      oscillator: { type: "sine" },
      modulation: { type: "sine" },
      envelope: {
        attack: 0.01,
        decay: 0.3,
        sustain: 0,
        release: 1.2,
      },
      volume: -18,
    }).connect(output);

    // Trigger bell-like tones on a loop
    const notes = ["C5", "E5", "G5", "B5", "C6", "B5", "G5", "E5"];
    let index = 0;

    const loop = new Tone.Loop((time) => {
      fm.triggerAttackRelease(notes[index % notes.length], "8n", time);
      index++;
    }, "4n");

    // Random octave jumps for unpredictability
    const interval = setInterval(() => {
      index += Math.floor(Math.random() * 3);
    }, 4000);

    loop.start(0);

    return () => {
      loop.stop();
      loop.dispose();
      fm.dispose();
      clearInterval(interval);
    };
  }

  // ── JANUS: static — filtered noise, liminal space ───────────────────────
  private buildStatic(output: Tone.Volume): () => void {
    const noise = new Tone.Noise("pink").start();

    const bandpass = new Tone.Filter({
      type: "bandpass",
      frequency: 1000,
      Q: 2,
    });

    const noiseVol = new Tone.Volume(-24);
    noise.connect(bandpass);
    bandpass.connect(noiseVol);
    noiseVol.connect(output);

    // Slow bandpass sweep
    const sweepLfo = new Tone.LFO({
      frequency: 0.03,
      min: 400,
      max: 2000,
    }).connect(bandpass.frequency);
    sweepLfo.start();

    // Occasional crackle via gain modulation
    const crackleLfo = new Tone.LFO({
      frequency: 0.2,
      min: -35,
      max: -20,
    }).connect(noiseVol.volume as any);
    crackleLfo.start();

    return () => {
      noise.stop();
      noise.dispose();
      bandpass.dispose();
      noiseVol.dispose();
      sweepLfo.stop();
      sweepLfo.dispose();
      crackleLfo.stop();
      crackleLfo.dispose();
    };
  }

  // ── ETHOS: choir — layered voices with slow drift ───────────────────────
  private buildChoir(output: Tone.Volume): () => void {
    const voices = [
      { freq: 196, detune: 0 },    // G3
      { freq: 246.94, detune: 2 },  // B3
      { freq: 293.66, detune: -1 }, // D4
      { freq: 392, detune: 1 },     // G4
    ];

    const oscillators: Tone.Oscillator[] = [];
    const lfos: Tone.LFO[] = [];

    for (const voice of voices) {
      const osc = new Tone.Oscillator({
        type: "sine",
        frequency: voice.freq,
        volume: -22,
        detune: voice.detune,
      }).connect(output);
      osc.start();
      oscillators.push(osc);

      // Slow amplitude drift for breathing effect
      const ampLfo = new Tone.LFO({
        frequency: 0.06 + Math.random() * 0.04,
        min: -28,
        max: -18,
      }).connect(osc.volume as any);
      ampLfo.start();
      lfos.push(ampLfo);
    }

    return () => {
      for (const osc of oscillators) {
        osc.stop();
        osc.dispose();
      }
      for (const lfo of lfos) {
        lfo.stop();
        lfo.dispose();
      }
    };
  }

  // ── AURORA: rhythmic — percussive pattern with evolving texture ──────────
  private buildRhythmic(output: Tone.Volume): () => void {
    const kick = new Tone.MembraneSynth({
      pitchDecay: 0.05,
      octaves: 4,
      volume: -18,
    }).connect(output);

    const hat = new Tone.NoiseSynth({
      noise: { type: "white" },
      envelope: { attack: 0.001, decay: 0.05, sustain: 0, release: 0 },
      volume: -24,
    }).connect(output);

    // Kick pattern: 1 . 3 . | 1 . 3 4
    const kickLoop = new Tone.Loop((time) => {
      kick.triggerAttackRelease("C2", "8n", time);
    }, "2n").start(0);

    // Hat pattern: 1 & 2 & 3 & 4 &
    const hatLoop = new Tone.Loop((time) => {
      hat.triggerAttackRelease("8n", time);
    }, "8n").start("4n");

    // Reverb send for depth
    const verb = new Tone.Reverb({ decay: 2, wet: 0.3 });
    verb.connect(output);
    kick.connect(verb);
    hat.connect(verb);

    return () => {
      kickLoop.stop();
      kickLoop.dispose();
      hatLoop.stop();
      hatLoop.dispose();
      kick.dispose();
      hat.dispose();
      verb.dispose();
    };
  }

  // ── CIPHER: digital — arpeggiated square pattern ────────────────────────
  private buildDigital(output: Tone.Volume): () => void {
    const synth = new Tone.Synth({
      oscillator: { type: "square" },
      envelope: {
        attack: 0.005,
        decay: 0.1,
        sustain: 0.1,
        release: 0.05,
      },
      volume: -22,
    }).connect(output);

    // Minor pentatonic arpeggio
    const notes = ["C4", "Eb4", "F4", "G4", "Bb4", "G4", "F4", "Eb4"];
    let index = 0;

    const loop = new Tone.Loop((time) => {
      synth.triggerAttackRelease(notes[index % notes.length], "16n", time);
      index++;
    }, "8n");

    // High-pass filter for digital crispness
    const hpFilter = new Tone.Filter({
      type: "highpass",
      frequency: 300,
      rolloff: -12,
    });
    synth.disconnect(output);
    synth.connect(hpFilter);
    hpFilter.connect(output);

    loop.start(0);

    return () => {
      loop.stop();
      loop.dispose();
      synth.dispose();
      hpFilter.dispose();
    };
  }

  // ── TERRA: organic — filtered noise with natural envelope ────────────────
  private buildOrganic(output: Tone.Volume): () => void {
    const noise = new Tone.Noise("brown").start();

    const lowpass = new Tone.Filter({
      type: "lowpass",
      frequency: 250,
      rolloff: -12,
    });

    const noiseVol = new Tone.Volume(-26);
    noise.connect(lowpass);
    lowpass.connect(noiseVol);
    noiseVol.connect(output);

    // Slow organic filter movement (wind/earth feel)
    const lfo1 = new Tone.LFO({
      frequency: 0.04,
      min: 120,
      max: 400,
    }).connect(lowpass.frequency);
    lfo1.start();

    // Secondary modulation for complexity
    const lfo2 = new Tone.LFO({
      frequency: 0.11,
      min: 180,
      max: 320,
    }).connect(lowpass.frequency);
    lfo2.start();

    // Volume swell
    const swellLfo = new Tone.LFO({
      frequency: 0.06,
      min: -35,
      max: -22,
    }).connect(noiseVol.volume as any);
    swellLfo.start();

    return () => {
      noise.stop();
      noise.dispose();
      lowpass.dispose();
      noiseVol.dispose();
      lfo1.stop();
      lfo1.dispose();
      lfo2.stop();
      lfo2.dispose();
      swellLfo.stop();
      swellLfo.dispose();
    };
  }

  // ── EVENT SUBSCRIPTION ──────────────────────────────────────────────────

  private subscribeToEvents(): void {
    // Planet activation triggers audio
    universeBus.subscribe("PLANET_ACTIVATED", (event) => {
      this.playSignature(event.planetId);
    });

    // Planet completion stops its audio
    universeBus.subscribe("PLANET_COMPLETED", (event) => {
      this.stopSignature(event.planetId);
    });

    // Audio state toggle
    universeBus.subscribe("AUDIO_STATE_CHANGED", (event) => {
      if (event.type === "AUDIO_STATE_CHANGED" && event.active) {
        this.resume();
      } else {
        this.suspend();
      }
    });
  }
}

/** Singleton — entire app shares one audio manager */
export const audioManager = new AudioManager();

/**
 * ─── PROGRESSION ENGINE — Pure Functions & Types (Client-Safe) ────────────────
 *
 * This file contains ONLY pure functions with zero side effects.
 * SAFE to import from Client Components.
 *
 * DB-dependent functions live in progression-engine.server.ts
 */

import { planetRegistry, type PlanetId, type PlanetState } from "./planet-registry";

// ─── TYPES ────────────────────────────────────────────────────────────────────

export interface PlayerProgression {
  /** DB row ID */
  id: string;
  /** Schema version for evolution safety */
  _schemaVersion?: number;
  /** Planets the player has completed */
  completed: PlanetId[];
  /** Currently active planet (if any) */
  activePlanet: PlanetId | null;
  /** Planets available for activation */
  available: PlanetId[];
  /** Active hints (max 2) */
  activeHints: Hint[];
  /** Timestamp of last progression change (for cooldown) */
  lastProgressionAt: number;
  /** Total planets completed (derived from completed.length) */
  totalCompleted: number;
}

export interface Hint {
  id: string;
  planetId: PlanetId;
  text: string;
  createdAt: number;
}

export type ActionResult =
  | { success: true; progression: PlayerProgression }
  | { success: false; error: string };

export type HintResult =
  | { success: true; progression: PlayerProgression; hint: Hint }
  | { success: false; error: string };

// ─── CONSTANTS ────────────────────────────────────────────────────────────────

/** Schema version — bump when PlayerProgression shape changes */
export const SCHEMA_VERSION = 1;

/** Minimum milliseconds between progression changes */
export const PROGRESSION_COOLDOWN_MS = 2000;

/** Maximum active hints at any time */
export const MAX_ACTIVE_HINTS = 2;

// ─── INITIAL STATE ────────────────────────────────────────────────────────────

/** The canonical empty progression. ALL initialization MUST use this. */
const EMPTY_PROGRESSION: PlayerProgression = {
  id: "",
  completed: [],
  activePlanet: null,
  available: ["nexus"],
  activeHints: [],
  lastProgressionAt: 0,
  totalCompleted: 0,
  _schemaVersion: SCHEMA_VERSION,
};

/**
 * Pure factory — default progression for a new user.
 * Does NOT touch the DB.
 */
export function createInitialProgression(): PlayerProgression {
  return { ...EMPTY_PROGRESSION };
}

// ─── RUNTIME NORMALIZATION ────────────────────────────────────────────────────

/**
 * Normalize potentially corrupted or partial progression data.
 *
 * Handles:
 *   - undefined/missing arrays → []
 *   - null activePlanet preserved
 *   - missing numeric fields → 0
 *   - schema version validation
 *   - invalid PlanetIds filtered from arrays
 *
 * This is the SINGLE normalization boundary. Every entry point
 * (API response, localStorage, mock data) MUST pass through here.
 */
export function normalizeProgression(
  raw: Partial<PlayerProgression> | null | undefined
): PlayerProgression {
  const defaults = EMPTY_PROGRESSION;

  if (!raw || typeof raw !== "object") {
    return { ...defaults };
  }

  // Defensive: every array field gets normalized
  const completed = Array.isArray(raw.completed)
    ? raw.completed.filter((id): id is PlanetId => typeof id === "string" && id in planetRegistry)
    : [...defaults.completed];

  const available = Array.isArray(raw.available)
    ? raw.available.filter((id): id is PlanetId => typeof id === "string" && id in planetRegistry)
    : [...defaults.available];

  const activeHints = Array.isArray(raw.activeHints)
    ? raw.activeHints.filter(
        (h): h is Hint =>
          typeof h === "object" &&
          h !== null &&
          typeof h.id === "string" &&
          typeof h.planetId === "string" &&
          typeof h.text === "string" &&
          typeof h.createdAt === "number"
      )
    : [];

  // Schema version: migrate if needed (future-proof)
  const version = typeof raw._schemaVersion === "number" ? raw._schemaVersion : 0;

  return {
    id: typeof raw.id === "string" ? raw.id : defaults.id,
    _schemaVersion: SCHEMA_VERSION,
    completed,
    activePlanet:
      typeof raw.activePlanet === "string" && raw.activePlanet in planetRegistry
        ? (raw.activePlanet as PlanetId)
        : null,
    available,
    activeHints,
    lastProgressionAt:
      typeof raw.lastProgressionAt === "number" ? raw.lastProgressionAt : 0,
    totalCompleted:
      typeof raw.totalCompleted === "number" ? raw.totalCompleted : completed.length,
  };
}

// ─── STATE CALCULATION (pure functions — no DB, no side effects) ──────────────

/**
 * Calculate a planet's current state based on player progression.
 * Pure function — no side effects, no mutation.
 */
export function calculatePlanetState(
  planetId: PlanetId,
  progression: PlayerProgression | null | undefined
): PlanetState {
  // Defensive guard: progression may be null/undefined during first render
  // or if API response hasn't arrived yet
  if (!progression) return "undiscovered";

  // Defensive: ensure arrays exist even if JSON deserialization is partial
  const completed: PlanetId[] = Array.isArray(progression.completed) ? progression.completed : [];
  const available: PlanetId[] = Array.isArray(progression.available) ? progression.available : [];

  if (!allRequiresMet(planetId, progression, completed)) {
    return "undiscovered";
  }
  if (planetId === progression.activePlanet) {
    return "active";
  }
  if (completed.includes(planetId)) {
    return "completed";
  }
  if (available.includes(planetId)) {
    return "available";
  }
  return "undiscovered";
}

/**
 * Check if all prerequisite planets for `planetId` have been completed.
 */
function allRequiresMet(
  planetId: PlanetId,
  progression: PlayerProgression,
  completed: PlanetId[]
): boolean {
  const planet = planetRegistry[planetId];
  if (planet.requires.length === 0) return true;
  return planet.requires.every((reqId) => completed.includes(reqId));
}

// ─── DIAGNOSTIC (pure functions) ──────────────────────────────────────────────

/**
 * Get a summary of all planet states for the current progression.
 */
export function getUniverseSnapshot(
  progression: PlayerProgression
): Record<PlanetId, PlanetState> {
  const snapshot: Record<string, PlanetState> = {};
  for (const id of Object.keys(planetRegistry) as PlanetId[]) {
    snapshot[id] = calculatePlanetState(id, progression);
  }
  return snapshot as Record<PlanetId, PlanetState>;
}

/**
 * Count planets by state.
 */
export function countByState(
  progression: PlayerProgression
): Record<PlanetState, number> {
  const snapshot = getUniverseSnapshot(progression);
  const counts: Record<PlanetState, number> = {
    undiscovered: 0,
    available: 0,
    active: 0,
    completed: 0,
  };
  for (const state of Object.values(snapshot)) {
    counts[state]++;
  }
  return counts;
}

/**
 * MENTE.AI — Sistema Central de Eventos XP (Fase 2)
 * src/lib/xp-webhook.ts
 *
 * Responsabilidades:
 *  1. Recebe eventos tipados de XP (AGENTE_INTERACAO, COMBINACAO_DESCOBERTA, etc.)
 *  2. Executa transação Drizzle ATÔMICA: userXp + userAgentProgress simultaneamente
 *  3. Verifica conquistas (badges) após cada ganho de XP
 *  4. Retorna XpEventResult com todos os dados para o chamador usar (SSE / resposta JSON)
 *
 * DESIGN: Não usa cache global (incompatível com serverless Vercel).
 * O chamador (route handler) decide como propagar o resultado para o cliente.
 */

import { db } from "@/lib/db";
import { userXp, userAgentProgress } from "@/lib/db/schema";
import { XP_REWARDS } from "@/lib/xp";
import { eq, and } from "drizzle-orm";
import crypto from "crypto";
import {
  logXPGain,
  logBadgeEarned,
  logStreakUpdate,
  logError,
} from "@/lib/gamification-logger";

// ─── Tipos de eventos ──────────────────────────────────────────────────────────

export type XpEventType = keyof typeof XP_REWARDS;

/** Metadata opcional por tipo de evento */
interface XpEventMetadata {
  agentId?: string;          // Obrigatório em eventos de agente
  combinationId?: string;    // Obrigatório em eventos de combinação
  duracaoSegundos?: number;  // Duração da interação (métricas)
}

export interface XpEvent {
  userId: number;
  tipo: XpEventType;
  metadata?: XpEventMetadata;
}

/** Resultado retornado ao chamador após processar o evento */
export interface XpEventResult {
  sucesso: boolean;
  xpGanho: number;
  xpTotalAtualizado: number;
  xpSemanaAtualizado: number;
  streakDias: number;
  badgesDesbloqueadas: string[];
  /** Novo nível de interação com o agente (0-5), se aplicável */
  nivelInteracaoAgente?: number;
  /** true se o agente foi concluído neste evento */
  agenteConcluido?: boolean;
  erro?: string;
}

// ─── Constantes de gamificação ────────────────────────────────────────────────

/** Interações necessárias para cada nível de relacionamento com um agente */
const NIVEL_INTERACAO_THRESHOLDS = [0, 2, 5, 10, 20, 35] as const; // nível 0-5

/** Regras de badges: id → condição avaliada sobre XP total */
const REGRAS_BADGES: { id: string; label: string; xpNecessario: number }[] = [
  { id: "explorador",    label: "Explorador",          xpNecessario: 50   },
  { id: "aprendiz",      label: "Aprendiz da IA",       xpNecessario: 150  },
  { id: "conector",      label: "Conector de Agentes",  xpNecessario: 300  },
  { id: "investigador",  label: "Investigador",         xpNecessario: 500  },
  { id: "mestre",        label: "Mestre MENTE.AI",      xpNecessario: 1000 },
];

// ─── Helpers internos ─────────────────────────────────────────────────────────

function getMondayAtual(): string {
  const now = new Date();
  const day = now.getDay();
  const diff = now.getDate() - day + (day === 0 ? -6 : 1);
  const monday = new Date(now);
  monday.setDate(diff);
  return monday.toISOString().split("T")[0];
}

function calcularNivelInteracao(interacoesTotal: number): number {
  for (let nivel = NIVEL_INTERACAO_THRESHOLDS.length - 1; nivel >= 0; nivel--) {
    if (interacoesTotal >= NIVEL_INTERACAO_THRESHOLDS[nivel]) return nivel;
  }
  return 0;
}

function verificarBadgesDesbloqueadas(xpAntes: number, xpDepois: number): string[] {
  return REGRAS_BADGES
    .filter((b) => xpAntes < b.xpNecessario && xpDepois >= b.xpNecessario)
    .map((b) => b.id);
}

// ─── Função principal: emitXpEvent ────────────────────────────────────────────

/**
 * Processa um evento XP em transação atômica.
 *
 * Para eventos de agente, atualiza TANTO userXp (global) QUANTO
 * userAgentProgress (por agente) no mesmo commit — sem risco de inconsistência.
 */
export async function emitXpEvent(evento: XpEvent): Promise<XpEventResult> {
  const { userId, tipo, metadata } = evento;
  const xpGanho = XP_REWARDS[tipo];
  const hoje = new Date().toISOString().split("T")[0];
  const monday = getMondayAtual();

  try {
    const resultado = await db.transaction(async (tx) => {
      // ── 1. Atualizar userXp (global) ────────────────────────────────────────
      const [xpAtual] = await tx
        .select()
        .from(userXp)
        .where(eq(userXp.userId, userId))
        .limit(1);

      let xpTotal: number;
      let xpThisWeek: number;
      let streakDias: number;

      if (!xpAtual) {
        // Primeiro evento do usuário
        await tx.insert(userXp).values({
          id: crypto.randomUUID(),
          userId,
          xpTotal: xpGanho,
          xpThisWeek: xpGanho,
          streakDays: 1,
          lastActivityDate: hoje,
          weekStartDate: monday,
        });
        xpTotal = xpGanho;
        xpThisWeek = xpGanho;
        streakDias = 1;
      } else {
        const lastDate = xpAtual.lastActivityDate ?? null;
        const diffDias = lastDate
          ? Math.floor((new Date(hoje).getTime() - new Date(lastDate).getTime()) / 86_400_000)
          : 999;

        streakDias = diffDias === 0 ? (xpAtual.streakDays ?? 1)
                   : diffDias === 1 ? (xpAtual.streakDays ?? 0) + 1
                   : 1;

        const semanaResetou = xpAtual.weekStartDate !== monday;
        xpTotal    = (xpAtual.xpTotal ?? 0) + xpGanho;
        xpThisWeek = semanaResetou ? xpGanho : (xpAtual.xpThisWeek ?? 0) + xpGanho;

        await tx
          .update(userXp)
          .set({ xpTotal, xpThisWeek, streakDays: streakDias, lastActivityDate: hoje, weekStartDate: monday })
          .where(eq(userXp.userId, userId));
      }

      // ── 2. Atualizar userAgentProgress (por agente) — se aplicável ──────────
      let nivelInteracaoAgente: number | undefined;
      let agenteConcluido = false;

      const agentId = metadata?.agentId;
      const ehEventoDeAgente =
        tipo === "AGENTE_INTERACAO" ||
        tipo === "AGENTE_DESBLOQUEADO" ||
        tipo === "AGENTE_COMPLETADO";

      if (agentId && ehEventoDeAgente) {
        const [progressoAtual] = await tx
          .select()
          .from(userAgentProgress)
          .where(and(eq(userAgentProgress.userId, userId), eq(userAgentProgress.agentId, agentId)))
          .limit(1);

        if (!progressoAtual) {
          // Primeiro contato com este agente
          const eDesbloqueio = tipo === "AGENTE_DESBLOQUEADO";
          await tx.insert(userAgentProgress).values({
            id: crypto.randomUUID(),
            userId,
            agentId,
            desbloqueado: eDesbloqueio,
            desbloqueadoEm: eDesbloqueio ? new Date() : null,
            interacoesTotal: tipo === "AGENTE_INTERACAO" ? 1 : 0,
            xpGanho,
            nivelInteracao: 0,
          });
          nivelInteracaoAgente = 0;
        } else {
          const novasInteracoes =
            tipo === "AGENTE_INTERACAO"
              ? progressoAtual.interacoesTotal + 1
              : progressoAtual.interacoesTotal;

          const novoNivel = calcularNivelInteracao(novasInteracoes);
          const concluido = novasInteracoes >= NIVEL_INTERACAO_THRESHOLDS[5];

          const update: Partial<typeof userAgentProgress.$inferInsert> = {
            interacoesTotal: novasInteracoes,
            xpGanho: progressoAtual.xpGanho + xpGanho,
            nivelInteracao: novoNivel,
          };

          if (tipo === "AGENTE_DESBLOQUEADO" && !progressoAtual.desbloqueado) {
            update.desbloqueado = true;
            update.desbloqueadoEm = new Date();
          }
          if (concluido && !progressoAtual.completadoEm) {
            update.completadoEm = new Date();
            agenteConcluido = true;
          }

          await tx
            .update(userAgentProgress)
            .set(update)
            .where(eq(userAgentProgress.id, progressoAtual.id));

          nivelInteracaoAgente = novoNivel;
        }
      }

      // ── 3. Verificar badges desbloqueadas ────────────────────────────────────
      const xpAntes = xpTotal - xpGanho;
      const badges = verificarBadgesDesbloqueadas(xpAntes, xpTotal);

      // Logging estruturado
      logXPGain(
        {
          xpGanho,
          xpTotal,
          xpSemana: xpThisWeek,
          tipoEvento: evento.tipo,
          agentId: metadata?.agentId,
          combinationId: metadata?.combinationId,
        },
        userId,
      );

      if (badges.length > 0) {
        for (const badgeId of badges) {
          const badge = REGRAS_BADGES.find((b) => b.id === badgeId);
          if (badge) {
            logBadgeEarned(
              {
                badgeId,
                badgeLabel: badge.label,
                xpTotal,
              },
              userId,
            );
          }
        }
      }

      logStreakUpdate(
        {
          streakDias,
          ultimaAtividade: hoje,
        },
        userId,
      );

      return {
        xpTotal,
        xpThisWeek,
        streakDias,
        badges,
        nivelInteracaoAgente,
        agenteConcluido,
      };
    });

    return {
      sucesso: true,
      xpGanho,
      xpTotalAtualizado: resultado.xpTotal,
      xpSemanaAtualizado: resultado.xpThisWeek,
      streakDias: resultado.streakDias,
      badgesDesbloqueadas: resultado.badges,
      nivelInteracaoAgente: resultado.nivelInteracaoAgente,
      agenteConcluido: resultado.agenteConcluido,
    };

  } catch (erro) {
    console.error(`[xp-webhook] Falha ao processar evento ${tipo} para userId=${userId}:`, erro);
    return {
      sucesso: false,
      xpGanho: 0,
      xpTotalAtualizado: 0,
      xpSemanaAtualizado: 0,
      streakDias: 0,
      badgesDesbloqueadas: [],
      erro: erro instanceof Error ? erro.message : String(erro),
    };
  }
}

import { db } from "@/lib/db";
import { userXp } from "@/lib/db/schema";
import { eq } from "drizzle-orm";
import crypto from "crypto";

export const XP_REWARDS = {
  // ─── Fase 1 (MVP) ───────────────────────────────────────────────────────────
  NOTA_CRIADA:          10,
  EXPERIMENTO_CONCLUIDO: 25,
  LOGIN_DIARIO:          5,
  PERFIL_COMPLETO:      50,

  // ─── Fase 2 — Agentes ───────────────────────────────────────────────────────
  /** Primeira interação com um agente recém-desbloqueado */
  AGENTE_DESBLOQUEADO:   30,
  /** A cada nova interação com qualquer agente */
  AGENTE_INTERACAO:      15,
  /** Atingiu 10 interações com um mesmo agente (nível de relacionamento max) */
  AGENTE_COMPLETADO:    100,

  // ─── Fase 2 — Combinações ───────────────────────────────────────────────────
  /** Primeira vez que o usuário usa uma combinação de agentes */
  COMBINACAO_DESCOBERTA: 50,
  /** Usa uma combinação já descoberta (bônus menor) */
  COMBINACAO_USADA:      10,
} as const;

function getMondayOfCurrentWeek(): string {
  const now = new Date();
  const day = now.getDay();
  const diff = now.getDate() - day + (day === 0 ? -6 : 1);
  const monday = new Date(now);
  monday.setDate(diff);
  return monday.toISOString().split("T")[0];
}

export async function addXp(userId: number, amount: number, _reason: string): Promise<void> {
  const today = new Date().toISOString().split("T")[0];
  const monday = getMondayOfCurrentWeek();

  const existing = await db.select().from(userXp).where(eq(userXp.userId, userId)).limit(1);

  if (existing.length === 0) {
    await db.insert(userXp).values({
      id: crypto.randomUUID(),
      userId,
      xpTotal: amount,
      xpThisWeek: amount,
      streakDays: 1,
      lastActivityDate: today,
      weekStartDate: monday,
    });
    return;
  }

  const record = existing[0];
  const lastDate = record.lastActivityDate ?? null;
  const lastWeek = record.weekStartDate ?? null;

  const diffDays = lastDate
    ? Math.floor((new Date(today).getTime() - new Date(lastDate).getTime()) / 86400000)
    : 999;

  const newStreak =
    diffDays === 0 ? record.streakDays! :
    diffDays === 1 ? record.streakDays! + 1 : 1;

  const newXpWeek = lastWeek !== monday ? amount : record.xpThisWeek! + amount;

  await db.update(userXp).set({
    xpTotal: record.xpTotal! + amount,
    xpThisWeek: newXpWeek,
    streakDays: newStreak,
    lastActivityDate: today,
    weekStartDate: monday,
  }).where(eq(userXp.userId, userId));
}

